const WORKED_EXAMPLES={"N01":{"default":"transfer","variants":{"transfer":{"title":"Zwei Rundungen erzählen unterschiedlich viel","prompt":"Eine Anzeigetafel meldet „etwa 8 000 Gäste“, auf Tausender gerundet. Eine zweite meldet „etwa 7 960 Gäste“, auf Zehner gerundet. Welche ganzen Besucherzahlen könnten zu beiden Meldungen passen?","prerequisites":[],"blocks":[{"type":"H","value":"Zwei Rundungen erzählen unterschiedlich viel"},{"type":"T","value":"Eine Anzeigetafel meldet „etwa 8 000 Gäste“, auf Tausender gerundet. Eine zweite meldet „etwa 7 960 Gäste“, auf Zehner gerundet. Welche ganzen Besucherzahlen könnten zu beiden Meldungen passen?"},{"type":"H","value":"1. Rundungsstellen lesen"},{"type":"T","value":"Die erste Angabe ist auf Tausender gerundet, die zweite auf Zehner. Wir suchen Zahlen rückwärts aus den gerundeten Angaben."},{"type":"H","value":"2. Beide Bereiche bestimmen"},{"type":"T","value":"Zu 8 000 gehören beim Runden auf Tausender die ganzen Zahlen von 7 500 bis 8 499. Zu 7 960 gehören beim Runden auf Zehner 7 955 bis 7 964."},{"type":"H","value":"3. Gemeinsamen Bereich und Grenzen prüfen"},{"type":"T","value":"Alle Zahlen von 7 955 bis 7 964 erfüllen beide Meldungen. 7 954 wird schon zu 7 950; 7 965 wird zu 7 970. Die genauere Rundung schränkt den Bereich stärker ein."}]},"source-0":{"title":"Eine Ziffer – verschiedene Werte","prompt":"","blocks":[{"type":"H","value":"Eine Ziffer – verschiedene Werte"},{"type":"T","value":"In <b>43 674</b> bedeutet die erste 4 vier Zehntausender, die letzte 4 nur vier Einer. Eine <b>Ziffer</b> ist ein einzelnes Zeichen; die ganze <b>Zahl</b> entsteht aus den Stellenwerten. Deshalb vergleichen wir Zahlen von der größten Stelle aus."},{"type":"M","value":"43\\,674=4\\cdot10\\,000+3\\cdot1000+6\\cdot100+7\\cdot10+4"},{"type":"T","value":"43 674 ist größer als 43 647: Bis zu den Hundertern ist alles gleich, dann entscheidet 7 Zehner gegenüber 4 Zehnern."}],"prerequisites":[]},"source-1":{"title":"Runden heißt: den näheren Nachbarn wählen","prompt":"","blocks":[{"type":"H","value":"Runden heißt: den näheren Nachbarn wählen"},{"type":"T","value":"Beim Runden auf Hunderter liegen die Nachbarn bei 43 600 und 43 700. Die Mitte ist 43 650. Unsere Zahl liegt darüber, also näher an 43 700. Das Zeichen <b>≈</b> heißt „ungefähr gleich“; die Zahl wird durch einen Näherungswert ersetzt."},{"type":"V","value":"N01"},{"type":"M","value":"43\\,674\\approx43\\,700\\quad\\mathrm{(auf\\ Hunderter)}"},{"type":"T","value":"Rückwärts können viele Zahlen gemeint sein: Jede ganze Zahl von 43 650 bis 43 749 wird zu 43 700 gerundet. 43 750 gehört schon zum nächsten Hunderter. Die Rundungsstelle muss deshalb immer genannt werden."}],"prerequisites":[]}},"taskExamples":{"N01_MINI":"transfer","N01_L4_01":"transfer","N01_L4_02":"transfer","N01_L4_03":"transfer","N01_L4_04":"transfer","N01_L4_05":"transfer","N01_POOL_01":"transfer","N01_POOL_02":"transfer","N01_POOL_03":"transfer","N01_POOL_04":"transfer","N01_NEU_01":"transfer","N01_NEU_02":"transfer","N01_NEU_03":"transfer","N01_NEU_04":"transfer","N01_NEU_05":"transfer","N01_NEU_06":"transfer","N01_TEST_01":"transfer","N01_TEST_02":"transfer","N01_TEST_03":"transfer","N01_NEU_07":"transfer","N01_NEU_08":"transfer","N01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"N02":{"default":"transfer","variants":{"transfer":{"title":"Eine Lieferung mit Rest aufteilen","prompt":"Eine Schule hat 53 Klebestifte. Fünf Klassen bekommen gleich viele; der Rest bleibt im Materialschrank. Später kommen 12 weitere Stifte. Wie wird die neue Verteilung aus der alten Rechnung sichtbar?","prerequisites":["N03"],"blocks":[{"type":"H","value":"Eine Lieferung mit Rest aufteilen"},{"type":"T","value":"Eine Schule hat 53 Klebestifte. Fünf Klassen bekommen gleich viele; der Rest bleibt im Materialschrank. Später kommen 12 weitere Stifte. Wie wird die neue Verteilung aus der alten Rechnung sichtbar?"},{"type":"H","value":"1. Die erste Verteilung beschreiben"},{"type":"M","value":"53=5\\cdot10+3"},{"type":"T","value":"Jede Klasse bekommt 10 Stifte; 3 bleiben übrig. Der Rest ist kleiner als die Anzahl der Klassen."},{"type":"H","value":"2. Die Nachlieferung zum Rest legen"},{"type":"M","value":"3+12=15=5\\cdot3"},{"type":"T","value":"Aus den 15 noch unverteilten Stiften bekommt jede Klasse 3 weitere."},{"type":"H","value":"3. Gesamtrechnung prüfen"},{"type":"M","value":"53+12=65=5\\cdot13"},{"type":"T","value":"Jede Klasse hat 13 Stifte, jetzt bleibt nichts übrig. Die Multiplikation kontrolliert sowohl die Verteilung als auch den Umgang mit dem Rest."}]},"source-0":{"title":"Rechnen mit Stellenwerten und Umkehraufgaben","prompt":"","blocks":[{"type":"H","value":"Rechnen mit Stellenwerten und Umkehraufgaben"},{"type":"T","value":"Bei 368 + 247 heißen die Zahlen <b>Summanden</b>, das Ergebnis <b>Summe</b>. Wir bündeln: 8 + 7 = 15 Einer sind 1 Zehner und 5 Einer. Dieser zusätzliche Zehner ist der <b>Übertrag</b>. Danach ergeben 6 + 4 + 1 Zehner wieder 1 Hunderter und 1 Zehner."},{"type":"M","value":"368+247=615"},{"type":"T","value":"Subtraktion fragt nach einer fehlenden Menge. Für 615 − 247 entbündeln wir einen Zehner in 10 Einer: 15 − 7 = 8; dann einen Hunderter in 10 Zehner: 10 − 4 = 6; schließlich 5 − 2 = 3. Die <b>Differenz</b> ist 368. Die Addition prüft sie."}],"prerequisites":["N01"]},"source-1":{"title":"Eine Multiplikation verstehen und umkehren","prompt":"","blocks":[{"type":"H","value":"Eine Multiplikation verstehen und umkehren"},{"type":"T","value":"Bei 24 · 13 heißen 24 und 13 <b>Faktoren</b>, das Ergebnis <b>Produkt</b>. 13 Gruppen sind 10 Gruppen und 3 Gruppen. So geht beim Zerlegen keine Gruppe verloren."},{"type":"M","value":"24\\cdot13=24\\cdot10+24\\cdot3=240+72=312"},{"type":"V","value":"N02"},{"type":"T","value":"Bei 312 : 24 ist 312 der <b>Dividend</b>, 24 der <b>Divisor</b> und 13 der <b>Quotient</b>. Gesucht ist die Anzahl der 24er-Gruppen. Division und Multiplikation prüfen sich gegenseitig."},{"type":"M","value":"312:24=13\\qquad13\\cdot24=312"}],"prerequisites":["N01"]}},"taskExamples":{"N02_MINI":"transfer","N02_L4_01":"transfer","N02_L4_02":"transfer","N02_L4_03":"transfer","N02_L4_04":"transfer","N02_L4_05":"transfer","N02_POOL_01":"transfer","N02_POOL_02":"transfer","N02_POOL_03":"transfer","N02_POOL_04":"transfer","N02_NEU_01":"transfer","N02_NEU_02":"transfer","N02_NEU_03":"transfer","N02_NEU_04":"transfer","N02_NEU_05":"transfer","N02_NEU_06":"transfer","N02_TEST_01":"transfer","N02_TEST_02":"transfer","N02_TEST_03":"transfer","N02_NEU_07":"transfer","N02_NEU_08":"transfer","N02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"N03":{"default":"transfer","variants":{"transfer":{"title":"Pakete und gemeinsame Termine unterscheiden","prompt":"Für ein Fest gibt es 28 Äpfel und 42 Birnen. Daneben klingeln zwei Erinnerungen jetzt gemeinsam und danach alle 28 beziehungsweise 42 Minuten. Die gleichen Zahlen führen zu unterschiedlichen Fragen.","prerequisites":["N02"],"blocks":[{"type":"H","value":"Pakete und gemeinsame Termine unterscheiden"},{"type":"T","value":"Für ein Fest gibt es 28 Äpfel und 42 Birnen. Daneben klingeln zwei Erinnerungen jetzt gemeinsam und danach alle 28 beziehungsweise 42 Minuten. Die gleichen Zahlen führen zu unterschiedlichen Fragen."},{"type":"H","value":"1. Gleich gefüllte Pakete suchen"},{"type":"T","value":"Bei möglichst vielen gleichen Paketen müssen beide Obstzahlen durch die Paketanzahl teilbar sein."},{"type":"M","value":"28=2\\cdot2\\cdot7;\\qquad42=2\\cdot3\\cdot7"},{"type":"T","value":"Die gemeinsamen Faktoren ergeben 14. Es sind 14 Pakete mit je 2 Äpfeln und 3 Birnen möglich."},{"type":"H","value":"2. Gleichzeitigen Termin suchen"},{"type":"T","value":"Hier brauchen wir ein Vielfaches beider Takte: 28, 56, 84 … und 42, 84 … . Nach 84 Minuten treffen die Signale erstmals wieder zusammen."},{"type":"H","value":"3. Die Wahl begründen"},{"type":"T","value":"Pakete zerlegen vorhandene Mengen: gemeinsamer Teiler. Termine wiederholen ganze Takte: gemeinsames Vielfaches. Die Geschichte entscheidet, welche Zahl gesucht ist."}]},"source-0":{"title":"18 und 24 in Bausteine zerlegen","prompt":"","blocks":[{"type":"H","value":"18 und 24 in Bausteine zerlegen"},{"type":"T","value":"Ein <b>Teiler</b> teilt eine Zahl ohne Rest. Ein <b>Vielfaches</b> entsteht durch Multiplikation mit einer ganzen Zahl. Eine <b>Primzahl</b> hat genau zwei positive Teiler: 1 und sich selbst. 2 und 3 sind Primzahlen; 1 ist keine."},{"type":"M","value":"18=2\\cdot3\\cdot3\\qquad24=2\\cdot2\\cdot2\\cdot3"},{"type":"T","value":"Die Faktoren in dieser Zerlegung sind <b>Primfaktoren</b>. Beide Zahlen enthalten eine 2 und eine 3. Ihr Produkt 6 ist der <b>größte gemeinsame Teiler (ggT)</b>. Mehr gemeinsame Primfaktoren gibt es nicht."},{"type":"M","value":"\\mathrm{ggT}(18,24)=6\\qquad18:6=3;\\quad24:6=4"},{"type":"T","value":"Für das <b>kleinste gemeinsame Vielfache (kgV)</b> brauchen wir alle Bausteine beider Zahlen: drei Zweien und zwei Dreien. Damit lässt sich sowohl 18 als auch 24 als Faktor herausnehmen."},{"type":"M","value":"\\mathrm{kgV}(18,24)=2\\cdot2\\cdot2\\cdot3\\cdot3=72"},{"type":"V","value":"N03"},{"type":"T","value":"Zwei Busse fahren im 18- bzw. 24-Minuten-Takt gleichzeitig los. Das erste erneute Zusammentreffen liegt nach 72 Minuten: 4 · 18 = 3 · 24. Wir suchen hier ein gemeinsames Vielfaches, weil ganze Takte vergehen müssen."}],"prerequisites":["N02"]}},"taskExamples":{"N03_MINI":"transfer","N03_L4_01":"transfer","N03_L4_02":"transfer","N03_L4_03":"transfer","N03_L4_04":"transfer","N03_L4_05":"transfer","N03_POOL_01":"transfer","N03_POOL_02":"transfer","N03_POOL_03":"transfer","N03_POOL_04":"transfer","N03_NEU_01":"transfer","N03_NEU_02":"transfer","N03_NEU_03":"transfer","N03_NEU_04":"transfer","N03_NEU_05":"transfer","N03_NEU_06":"transfer","N03_TEST_01":"transfer","N03_TEST_02":"transfer","N03_TEST_03":"transfer","N03_NEU_07":"transfer","N03_NEU_08":"transfer","N03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"N04":{"default":"transfer","variants":{"transfer":{"title":"Eine Rechnung rückwärts zum Text lesen","prompt":"Drei Gruppen kaufen je zwei Eintrittskarten zu 7 Euro. Jede Gruppe hat einen Gutschein über 4 Euro. Vergleiche diesen Einkauf mit nur einem einzigen Gutschein für alle Gruppen.","prerequisites":["N02"],"blocks":[{"type":"H","value":"Eine Rechnung rückwärts zum Text lesen"},{"type":"T","value":"Drei Gruppen kaufen je zwei Eintrittskarten zu 7 Euro. Jede Gruppe hat einen Gutschein über 4 Euro. Vergleiche diesen Einkauf mit nur einem einzigen Gutschein für alle Gruppen."},{"type":"H","value":"1. Die gemeinsame Grundrechnung lesen"},{"type":"M","value":"3\\cdot(2\\cdot7)=42"},{"type":"T","value":"Zuerst kostet ein Kartenpaar 14 Euro, dann kosten drei Paare 42 Euro."},{"type":"H","value":"2. Je Gruppe einen Gutschein einsetzen"},{"type":"M","value":"3\\cdot(2\\cdot7-4)=3\\cdot10=30"},{"type":"T","value":"Die Subtraktion gehört in die Klammer, weil sie für jede Gruppe gilt."},{"type":"H","value":"3. Nur einen Gutschein einsetzen"},{"type":"M","value":"3\\cdot2\\cdot7-4=42-4=38"},{"type":"T","value":"Die Klammerposition bildet eine andere Geschichte ab. Beide Ergebnisse folgen derselben Regel: Klammern vor Punkt vor Strich."}]},"source-0":{"title":"Der Rechenplan steckt in der Schreibweise","prompt":"","blocks":[{"type":"H","value":"Der Rechenplan steckt in der Schreibweise"},{"type":"T","value":"Wir berechnen 60 − 2 · (3 + 2)². Die <b>Klammer</b> fasst eine Summe zu einer Einheit zusammen. Die <b>Potenz</b> bedeutet, diese ganze Einheit zweimal zu multiplizieren. Deshalb dürfen wir nicht zuerst 60 − 2 rechnen."},{"type":"M","value":"60-2\\cdot(3+2)^2=60-2\\cdot5^2"},{"type":"M","value":"=60-2\\cdot25=60-50=10"},{"type":"T","value":"Die Reihenfolge ist: Klammer, Potenz, Punktrechnung, Strichrechnung. „Punkt“ meint Multiplikation und Division, „Strich“ Addition und Subtraktion. Diese Vereinbarung macht einen Term ohne zusätzliche Worte eindeutig."}],"prerequisites":["N02"]},"source-1":{"title":"Gleicher Rang: von links nach rechts","prompt":"","blocks":[{"type":"H","value":"Gleicher Rang: von links nach rechts"},{"type":"M","value":"24:3\\cdot2=8\\cdot2=16\\qquad24:(3\\cdot2)=4"},{"type":"T","value":"Multiplikation und Division sind <b>gleichrangig</b>. Links wird daher zuerst geteilt; rechts erzwingt die Klammer zuerst die Multiplikation. „Mal immer vor Geteilt“ wäre falsch."},{"type":"T","value":"Rückwärts wollen wir aus 2 + 3 · 4 den Wert 20 erhalten. Weil 20 : 4 = 5 ist, muss vor dem Multiplizieren die Summe 2 + 3 entstehen. Genau darum setzen wir die Klammer um diese Summe."},{"type":"M","value":"(2+3)\\cdot4=5\\cdot4=20"}],"prerequisites":["N02"]}},"taskExamples":{"N04_MINI":"transfer","N04_L4_01":"transfer","N04_L4_02":"transfer","N04_L4_03":"transfer","N04_L4_04":"transfer","N04_L4_05":"transfer","N04_POOL_01":"transfer","N04_POOL_02":"transfer","N04_POOL_03":"transfer","N04_POOL_04":"transfer","N04_NEU_01":"transfer","N04_NEU_02":"transfer","N04_NEU_03":"transfer","N04_NEU_04":"transfer","N04_NEU_05":"transfer","N04_NEU_06":"transfer","N04_TEST_01":"transfer","N04_TEST_02":"transfer","N04_TEST_03":"transfer","N04_NEU_07":"transfer","N04_NEU_08":"transfer","N04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"N05":{"default":"transfer","variants":{"transfer":{"title":"Zwei Wege prüfen denselben Einkauf","prompt":"Für ein Projekt werden 12 Päckchen mit jeweils 25 Perlen gekauft. Ein Päckchen ist beschädigt und enthält nur 19 Perlen. Zähle geschickt auf zwei Wegen.","prerequisites":["N04"],"blocks":[{"type":"H","value":"Zwei Wege prüfen denselben Einkauf"},{"type":"T","value":"Für ein Projekt werden 12 Päckchen mit jeweils 25 Perlen gekauft. Ein Päckchen ist beschädigt und enthält nur 19 Perlen. Zähle geschickt auf zwei Wegen."},{"type":"H","value":"1. Mit vollen Päckchen beginnen"},{"type":"M","value":"12\\cdot25=3\\cdot(4\\cdot25)=300"},{"type":"T","value":"Vier 25er bilden 100. Das verbindet Vertauschen und Zusammenfassen."},{"type":"H","value":"2. Die Abweichung korrigieren"},{"type":"M","value":"300-(25-19)=300-6=294"},{"type":"T","value":"Es fehlen nicht 19 Perlen, sondern 6 gegenüber einem vollen Päckchen."},{"type":"H","value":"3. Mit einer zweiten Zerlegung kontrollieren"},{"type":"M","value":"11\\cdot25+19=275+19=294"},{"type":"T","value":"Beide Zerlegungen zählen dieselbe Gesamtmenge. Der Überschlag „etwas weniger als 300“ passt."}]},"source-0":{"title":"Rechengesetze machen günstige Zahlen sichtbar","prompt":"","blocks":[{"type":"H","value":"Rechengesetze machen günstige Zahlen sichtbar"},{"type":"T","value":"25 · 17 · 4 wirkt zunächst umständlich. Beim Multiplizieren dürfen wir Faktoren vertauschen (<b>Kommutativgesetz</b>) und anders zusammenfassen (<b>Assoziativgesetz</b>). Wir bringen 25 und 4 zusammen, weil ihr Produkt 100 ist."},{"type":"M","value":"25\\cdot17\\cdot4=(25\\cdot4)\\cdot17=100\\cdot17=1700"},{"type":"T","value":"Bei 7 · 99 hilft Verteilen, das <b>Distributivgesetz</b>: 99 ist 100 − 1. Sieben 99er enthalten genau sieben weniger als sieben 100er."},{"type":"M","value":"7\\cdot99=7\\cdot(100-1)=700-7=693"},{"type":"V","value":"N05"},{"type":"T","value":"Rückwärts kann derselbe gemeinsame Faktor wieder vor die Klammer: 7 · 60 + 7 · 39 = 7 · (60 + 39). Die Fläche im Bild bleibt gleich, ob wir die Teile getrennt oder zusammen berechnen."}],"prerequisites":["N02","N04"]},"source-1":{"title":"Ein Überschlag ist eine Kontrolle","prompt":"","blocks":[{"type":"H","value":"Ein Überschlag ist eine Kontrolle"},{"type":"T","value":"Für 19 · 51 rechnen wir ungefähr 20 · 50 = 1000. Genau ergibt (20 − 1) · 51 = 1020 − 51 = 969. Ein Ergebnis 96,9 passt nicht zur Größenordnung. Ein Überschlag ersetzt die genaue Rechnung nur, wenn eine Näherung gefragt ist."},{"type":"T","value":"Vorsicht: Vertauschen gilt bei Addition und Multiplikation, aber nicht allgemein bei Subtraktion oder Division: 12 : 3 ist etwas anderes als 3 : 12."}],"prerequisites":["N02","N04"]}},"taskExamples":{"N05_MINI":"transfer","N05_L4_01":"transfer","N05_L4_02":"transfer","N05_L4_03":"transfer","N05_L4_04":"transfer","N05_L4_05":"transfer","N05_POOL_01":"transfer","N05_POOL_02":"transfer","N05_POOL_03":"transfer","N05_POOL_04":"transfer","N05_NEU_01":"transfer","N05_NEU_02":"transfer","N05_NEU_03":"transfer","N05_NEU_04":"transfer","N05_NEU_05":"transfer","N05_NEU_06":"transfer","N05_TEST_01":"transfer","N05_TEST_02":"transfer","N05_TEST_03":"transfer","N05_NEU_07":"transfer","N05_NEU_08":"transfer","N05_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B01":{"default":"transfer","variants":{"transfer":{"title":"Das Ganze wechselt beim Teilen","prompt":"Drei gleich große Schokoriegel werden unter fünf Kindern geteilt. Ein Kind isst anschließend die Hälfte seines Anteils. Beschreibe seinen Anteil zuerst an einem Riegel und dann an allen drei Riegeln.","prerequisites":["N02","B06"],"blocks":[{"type":"H","value":"Das Ganze wechselt beim Teilen"},{"type":"T","value":"Drei gleich große Schokoriegel werden unter fünf Kindern geteilt. Ein Kind isst anschließend die Hälfte seines Anteils. Beschreibe seinen Anteil zuerst an einem Riegel und dann an allen drei Riegeln."},{"type":"H","value":"1. Gerecht verteilen"},{"type":"T","value":"Jeder Riegel wird in fünf gleich große Teile zerlegt. Jedes Kind bekommt aus jedem Riegel ein Teil."},{"type":"M","value":"3:5=\\frac35"},{"type":"T","value":"Ein Kind erhält 3/5 eines einzelnen Riegels."},{"type":"H","value":"2. Das Bezugs-Ganze wechseln"},{"type":"T","value":"Alle drei Riegel bilden nun zusammen das Ganze. Der Anteil eines Kindes ist daran 1/5, obwohl dieselbe Menge Schokolade gemeint ist."},{"type":"H","value":"3. Einen Anteil vom Anteil nehmen"},{"type":"M","value":"\\frac12\\cdot\\frac35=\\frac3{10}"},{"type":"T","value":"Die gegessene Menge sind 3/10 eines Riegels und 1/10 der gesamten Schokolade. Zähler und Nenner sind ohne genanntes Ganzes nicht eindeutig deutbar."}]},"source-0":{"title":"Drei Viertel – ein Bruch mit mehreren Bedeutungen","prompt":"","blocks":[{"type":"H","value":"Drei Viertel – ein Bruch mit mehreren Bedeutungen"},{"type":"T","value":"Ein <b>Bruch</b> beschreibt hier Teile eines Ganzen. In 3/4 nennt der <b>Nenner</b> 4 die Anzahl gleich großer Teile. Der <b>Zähler</b> 3 sagt, wie viele davon genommen werden. Ohne festgelegtes <b>Ganzes</b> wissen wir noch nicht, wie groß der Anteil in Litern oder Euro ist."},{"type":"V","value":"B01"},{"type":"T","value":"Als <b>Zahl</b> liegt drei Viertel zwischen 0 und 1. Die Strecke von 0 bis 1 wird in vier gleich lange Abschnitte geteilt; nach drei Abschnitten liegt die Zahl. Als <b>Quotient</b> bedeutet derselbe Bruch 3 : 4: Drei Liter werden gerecht auf vier Flaschen verteilt."},{"type":"M","value":"\\frac34=3:4=0{,}75"},{"type":"T","value":"Als <b>Anteil einer Menge</b> rechnen wir etwa drei Viertel von 20 Euro. Zuerst bestimmen wir ein Viertel, weil alle vier Teile gleich groß sein sollen. Dann nehmen wir drei solcher Teile."},{"type":"M","value":"20:4=5\\qquad3\\cdot5=15\\quad\\mathrm{(Euro)}"},{"type":"T","value":"Auch ein <b>Verhältnis</b> kann 3 : 4 lauten: 3 rote zu 4 blauen Steinen. Dann gibt es insgesamt 7 Steine; der rote Anteil am Ganzen ist 3/7, nicht 3/4. Frage also immer: Was wird mit was verglichen?"}],"prerequisites":["N02"]}},"taskExamples":{"B01_MINI":"transfer","B01_L4_01":"transfer","B01_L4_02":"transfer","B01_L4_03":"transfer","B01_L4_04":"transfer","B01_L4_05":"transfer","B01_POOL_01":"transfer","B01_POOL_02":"transfer","B01_POOL_03":"transfer","B01_POOL_04":"transfer","B01_NEU_01":"transfer","B01_NEU_02":"transfer","B01_NEU_03":"transfer","B01_NEU_04":"transfer","B01_NEU_05":"transfer","B01_NEU_06":"transfer","B01_TEST_01":"transfer","B01_TEST_02":"transfer","B01_TEST_03":"transfer","B01_NEU_07":"transfer","B01_NEU_08":"transfer","B01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B02":{"default":"transfer","variants":{"transfer":{"title":"Eine unbekannte Einteilung rekonstruieren","prompt":"Zwei gleich lange Streifen sind jeweils in gleich große Teile geteilt. Auf beiden ist dieselbe Länge markiert. Der erste zeigt 4/7, der zweite hat 20 markierte Teilstücke. Rekonstruiere seine Einteilung und kontrolliere rückwärts.","prerequisites":["N03"],"blocks":[{"type":"H","value":"Eine unbekannte Einteilung rekonstruieren"},{"type":"T","value":"Zwei gleich lange Streifen sind jeweils in gleich große Teile geteilt. Auf beiden ist dieselbe Länge markiert. Der erste zeigt 4/7, der zweite hat 20 markierte Teilstücke. Rekonstruiere seine Einteilung und kontrolliere rückwärts."},{"type":"H","value":"1. Den Vergrößerungsfaktor bestimmen"},{"type":"M","value":"20:4=5"},{"type":"T","value":"Jedes bisherige Siebtel wurde in fünf gleich große Teile zerlegt."},{"type":"H","value":"2. Den fehlenden Nenner berechnen"},{"type":"M","value":"\\frac47=\\frac{4\\cdot5}{7\\cdot5}=\\frac{20}{35}"},{"type":"T","value":"Die Gesamtzahl der Teilstücke wächst mit demselben Faktor."},{"type":"H","value":"3. Durch eine andere Darstellung prüfen"},{"type":"M","value":"\\frac{20}{35}=\\frac{40}{70}=\\frac47"},{"type":"T","value":"Man kann erst weiter verfeinern und dann kürzen. Nur den Nenner 7 durch 5 zu teilen würde den Wert verändern."}]},"source-0":{"title":"Gleich viel Fläche, anders eingeteilt","prompt":"","blocks":[{"type":"H","value":"Gleich viel Fläche, anders eingeteilt"},{"type":"T","value":"Von acht gleich großen Feldern sind sechs markiert. Fassen wir jeweils zwei Felder zusammen, sehen wir drei markierte von vier größeren Feldern. Die markierte Fläche bleibt gleich: Die Brüche sind <b>gleichwertig</b>."},{"type":"V","value":"B02"},{"type":"M","value":"\\frac68=\\frac{6:2}{8:2}=\\frac34"},{"type":"T","value":"Das heißt <b>Kürzen</b>: Zähler und Nenner durch denselben gemeinsamen Teiler teilen. Die 2 ist ein <b>gemeinsamer Teiler</b>, weil sie 6 und 8 ohne Rest teilt. Nur oben zu teilen würde die markierte Menge verändern."}],"prerequisites":["B01","N03"]},"source-1":{"title":"Rückwärts: kleinere Teilstücke erzeugen","prompt":"","blocks":[{"type":"H","value":"Rückwärts: kleinere Teilstücke erzeugen"},{"type":"T","value":"Beim <b>Erweitern</b> teilen wir jedes bisherige Viertel in drei Teile. Es gibt nun zwölf Teilstücke, neun davon sind markiert. Deshalb müssen Zähler und Nenner mit derselben Zahl multipliziert werden."},{"type":"M","value":"\\frac34=\\frac{3\\cdot3}{4\\cdot3}=\\frac9{12}"},{"type":"T","value":"So findest du auch eine Lücke: Um von 4 auf 20 im Nenner zu kommen, multiplizierst du mit 5. Der Zähler muss ebenfalls verfünffacht werden; er wird 15. Kürzen und Erweitern mit positiven ganzen Zahlen ändern die Zahl nicht. Beim Kürzen bis zum Ende haben Zähler und Nenner keinen gemeinsamen Teiler größer als 1."},{"type":"M","value":"\\frac34=\\frac{15}{20}\\qquad\\frac{18}{24}=\\frac34"}],"prerequisites":["B01","N03"]}},"taskExamples":{"B02_MINI":"transfer","B02_L4_01":"transfer","B02_L4_02":"transfer","B02_L4_03":"transfer","B02_L4_04":"transfer","B02_L4_05":"transfer","B02_POOL_01":"transfer","B02_POOL_02":"transfer","B02_POOL_03":"transfer","B02_POOL_04":"transfer","B02_NEU_01":"transfer","B02_NEU_02":"transfer","B02_NEU_03":"transfer","B02_NEU_04":"transfer","B02_NEU_05":"transfer","B02_NEU_06":"transfer","B02_TEST_01":"transfer","B02_TEST_02":"transfer","B02_TEST_03":"transfer","B02_NEU_07":"transfer","B02_NEU_08":"transfer","B02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B03":{"default":"transfer","variants":{"transfer":{"title":"Zwischen zwei Brüchen gibt es Platz","prompt":"Zwei Markierungen liegen bei 1 1/5 und 5/4 auf einer Zahlengeraden. Finde einen Bruch genau in der Mitte und prüfe seine Lage.","prerequisites":["B02","B05"],"blocks":[{"type":"H","value":"Zwischen zwei Brüchen gibt es Platz"},{"type":"T","value":"Zwei Markierungen liegen bei 1 1/5 und 5/4 auf einer Zahlengeraden. Finde einen Bruch genau in der Mitte und prüfe seine Lage."},{"type":"H","value":"1. In dieselbe Einteilung wechseln"},{"type":"M","value":"1\\frac15=\\frac65=\\frac{24}{20};\\qquad\\frac54=\\frac{25}{20}"},{"type":"T","value":"Zwischen benachbarten Zwanzigsteln lässt sich mit kleineren Teilen weitergehen."},{"type":"H","value":"2. Die Einteilung verfeinern"},{"type":"M","value":"\\frac{24}{20}=\\frac{48}{40};\\qquad\\frac{25}{20}=\\frac{50}{40}"},{"type":"T","value":"Jetzt liegt 49/40 genau zwischen den beiden Zählern."},{"type":"H","value":"3. Lage und Abstand prüfen"},{"type":"M","value":"\\frac{49}{40}-\\frac{48}{40}=\\frac1{40};\\qquad\\frac{50}{40}-\\frac{49}{40}=\\frac1{40}"},{"type":"T","value":"49/40 = 1 9/40 ist der Mittelpunkt. Zwischen zwei verschiedenen rationalen Zahlen liegt immer noch eine rationale Zahl."}]},"source-0":{"title":"Nur gleich große Teile lassen sich direkt zählen","prompt":"","blocks":[{"type":"H","value":"Nur gleich große Teile lassen sich direkt zählen"},{"type":"T","value":"Was ist größer: 3/4 oder 5/6? Die Zähler allein helfen nicht, denn Viertel und Sechstel sind verschieden groß. Wir erweitern auf <b>gleichnamige</b> Brüche: Beide haben dann denselben Nenner und damit gleich große Teile."},{"type":"M","value":"\\frac34=\\frac9{12}\\qquad\\frac56=\\frac{10}{12}\\qquad\\frac34<\\frac56"},{"type":"V","value":"B03"},{"type":"T","value":"Neun Zwölftel sind weniger als zehn Zwölftel. Bei gleichem Zähler ist es umgekehrt der Nenner, der entscheidet: 3/4 > 3/8, weil ein Viertel größer als ein Achtel ist."}],"prerequisites":["B01","B02"]},"source-1":{"title":"Ganze Teile aus einem Bruch herauslesen","prompt":"","blocks":[{"type":"H","value":"Ganze Teile aus einem Bruch herauslesen"},{"type":"T","value":"Ein <b>unechter Bruch</b> hat einen Zähler mindestens so groß wie seinen Nenner. In 11/4 stecken acht Viertel, also zwei Ganze, und drei Viertel Rest. Die Schreibweise mit Ganzzahl und Bruch heißt <b>gemischte Zahl</b> und bedeutet eine Summe."},{"type":"M","value":"\\frac{11}{4}=\\frac84+\\frac34=2+\\frac34=2\\frac34"},{"type":"T","value":"Rückwärts verwandeln wir jedes Ganze in vier Viertel. Zwei Ganze ergeben acht Viertel; zusammen mit drei Vierteln sind es elf. Die gemischte Schreibweise bedeutet hier keine Multiplikation."},{"type":"M","value":"2\\frac34=\\frac{2\\cdot4+3}{4}=\\frac{11}{4}"}],"prerequisites":["B01","B02"]}},"taskExamples":{"B03_MINI":"transfer","B03_L4_01":"transfer","B03_L4_02":"transfer","B03_L4_03":"transfer","B03_L4_04":"transfer","B03_L4_05":"transfer","B03_POOL_01":"transfer","B03_POOL_02":"transfer","B03_POOL_03":"transfer","B03_POOL_04":"transfer","B03_NEU_01":"transfer","B03_NEU_02":"transfer","B03_NEU_03":"transfer","B03_NEU_04":"transfer","B03_NEU_05":"transfer","B03_NEU_06":"transfer","B03_TEST_01":"transfer","B03_TEST_02":"transfer","B03_TEST_03":"transfer","B03_NEU_07":"transfer","B03_NEU_08":"transfer","B03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B04":{"default":"transfer","variants":{"transfer":{"title":"Eine Summe ergänzen und kontrollieren","prompt":"Ein Messbecher soll mit zwei Zutaten genau 1 Liter enthalten. Eine Zutat bringt 3/8 Liter, die zweite zunächst 1/4 Liter. Wie viel fehlt, und warum darfst du nicht die Nenner addieren?","prerequisites":["B02","B05"],"blocks":[{"type":"H","value":"Eine Summe ergänzen und kontrollieren"},{"type":"T","value":"Ein Messbecher soll mit zwei Zutaten genau 1 Liter enthalten. Eine Zutat bringt 3/8 Liter, die zweite zunächst 1/4 Liter. Wie viel fehlt, und warum darfst du nicht die Nenner addieren?"},{"type":"H","value":"1. Die vorhandene Menge bestimmen"},{"type":"M","value":"\\frac38+\\frac14=\\frac38+\\frac28=\\frac58"},{"type":"T","value":"Wir zählen gleich große Achtelliter. Die Stückgröße bleibt erhalten."},{"type":"H","value":"2. Den fehlenden Anteil finden"},{"type":"M","value":"1-\\frac58=\\frac38"},{"type":"T","value":"Von acht Achteln sind fünf vorhanden; drei fehlen."},{"type":"H","value":"3. Mit der ganzen Füllung prüfen"},{"type":"M","value":"\\frac38+\\frac14+\\frac38=\\frac38+\\frac28+\\frac38=1"},{"type":"T","value":"Das Gegenmodell 3/8 + 1/4 = 4/12 wäre sogar kleiner als 3/8. Positive Zutaten können die vorhandene Menge nicht verkleinern."}]},"source-0":{"title":"Ein Drittel plus ein Viertel zusammenlegen","prompt":"","blocks":[{"type":"H","value":"Ein Drittel plus ein Viertel zusammenlegen"},{"type":"T","value":"Wir addieren 1/3 und 1/4 desselben Ganzen. Drittel und Viertel sind verschieden große Teile. Ein gemeinsamer <b>Nenner</b> sorgt dafür, dass wir gleich große Teile zählen; 12 passt, weil 12 durch 3 und durch 4 teilbar ist."},{"type":"M","value":"\\frac13=\\frac4{12}\\qquad\\frac14=\\frac3{12}"},{"type":"V","value":"B04"},{"type":"T","value":"In der <b>Addition</b> kommen zu vier Zwölfteln drei Zwölftel hinzu. Wir zählen die Teilstücke, ihre Größe bleibt ein Zwölftel. Deshalb addieren wir die Zähler und behalten den Nenner bei."},{"type":"M","value":"\\frac13+\\frac14=\\frac4{12}+\\frac3{12}=\\frac7{12}"},{"type":"T","value":"7 und 12 haben keinen gemeinsamen Teiler größer als 1; der Bruch ist bereits vollständig gekürzt. Als Kontrolle: Beide Summanden sind positiv, also muss die Summe größer als jeder einzelne sein. 7/12 ist größer als 1/3 und 1/4, aber kleiner als 1."}],"prerequisites":["B02","N04"]},"source-1":{"title":"Die Rechnung rückwärts lesen","prompt":"","blocks":[{"type":"H","value":"Die Rechnung rückwärts lesen"},{"type":"M","value":"\\frac13+\\square=\\frac7{12}\\quad\\Longrightarrow\\quad\\square=\\frac7{12}-\\frac4{12}=\\frac14"},{"type":"T","value":"Wir ziehen den bekannten Summanden ab, weil wir den hinzugekommenen Anteil suchen. Zähler und Nenner jeweils zu addieren würde andere Teilgrößen erfinden und die dargestellte Menge nicht beschreiben."}],"prerequisites":["B02","N04"]}},"taskExamples":{"B04_MINI":"transfer","B04_L4_01":"transfer","B04_L4_02":"transfer","B04_L4_03":"transfer","B04_L4_04":"transfer","B04_L4_05":"transfer","B04_POOL_01":"transfer","B04_POOL_02":"transfer","B04_POOL_03":"transfer","B04_POOL_04":"transfer","B04_NEU_01":"transfer","B04_NEU_02":"transfer","B04_NEU_03":"transfer","B04_NEU_04":"transfer","B04_NEU_05":"transfer","B04_NEU_06":"transfer","B04_TEST_01":"transfer","B04_TEST_02":"transfer","B04_TEST_03":"transfer","B04_NEU_07":"transfer","B04_NEU_08":"transfer","B04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B05":{"default":"transfer","variants":{"transfer":{"title":"Eine Differenz durch Ergänzen finden","prompt":"Eine Markierung liegt bei 2 1/6 Metern, die andere bei 3/4 Meter. Wie groß ist der Abstand? Rechne einmal durch Abziehen und einmal durch Ergänzen.","prerequisites":["B02","B03","B04"],"blocks":[{"type":"H","value":"Eine Differenz durch Ergänzen finden"},{"type":"T","value":"Eine Markierung liegt bei 2 1/6 Metern, die andere bei 3/4 Meter. Wie groß ist der Abstand? Rechne einmal durch Abziehen und einmal durch Ergänzen."},{"type":"H","value":"1. Die Zahlen in Zwölfteln schreiben"},{"type":"M","value":"2\\frac16=\\frac{26}{12};\\qquad\\frac34=\\frac9{12}"},{"type":"H","value":"2. Die Differenz berechnen"},{"type":"M","value":"\\frac{26}{12}-\\frac9{12}=\\frac{17}{12}=1\\frac5{12}"},{"type":"H","value":"3. Auf dem Zahlenstrahl ergänzen"},{"type":"T","value":"Von 3/4 bis 1 fehlen 1/4 Meter; von 1 bis 2 1/6 sind es 1 1/6 Meter."},{"type":"M","value":"\\frac14+1\\frac16=1\\frac5{12}"},{"type":"T","value":"Die beiden Wege ergeben denselben Abstand."}]},"source-0":{"title":"Von fünf Sechsteln ein Viertel wegnehmen","prompt":"","blocks":[{"type":"H","value":"Von fünf Sechsteln ein Viertel wegnehmen"},{"type":"T","value":"Die <b>Differenz</b> ist das, was nach dem Wegnehmen übrig bleibt. Wir können Viertel nicht direkt von einer Anzahl Sechstel abziehen. Deshalb stellen wir beide Anteile desselben Ganzen in Zwölfteln dar."},{"type":"M","value":"\\frac56=\\frac{10}{12}\\qquad\\frac14=\\frac3{12}"},{"type":"V","value":"B05"},{"type":"T","value":"Von zehn markierten Zwölfteln werden drei weggenommen. Die übrigen sieben sind weiterhin Zwölftel. Der Nenner bleibt deshalb stehen."},{"type":"M","value":"\\frac56-\\frac14=\\frac{10}{12}-\\frac3{12}=\\frac7{12}"},{"type":"T","value":"Die <b>Probe</b> macht das Wegnehmen rückgängig: Zum Rest addieren wir den weggenommenen Anteil. Es müssen wieder fünf Sechstel entstehen."},{"type":"M","value":"\\frac7{12}+\\frac14=\\frac{10}{12}=\\frac56"}],"prerequisites":["B02","N04"]},"source-1":{"title":"Wenn eine gemischte Zahl vorkommt","prompt":"","blocks":[{"type":"H","value":"Wenn eine gemischte Zahl vorkommt"},{"type":"M","value":"1\\frac14-\\frac23=\\frac54-\\frac23=\\frac{15}{12}-\\frac8{12}=\\frac7{12}"},{"type":"T","value":"Das Ganze wird zuerst in Viertel umgewandelt, damit wir mit einem einzigen Bruch weiterrechnen können. Danach funktioniert dieselbe Idee. Am Schluss kürzen wir, falls Zähler und Nenner einen gemeinsamen Teiler besitzen; bei 7/12 ist das nicht möglich."}],"prerequisites":["B02","N04"]}},"taskExamples":{"B05_MINI":"transfer","B05_L4_01":"transfer","B05_L4_02":"transfer","B05_L4_03":"transfer","B05_L4_04":"transfer","B05_L4_05":"transfer","B05_POOL_01":"transfer","B05_POOL_02":"transfer","B05_POOL_03":"transfer","B05_POOL_04":"transfer","B05_NEU_01":"transfer","B05_NEU_02":"transfer","B05_NEU_03":"transfer","B05_NEU_04":"transfer","B05_NEU_05":"transfer","B05_NEU_06":"transfer","B05_TEST_01":"transfer","B05_TEST_02":"transfer","B05_TEST_03":"transfer","B05_NEU_07":"transfer","B05_NEU_08":"transfer","B05_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B06":{"default":"transfer","variants":{"transfer":{"title":"Ein Flächenanteil auf zwei Wegen","prompt":"Von einer rechteckigen Fläche sind 3/4 bepflanzt. Davon sind 2/3 Blumen. Welche Fläche bleibt für andere Pflanzen, und stimmt das mit der Aufteilung des Gartens überein?","prerequisites":["B01","B04"],"blocks":[{"type":"H","value":"Ein Flächenanteil auf zwei Wegen"},{"type":"T","value":"Von einer rechteckigen Fläche sind 3/4 bepflanzt. Davon sind 2/3 Blumen. Welche Fläche bleibt für andere Pflanzen, und stimmt das mit der Aufteilung des Gartens überein?"},{"type":"H","value":"1. Den Blumenanteil bestimmen"},{"type":"M","value":"\\frac23\\cdot\\frac34=\\frac12"},{"type":"T","value":"Das erste Ganze ist der Garten, das zweite Ganze bei „davon“ nur seine bepflanzte Fläche."},{"type":"H","value":"2. Den übrigen bepflanzten Anteil finden"},{"type":"M","value":"\\frac13\\cdot\\frac34=\\frac14"},{"type":"T","value":"Ein Drittel der bepflanzten Fläche enthält andere Pflanzen."},{"type":"H","value":"3. Alle Teile zusammensetzen"},{"type":"M","value":"\\frac12+\\frac14+\\frac14=1"},{"type":"T","value":"Die Teile sind Blumen, andere Pflanzen und unbepflanzter Garten. Sie ergeben genau ein Ganzes."}]},"source-0":{"title":"Zwei Drittel von drei Vierteln","prompt":"","blocks":[{"type":"H","value":"Zwei Drittel von drei Vierteln"},{"type":"T","value":"Von einer Fläche sind drei Viertel ausgewählt. Davon nehmen wir zwei Drittel. „<b>Von</b>“ bedeutet hier: einen Anteil einer schon ausgewählten Menge bilden. Wir unterteilen die ganze Fläche deshalb gleichzeitig in vier Spalten und drei Zeilen."},{"type":"V","value":"B06"},{"type":"T","value":"Das Ganze hat zwölf gleich große Felder. Der gesuchte überlappende Teil umfasst sechs Felder: zwei Zeilen mal drei Spalten. So erklärt das Bild, warum Zähler mit Zähler und Nenner mit Nenner multipliziert werden."},{"type":"M","value":"\\frac23\\cdot\\frac34=\\frac{2\\cdot3}{3\\cdot4}=\\frac6{12}=\\frac12"},{"type":"T","value":"Beim <b>Kürzen</b> vor der Multiplikation entfernen wir gleiche Faktoren aus dem gesamten Zähler und Nenner. Die 3 oben und unten heben sich auf; außerdem ergibt 2/4 = 1/2. Das spart große Zwischenzahlen und ändert das Produkt nicht."}],"prerequisites":["B01","B02"]},"source-1":{"title":"Dieselbe Rechnung mit einer Menge","prompt":"","blocks":[{"type":"H","value":"Dieselbe Rechnung mit einer Menge"},{"type":"T","value":"Von 24 Kindern sind drei Viertel im Sportverein. Zwei Drittel dieser Gruppe spielen Fußball. Der zweite Bruch bezieht sich auf die Sportgruppe, nicht unmittelbar auf alle Kinder."},{"type":"M","value":"24\\cdot\\frac34=18\\qquad18\\cdot\\frac23=12"},{"type":"T","value":"Also spielt die Hälfte aller 24 Kinder Fußball. Das passt zum Flächenbild. Weil wir jeweils einen Anteil kleiner als 1 nehmen, wird die betrachtete Menge hier bei jedem Schritt kleiner."}],"prerequisites":["B01","B02"]}},"taskExamples":{"B06_MINI":"transfer","B06_L4_01":"transfer","B06_L4_02":"transfer","B06_L4_03":"transfer","B06_L4_04":"transfer","B06_L4_05":"transfer","B06_POOL_01":"transfer","B06_POOL_02":"transfer","B06_POOL_03":"transfer","B06_POOL_04":"transfer","B06_NEU_01":"transfer","B06_NEU_02":"transfer","B06_NEU_03":"transfer","B06_NEU_04":"transfer","B06_NEU_05":"transfer","B06_NEU_06":"transfer","B06_TEST_01":"transfer","B06_TEST_02":"transfer","B06_TEST_03":"transfer","B06_NEU_07":"transfer","B06_NEU_08":"transfer","B06_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B07":{"default":"transfer","variants":{"transfer":{"title":"Portionen und Rest sind verschiedene Größen","prompt":"Aus 1 1/4 Liter Saft sollen Portionen von 3/8 Liter abgefüllt werden. Wie viele volle Portionen sind möglich, und wie groß ist der Rest in Litern?","prerequisites":["B03","B05","B06"],"blocks":[{"type":"H","value":"Portionen und Rest sind verschiedene Größen"},{"type":"T","value":"Aus 1 1/4 Liter Saft sollen Portionen von 3/8 Liter abgefüllt werden. Wie viele volle Portionen sind möglich, und wie groß ist der Rest in Litern?"},{"type":"H","value":"1. Die Portionenanzahl berechnen"},{"type":"M","value":"\\frac54:\\frac38=\\frac54\\cdot\\frac83=\\frac{10}{3}=3\\frac13"},{"type":"T","value":"Das Ergebnis zählt Portionen, keine Liter."},{"type":"H","value":"2. Nur volle Portionen abfüllen"},{"type":"M","value":"3\\cdot\\frac38=\\frac98"},{"type":"T","value":"Drei Portionen verbrauchen 9/8 Liter."},{"type":"H","value":"3. Den Rest zurück in Litern ausdrücken"},{"type":"M","value":"\\frac54-\\frac98=\\frac{10}{8}-\\frac98=\\frac18"},{"type":"T","value":"Der Rest ist 1/8 Liter und zugleich 1/3 einer Portion. Das erklärt den gebrochenen Anteil des Quotienten."}]},"source-0":{"title":"Wie oft passt ein halber Liter in drei Viertelliter?","prompt":"","blocks":[{"type":"H","value":"Wie oft passt ein halber Liter in drei Viertelliter?"},{"type":"T","value":"Bei 3/4 : 1/2 ist der <b>Dividend</b> 3/4 die vorhandene Menge und der <b>Divisor</b> 1/2 die Größe einer Portion. Eine volle Portion verbraucht zwei Viertel; vom dritten Viertel erhält man noch eine halbe Portion. Das Ergebnis ist also eineinhalb Portionen."},{"type":"V","value":"B07"},{"type":"T","value":"Algebraisch machen wir den Divisor zu 1. Dafür multiplizieren wir beide Zahlen der Division mit 2. Das Verhältnis bleibt gleich, denn beide werden im selben Maß vergrößert."},{"type":"M","value":"\\frac34:\\frac12=\\left(\\frac34\\cdot2\\right):1=\\frac32"},{"type":"T","value":"2 ist der <b>Kehrwert</b> von 1/2: Die beiden Zahlen ergeben multipliziert 1. Allgemein wird bei einem von 0 verschiedenen Bruch der Kehrwert durch Vertauschen von Zähler und Nenner gebildet. Nur der Divisor wird durch seinen Kehrwert ersetzt."},{"type":"M","value":"\\frac34:\\frac12=\\frac34\\cdot\\frac21=\\frac32=1\\frac12"},{"type":"T","value":"Die Probe fragt: Liefern eineinhalb Portionen zu einem halben Liter wieder drei Viertelliter? Ja. Durch 0 darf man nicht teilen; 0 besitzt keinen Kehrwert."},{"type":"M","value":"\\frac32\\cdot\\frac12=\\frac34"}],"prerequisites":["B06"]}},"taskExamples":{"B07_MINI":"transfer","B07_L4_01":"transfer","B07_L4_02":"transfer","B07_L4_03":"transfer","B07_L4_04":"transfer","B07_L4_05":"transfer","B07_POOL_01":"transfer","B07_POOL_02":"transfer","B07_POOL_03":"transfer","B07_POOL_04":"transfer","B07_NEU_01":"transfer","B07_NEU_02":"transfer","B07_NEU_03":"transfer","B07_NEU_04":"transfer","B07_NEU_05":"transfer","B07_NEU_06":"transfer","B07_TEST_01":"transfer","B07_TEST_02":"transfer","B07_TEST_03":"transfer","B07_NEU_07":"transfer","B07_NEU_08":"transfer","B07_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"B08":{"default":"transfer","variants":{"transfer":{"title":"Rückwärts durch zwei Verbrauchsschritte","prompt":"Ein Vorrat wird zuerst zur Hälfte verbraucht. Danach wird ein Viertel des Restes verbraucht. Am Ende bleiben 9 Liter. Rekonstruiere den Vorrat mit einer Skizzenidee und mit Faktoren.","prerequisites":["B01","B06","B07"],"blocks":[{"type":"H","value":"Rückwärts durch zwei Verbrauchsschritte"},{"type":"T","value":"Ein Vorrat wird zuerst zur Hälfte verbraucht. Danach wird ein Viertel des Restes verbraucht. Am Ende bleiben 9 Liter. Rekonstruiere den Vorrat mit einer Skizzenidee und mit Faktoren."},{"type":"H","value":"1. Den letzten Rest deuten"},{"type":"T","value":"Die 9 Liter sind drei Viertel der Menge nach dem ersten Verbrauch. Ein Viertel davon sind 3 Liter; die ganze Zwischenmenge sind 12 Liter."},{"type":"H","value":"2. Zum Anfang zurückgehen"},{"type":"T","value":"Die Zwischenmenge war die Hälfte des ursprünglichen Vorrats. Am Anfang waren also 24 Liter vorhanden."},{"type":"H","value":"3. Vorwärts prüfen"},{"type":"M","value":"24\\cdot\\frac12\\cdot\\frac34=9"},{"type":"T","value":"Es bleibt 3/8 des Anfangs. Die verbrauchten Anteile 1/2 und 1/4 darf man nicht ohne Beachtung ihrer verschiedenen Bezugsmengen addieren."}]},"source-0":{"title":"Wenn der Anteil bekannt ist, das Ganze aber fehlt","prompt":"","blocks":[{"type":"H","value":"Wenn der Anteil bekannt ist, das Ganze aber fehlt"},{"type":"T","value":"Drei Fünftel eines Weges sind 18 km. Der Bruch sagt, wie viele gleich große Teile gemeint sind; 18 km ist die Länge dieser drei Teile. Ein Fünftel ist deshalb 18 : 3 = 6 km. Für das <b>Ganze</b> brauchen wir fünf solcher Teile."},{"type":"V","value":"B08"},{"type":"M","value":"18:\\frac35=18\\cdot\\frac53=30\\quad\\mathrm{(km)}"},{"type":"T","value":"Die Division durch den Anteil macht die Multiplikation mit dem Anteil rückgängig. Zur Probe nehmen wir drei Fünftel von 30 km: 30 : 5 · 3 = 18 km. Der ganze Weg ist länger als die bekannte Teilstrecke; das Ergebnis passt."}],"prerequisites":["B04","B05","B06","B07"]},"source-1":{"title":"Achtung: Wovon wird der nächste Anteil genommen?","prompt":"","blocks":[{"type":"H","value":"Achtung: Wovon wird der nächste Anteil genommen?"},{"type":"T","value":"Von 30 Euro gibst du zuerst ein Drittel aus, danach die Hälfte des <b>Restes</b>. Der erste Anteil bezieht sich auf 30 Euro. Nach dem Einkauf sind nur noch 20 Euro da; diese 20 Euro sind nun die neue <b>Bezugsgröße</b>."},{"type":"M","value":"30-\\frac13\\cdot30=20\\qquad20-\\frac12\\cdot20=10"},{"type":"T","value":"Es bleiben 10 Euro, also ein Drittel des Anfangsgeldes. Die Brüche 1/3 und 1/2 darfst du hier nicht einfach als ausgegebene Anteile addieren: Sie beziehen sich auf unterschiedliche Ganze. Notiere bei Sachaufgaben deshalb zuerst, welches Ganze zu jedem Bruch gehört."}],"prerequisites":["B04","B05","B06","B07"]}},"taskExamples":{"B08_MINI":"transfer","B08_L4_01":"transfer","B08_L4_02":"transfer","B08_L4_03":"transfer","B08_L4_04":"transfer","B08_L4_05":"transfer","B08_POOL_01":"transfer","B08_POOL_02":"transfer","B08_POOL_03":"transfer","B08_POOL_04":"transfer","B08_NEU_01":"transfer","B08_NEU_02":"transfer","B08_NEU_03":"transfer","B08_NEU_04":"transfer","B08_NEU_05":"transfer","B08_NEU_06":"transfer","B08_TEST_01":"transfer","B08_TEST_02":"transfer","B08_TEST_03":"transfer","B08_NEU_07":"transfer","B08_NEU_08":"transfer","B08_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"D01":{"default":"transfer","variants":{"transfer":{"title":"Eine Stelle mehr macht Vergleiche genauer","prompt":"Zwei Messwerte sind 2,4 und 2,38. Eine dritte Messung soll genau dazwischenliegen. Erkläre die Lage mit Hundertsteln und mit Bruchteilen.","prerequisites":["B01","B03"],"blocks":[{"type":"H","value":"Eine Stelle mehr macht Vergleiche genauer"},{"type":"T","value":"Zwei Messwerte sind 2,4 und 2,38. Eine dritte Messung soll genau dazwischenliegen. Erkläre die Lage mit Hundertsteln und mit Bruchteilen."},{"type":"H","value":"1. Gleiche Stellen gegenüberstellen"},{"type":"M","value":"2{,}4=2{,}40=\\frac{240}{100};\\qquad2{,}38=\\frac{238}{100}"},{"type":"H","value":"2. Die Mitte bestimmen"},{"type":"T","value":"239 Hundertstel liegen zwischen 238 und 240 Hundertsteln. Der dritte Wert ist 2,39."},{"type":"H","value":"3. Mit Abständen prüfen"},{"type":"M","value":"2{,}40-2{,}39=0{,}01;\\qquad2{,}39-2{,}38=0{,}01"},{"type":"T","value":"Eine Endnull hängt eine kleinere Stelle mit Wert null an. Sie macht 2,4 nicht größer."}]},"source-0":{"title":"Nach dem Komma geht das Stellenwertsystem weiter","prompt":"","blocks":[{"type":"H","value":"Nach dem Komma geht das Stellenwertsystem weiter"},{"type":"T","value":"In der <b>Dezimalzahl</b> 2,35 stehen 2 Einer, 3 Zehntel und 5 Hundertstel. Eine Stelle nach rechts bedeutet immer: Ein Teil ist nur noch ein Zehntel so groß. Darum können wir die Zahl auch als Summe von Brüchen lesen."},{"type":"M","value":"2{,}35=2+\\frac3{10}+\\frac5{100}=\\frac{235}{100}"},{"type":"V","value":"D01"},{"type":"T","value":"Zum Vergleichen von 2,35 und 2,4 gleichen wir die Stellen an: 2,4 = 2,40. Die angehängte Null ändert den Wert nicht. Beide Zahlen haben zwei Einer; bei den Zehnteln entscheidet 3 < 4. Also ist 2,35 kleiner. „35 ist größer als 4“ vergleicht hier die falschen Einheiten."},{"type":"M","value":"2{,}35<2{,}40=2{,}4"}],"prerequisites":["N01","B01"]},"source-1":{"title":"Zwischen Bruch und Dezimalzahl wechseln","prompt":"","blocks":[{"type":"H","value":"Zwischen Bruch und Dezimalzahl wechseln"},{"type":"T","value":"Drei Viertel erweitern wir auf Hundertstel, weil Hundertstel direkt als zwei Nachkommastellen lesbar sind. Rückwärts schreiben wir zunächst den Stellenwert als Nenner und kürzen dann."},{"type":"M","value":"\\frac34=\\frac{75}{100}=0{,}75\\qquad0{,}08=\\frac8{100}=\\frac2{25}"},{"type":"T","value":"Bei 0,08 hält die Null den Zehntelplatz frei. Ohne sie wäre 0,8 gemeint, also acht Zehntel statt acht Hundertstel: der zehnfache Wert."}],"prerequisites":["N01","B01"]}},"taskExamples":{"D01_MINI":"transfer","D01_L4_01":"transfer","D01_L4_02":"transfer","D01_L4_03":"transfer","D01_L4_04":"transfer","D01_L4_05":"transfer","D01_POOL_01":"transfer","D01_POOL_02":"transfer","D01_POOL_03":"transfer","D01_POOL_04":"transfer","D01_NEU_01":"transfer","D01_NEU_02":"transfer","D01_NEU_03":"transfer","D01_NEU_04":"transfer","D01_NEU_05":"transfer","D01_NEU_06":"transfer","D01_TEST_01":"transfer","D01_TEST_02":"transfer","D01_TEST_03":"transfer","D01_NEU_07":"transfer","D01_NEU_08":"transfer","D01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"D02":{"default":"transfer","variants":{"transfer":{"title":"Ein Ergebnis auf drei Arten kontrollieren","prompt":"Ein 3,6 Meter langes Band wird in 0,24 Meter lange Stücke geschnitten. Zeige mit einer Division, einer Rückrechnung und einem Überschlag, warum 15 Stücke passen.","prerequisites":["N05","B07"],"blocks":[{"type":"H","value":"Ein Ergebnis auf drei Arten kontrollieren"},{"type":"T","value":"Ein 3,6 Meter langes Band wird in 0,24 Meter lange Stücke geschnitten. Zeige mit einer Division, einer Rückrechnung und einem Überschlag, warum 15 Stücke passen."},{"type":"H","value":"1. Den Divisor ganzzahlig machen"},{"type":"M","value":"3{,}6:0{,}24=360:24=15"},{"type":"T","value":"Beide Zahlen werden mit 100 multipliziert, das Mengenverhältnis bleibt gleich."},{"type":"H","value":"2. Mit einer Multiplikation prüfen"},{"type":"M","value":"15\\cdot0{,}24=10\\cdot0{,}24+5\\cdot0{,}24=2{,}4+1{,}2=3{,}6"},{"type":"H","value":"3. Die Größenordnung erklären"},{"type":"T","value":"Ein Stück ist ungefähr ein Viertelmeter lang. In etwas mehr als 3,5 Meter passen ungefähr 14 bis 15 Viertelmeter. Ein Ergebnis 1,5 oder 150 wäre unplausibel."}]},"source-0":{"title":"Addieren und subtrahieren: gleiche Stellen zusammen","prompt":"","blocks":[{"type":"H","value":"Addieren und subtrahieren: gleiche Stellen zusammen"},{"type":"T","value":"Wir rechnen 2,35 + 0,8. Schreibe 0,8 als 0,80, damit Hundertstel unter Hundertsteln stehen. 35 Hundertstel + 80 Hundertstel sind 115 Hundertstel, also ein Einer und 15 Hundertstel. Das Komma markiert die Grenze zwischen Einern und Zehnteln."},{"type":"M","value":"2{,}35+0{,}80=3{,}15\\qquad3{,}15-0{,}80=2{,}35"},{"type":"T","value":"Die Subtraktion ist die passende Probe zur Addition. Beim schriftlichen Rechnen stehen die Kommas untereinander; nicht die jeweils letzte Ziffer."}],"prerequisites":["D01","N02"]},"source-1":{"title":"Multiplizieren: die Größe der Teile mitrechnen","prompt":"","blocks":[{"type":"H","value":"Multiplizieren: die Größe der Teile mitrechnen"},{"type":"M","value":"1{,}2\\cdot0{,}3=\\frac{12}{10}\\cdot\\frac3{10}=\\frac{36}{100}=0{,}36"},{"type":"T","value":"Zwölf Zehntel mal drei Zehntel ergeben 36 Hundertstel. Deshalb hat das Produkt hier insgesamt zwei Nachkommastellen. 3,6 wäre zehnmal zu groß; 0,3 von 1,2 muss kleiner als 1,2 sein."}],"prerequisites":["D01","N02"]},"source-2":{"title":"Dividieren: den Divisor ganzzahlig machen","prompt":"","blocks":[{"type":"H","value":"Dividieren: den Divisor ganzzahlig machen"},{"type":"M","value":"1{,}44:0{,}12=144:12=12"},{"type":"T","value":"Wir multiplizieren <b>beide</b> Zahlen mit 100. Der Quotient bleibt gleich: Das Verhältnis von 144 Hundertsteln zu 12 Hundertsteln ist dasselbe wie von 144 zu 12. Nur bei einer Zahl das Komma zu verschieben wäre keine gleichwertige Rechnung."},{"type":"M","value":"12\\cdot0{,}12=1{,}44\\quad\\mathrm{(Probe)}"}],"prerequisites":["D01","N02"]}},"taskExamples":{"D02_MINI":"transfer","D02_L4_01":"transfer","D02_L4_02":"transfer","D02_L4_03":"transfer","D02_L4_04":"transfer","D02_L4_05":"transfer","D02_POOL_01":"transfer","D02_POOL_02":"transfer","D02_POOL_03":"transfer","D02_POOL_04":"transfer","D02_NEU_01":"transfer","D02_NEU_02":"transfer","D02_NEU_03":"transfer","D02_NEU_04":"transfer","D02_NEU_05":"transfer","D02_NEU_06":"transfer","D02_TEST_01":"transfer","D02_TEST_02":"transfer","D02_TEST_03":"transfer","D02_NEU_07":"transfer","D02_NEU_08":"transfer","D02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"D03":{"default":"transfer","variants":{"transfer":{"title":"Endlich, periodisch oder nur gerundet?","prompt":"Vergleiche 7/20 und 7/12. Beide Brüche haben denselben Zähler, aber ihre Dezimaldarstellungen verhalten sich verschieden.","prerequisites":["N03","B02"],"blocks":[{"type":"H","value":"Endlich, periodisch oder nur gerundet?"},{"type":"T","value":"Vergleiche 7/20 und 7/12. Beide Brüche haben denselben Zähler, aber ihre Dezimaldarstellungen verhalten sich verschieden."},{"type":"H","value":"1. Den gekürzten Nenner untersuchen"},{"type":"M","value":"20=2^2\\cdot5;\\qquad12=2^2\\cdot3"},{"type":"T","value":"Nur Faktoren 2 und 5 können einen Nenner zu einer Zehnerpotenz ergänzen. Daher endet 7/20; 7/12 hat eine Periode."},{"type":"H","value":"2. Die Darstellungen berechnen"},{"type":"M","value":"\\frac7{20}=0{,}35;\\qquad\\frac7{12}=0{,}58\\overline3"},{"type":"T","value":"Bei 7/12 wiederholt sich der Rest in der Division. Der Periodenstrich gehört nur über die 3."},{"type":"H","value":"3. Eine Rundung davon abgrenzen"},{"type":"M","value":"\\frac7{12}\\approx0{,}58"},{"type":"T","value":"0,58 ist ein gerundeter Wert auf Hundertstel und nicht exakt derselbe Bruch. Gleichheitszeichen und Näherungszeichen beschreiben verschiedene Aussagen."}]},"source-0":{"title":"Teilen zeigt, ob die Dezimaldarstellung endet","prompt":"","blocks":[{"type":"H","value":"Teilen zeigt, ob die Dezimaldarstellung endet"},{"type":"T","value":"Für 3/8 teilen wir 3 durch 8. 30 Zehntel liefern 3 Zehntel, Rest 6 Zehntel. Aus 60 Hundertsteln werden 7 Hundertstel, Rest 4 Hundertstel. 40 Tausendstel liefern 5 Tausendstel ohne Rest: Die Darstellung endet."},{"type":"M","value":"\\frac38=0{,}375"},{"type":"T","value":"Bei 1/3 entsteht nach jedem Rechenschritt wieder derselbe Rest 1. Daher wiederholt sich die Ziffer 3 endlos. Die wiederholte Ziffernfolge heißt <b>Periode</b>; der Strich steht über genau dieser Folge."},{"type":"M","value":"\\frac13=0{,}\\overline{3}\\qquad\\frac16=0{,}1\\overline{6}"},{"type":"T","value":"Bei einem vollständig gekürzten Bruch endet die Dezimaldarstellung genau dann, wenn der Nenner nur Primfaktoren 2 und 5 enthält. Denn nur solche Nenner lassen sich zu einer Zehnerpotenz erweitern. 8 = 2 · 2 · 2 passt; 3 und 6 enthalten den Faktor 3."}],"prerequisites":["B02","D02"]},"source-1":{"title":"Exakte Zahl oder gerundeter Wert?","prompt":"","blocks":[{"type":"H","value":"Exakte Zahl oder gerundeter Wert?"},{"type":"M","value":"\\frac13=0{,}\\overline3\\qquad\\frac13\\approx0{,}33"},{"type":"T","value":"0,33 hat genau 33 Hundertstel und ist etwas kleiner als ein Drittel. Verwende bei einer Rundung <b>≈</b>. Für 0,375 geht es exakt zurück: 375/1000 = 3/8. Auch eine Periode ist eine exakte Schreibweise; sie ist kein ungenaues Messergebnis."}],"prerequisites":["B02","D02"]}},"taskExamples":{"D03_MINI":"transfer","D03_L4_01":"transfer","D03_L4_02":"transfer","D03_L4_03":"transfer","D03_L4_04":"transfer","D03_L4_05":"transfer","D03_POOL_01":"transfer","D03_POOL_02":"transfer","D03_POOL_03":"transfer","D03_POOL_04":"transfer","D03_NEU_01":"transfer","D03_NEU_02":"transfer","D03_NEU_03":"transfer","D03_NEU_04":"transfer","D03_NEU_05":"transfer","D03_NEU_06":"transfer","D03_TEST_01":"transfer","D03_TEST_02":"transfer","D03_TEST_03":"transfer","D03_NEU_07":"transfer","D03_NEU_08":"transfer","D03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"R01":{"default":"transfer","variants":{"transfer":{"title":"Gleicher Abstand, andere Lage","prompt":"Zwei Messpunkte liegen gleich weit von −1 entfernt: einer bei −3,5, der andere rechts von −1. Bestimme ihn und vergleiche diese Symmetrie mit Gegenzahlen.","prerequisites":["D01","R02"],"blocks":[{"type":"H","value":"Gleicher Abstand, andere Lage"},{"type":"T","value":"Zwei Messpunkte liegen gleich weit von −1 entfernt: einer bei −3,5, der andere rechts von −1. Bestimme ihn und vergleiche diese Symmetrie mit Gegenzahlen."},{"type":"H","value":"1. Den Abstand zur Mitte bestimmen"},{"type":"M","value":"|-3{,}5-(-1)|=2{,}5"},{"type":"H","value":"2. Den zweiten Punkt finden"},{"type":"M","value":" -1+2{,}5=1{,}5"},{"type":"T","value":"Der gesuchte Punkt liegt bei 1,5. −3,5 und 1,5 sind um −1 spiegelbildlich."},{"type":"H","value":"3. Gegenzahlen unterscheiden"},{"type":"T","value":"Die Gegenzahl zu −3,5 ist dagegen +3,5: Bei Gegenzahlen ist die Mitte immer null. Gleicher Abstand von irgendeinem Mittelpunkt bedeutet noch nicht „Gegenzahl“."}]},"source-0":{"title":"Links von null wird weitergezählt","prompt":"","blocks":[{"type":"H","value":"Links von null wird weitergezählt"},{"type":"T","value":"Eine <b>rationale Zahl</b> lässt sich als Bruch ganzer Zahlen mit Nenner ungleich 0 schreiben. Dazu gehören auch negative Zahlen, ganze Zahlen sowie endliche und periodische Dezimalzahlen. Auf der Zahlengeraden werden die Zahlen nach rechts größer."},{"type":"V","value":"R01"},{"type":"M","value":"-3<-1{,}5<0<1{,}5"},{"type":"T","value":"−3 ist kleiner als −1,5, obwohl sein Abstand von null größer ist. Bei negativen Zahlen entscheidet die Richtung, nicht nur die Zifferngröße. Der <b>Betrag</b> ist dagegen ausschließlich der Abstand von null und deshalb nie negativ."},{"type":"M","value":"\\lvert-1{,}5\\rvert=1{,}5\\qquad\\lvert1{,}5\\rvert=1{,}5"},{"type":"T","value":"−1,5 und +1,5 sind <b>Gegenzahlen</b>: Sie liegen gleich weit von null auf entgegengesetzten Seiten. Addiert ergeben sie 0. Die Gegenzahl von −1,5 ist also +1,5; die Gegenzahl von 0 ist 0."},{"type":"M","value":"-1{,}5+1{,}5=0\\qquad-(-1{,}5)=1{,}5"},{"type":"T","value":"Bei einer Temperatur von −3 °C ist es kälter als bei −1,5 °C. Die zweite Temperatur liegt näher an 0 °C und weiter rechts. Diese Vorstellung hilft beim Ordnen; für einen Temperaturunterschied musst du beide Werte miteinander vergleichen."}],"prerequisites":["D01","B03"]}},"taskExamples":{"R01_MINI":"transfer","R01_L4_01":"transfer","R01_L4_02":"transfer","R01_L4_03":"transfer","R01_L4_04":"transfer","R01_L4_05":"transfer","R01_POOL_01":"transfer","R01_POOL_02":"transfer","R01_POOL_03":"transfer","R01_POOL_04":"transfer","R01_NEU_01":"transfer","R01_NEU_02":"transfer","R01_NEU_03":"transfer","R01_NEU_04":"transfer","R01_NEU_05":"transfer","R01_NEU_06":"transfer","R01_TEST_01":"transfer","R01_TEST_02":"transfer","R01_TEST_03":"transfer","R01_NEU_07":"transfer","R01_NEU_08":"transfer","R01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"R02":{"default":"transfer","variants":{"transfer":{"title":"Eine Änderung rückwärts prüfen","prompt":"Ein Thermometer zeigt erst −2,5 °C und später −6 °C. Welche Änderung ist passiert, und welche entgegengesetzte Änderung führt zurück?","prerequisites":["R01","D02"],"blocks":[{"type":"H","value":"Eine Änderung rückwärts prüfen"},{"type":"T","value":"Ein Thermometer zeigt erst −2,5 °C und später −6 °C. Welche Änderung ist passiert, und welche entgegengesetzte Änderung führt zurück?"},{"type":"H","value":"1. Endwert minus Anfangswert rechnen"},{"type":"M","value":" -6-(-2{,}5)=-6+2{,}5=-3{,}5"},{"type":"T","value":"Die negative Änderung bedeutet: Die Temperatur ist gefallen."},{"type":"H","value":"2. Den Endwert kontrollieren"},{"type":"M","value":" -2{,}5+(-3{,}5)=-6"},{"type":"H","value":"3. Den Rückweg nehmen"},{"type":"M","value":" -6+3{,}5=-2{,}5"},{"type":"T","value":"Zum Rückweg gehört die Gegenzahl der Änderung. Eine negative Zahl zu subtrahieren hätte einen Anstieg bewirkt."}]},"source-0":{"title":"Die Rechnung am Zahlenstrahl verfolgen","prompt":"","blocks":[{"type":"H","value":"Die Rechnung am Zahlenstrahl verfolgen"},{"type":"T","value":"Bei −3 + 5 starten wir bei −3. Eine positive Zahl addieren heißt nach rechts gehen: zuerst 3 Schritte bis null, dann noch 2. Bei 2 + (−5) gehen wir von 2 fünf Schritte nach links. Das <b>Vorzeichen</b> gehört zur Zahl; das <b>Rechenzeichen</b> sagt, was mit ihr geschieht."},{"type":"V","value":"R02"},{"type":"M","value":"-3+5=2\\qquad2+(-5)=-3"}],"prerequisites":["R01","N04"]},"source-1":{"title":"Subtrahieren heißt: die Gegenzahl addieren","prompt":"","blocks":[{"type":"H","value":"Subtrahieren heißt: die Gegenzahl addieren"},{"type":"T","value":"Die <b>Gegenzahl</b> macht eine Änderung rückgängig. Wenn wir −5 abziehen, nehmen wir eine Bewegung von fünf Schritten nach links zurück. Das führt fünf Schritte nach rechts. Darum wird aus „minus eine negative Zahl“ hier eine Addition der positiven Gegenzahl."},{"type":"M","value":"-3-(-5)=-3+5=2"},{"type":"T","value":"Dagegen führt −3 − 5 nach links und ergibt −8. Die beiden Minuszeichen bei −3 − (−5) dürfen nicht einfach überlesen werden: Eines bezeichnet die Subtraktion, das andere das Vorzeichen des zweiten Wertes."}],"prerequisites":["R01","N04"]},"source-2":{"title":"Dasselbe gilt für Brüche","prompt":"","blocks":[{"type":"H","value":"Dasselbe gilt für Brüche"},{"type":"M","value":"-\\frac12+\\frac34=-\\frac24+\\frac34=\\frac14"},{"type":"T","value":"Gleich große Viertel machen die Änderung sichtbar: Zwei Viertel links von null und drei Viertel nach rechts ergeben ein Viertel rechts von null. Die Vorzeichenregel ersetzt also nicht das Gleichnamigmachen der Brüche."}],"prerequisites":["R01","N04"]}},"taskExamples":{"R02_MINI":"transfer","R02_L4_01":"transfer","R02_L4_02":"transfer","R02_L4_03":"transfer","R02_L4_04":"transfer","R02_L4_05":"transfer","R02_POOL_01":"transfer","R02_POOL_02":"transfer","R02_POOL_03":"transfer","R02_POOL_04":"transfer","R02_NEU_01":"transfer","R02_NEU_02":"transfer","R02_NEU_03":"transfer","R02_NEU_04":"transfer","R02_NEU_05":"transfer","R02_NEU_06":"transfer","R02_TEST_01":"transfer","R02_TEST_02":"transfer","R02_TEST_03":"transfer","R02_NEU_07":"transfer","R02_NEU_08":"transfer","R02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"R03":{"default":"transfer","variants":{"transfer":{"title":"Das Vorzeichen aus einer fehlenden Zahl gewinnen","prompt":"Gesucht ist eine Zahl, die mit −4 multipliziert +18 ergibt. Prüfe das Ergebnis anschließend mit einer Rechnung, in der drei negative Faktoren vorkommen.","prerequisites":["R01","D02"],"blocks":[{"type":"H","value":"Das Vorzeichen aus einer fehlenden Zahl gewinnen"},{"type":"T","value":"Gesucht ist eine Zahl, die mit −4 multipliziert +18 ergibt. Prüfe das Ergebnis anschließend mit einer Rechnung, in der drei negative Faktoren vorkommen."},{"type":"H","value":"1. Die Umkehraufgabe bilden"},{"type":"M","value":"(-4)\\cdot x=18;\\qquad x=18:(-4)=-4{,}5"},{"type":"H","value":"2. Das Vorzeichen begründen und prüfen"},{"type":"M","value":"(-4)\\cdot(-4{,}5)=18"},{"type":"T","value":"Ein negativer Faktor braucht einen zweiten negativen Faktor, damit das Produkt positiv ist."},{"type":"H","value":"3. Einen weiteren negativen Faktor hinzufügen"},{"type":"M","value":"(-4)\\cdot(-4{,}5)\\cdot(-2)=18\\cdot(-2)=-36"},{"type":"T","value":"Zwei Minusfaktoren ergeben ein Plus; der dritte macht das Gesamtprodukt wieder negativ."}]},"source-0":{"title":"Warum Minus mal Minus positiv ist","prompt":"","blocks":[{"type":"H","value":"Warum Minus mal Minus positiv ist"},{"type":"T","value":"Wir betrachten Produkte mit dem ersten Faktor −2. Wird der zweite Faktor um 1 kleiner, steigt das Produkt jeweils um 2. Dieses Muster muss auch über null hinaus passen, damit das Verteilen auf Summen gültig bleibt."},{"type":"V","value":"R03"},{"type":"M","value":"(-2)\\cdot(-3)=6"},{"type":"T","value":"Ein positiver und ein negativer <b>Faktor</b> ergeben ein negatives <b>Produkt</b>; zwei negative Faktoren ergeben ein positives. Für die Größe rechnest du mit den <b>Beträgen</b>, also den Abständen von null. Die Regeln gelten genauso für Brüche."},{"type":"M","value":"\\left(-\\frac23\\right)\\cdot\\left(-\\frac34\\right)=\\frac12"}],"prerequisites":["R01","B06","B07"]},"source-1":{"title":"Division durch die Multiplikation erklären","prompt":"","blocks":[{"type":"H","value":"Division durch die Multiplikation erklären"},{"type":"T","value":"Für (−12) : 3 suchen wir die Zahl, die mit 3 multipliziert −12 ergibt. Das ist −4. Für (−12) : (−3) brauchen wir +4. Deshalb gilt beim Quotienten dieselbe Vorzeichenregel wie beim Produkt."},{"type":"M","value":"(-12):3=-4\\qquad(-12):(-3)=4"},{"type":"M","value":"\\left(-\\frac34\\right):\\left(-\\frac12\\right)=\\frac34\\cdot2=\\frac32"},{"type":"T","value":"Hier ist das Vorzeichen positiv; für den Betrag multiplizieren wir mit dem <b>Kehrwert</b> des Divisors. Die Probe lautet 3/2 · (−1/2) = −3/4. Durch null wird auch bei rationalen Zahlen nie geteilt."}],"prerequisites":["R01","B06","B07"]}},"taskExamples":{"R03_MINI":"transfer","R03_L4_01":"transfer","R03_L4_02":"transfer","R03_L4_03":"transfer","R03_L4_04":"transfer","R03_L4_05":"transfer","R03_POOL_01":"transfer","R03_POOL_02":"transfer","R03_POOL_03":"transfer","R03_POOL_04":"transfer","R03_NEU_01":"transfer","R03_NEU_02":"transfer","R03_NEU_03":"transfer","R03_NEU_04":"transfer","R03_NEU_05":"transfer","R03_NEU_06":"transfer","R03_TEST_01":"transfer","R03_TEST_02":"transfer","R03_TEST_03":"transfer","R03_NEU_07":"transfer","R03_NEU_08":"transfer","R03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"R04":{"default":"transfer","variants":{"transfer":{"title":"Ein Minus an zwei verschiedenen Stellen","prompt":"Vergleiche A(x)=−x² und B(x)=(−x)² für x=−3. Erkläre danach ohne neue Rechnung, was bei x=3 gleich bleibt.","prerequisites":["R02","R03","T01"],"blocks":[{"type":"H","value":"Ein Minus an zwei verschiedenen Stellen"},{"type":"T","value":"Vergleiche A(x)=−x² und B(x)=(−x)² für x=−3. Erkläre danach ohne neue Rechnung, was bei x=3 gleich bleibt."},{"type":"H","value":"1. Die eingesetzte Zahl klammern"},{"type":"M","value":"A(-3)=-(-3)^2=-9;\\qquad B(-3)=(-(-3))^2=3^2=9"},{"type":"H","value":"2. Die Reichweite der Potenz benennen"},{"type":"T","value":"Bei A steht ein Minus vor dem Quadrat. Bei B gehört das Minus innerhalb der Basis zum Quadrat. Die äußerlich ähnlichen Zeichen beschreiben andere Rechenpläne."},{"type":"H","value":"3. Die positive Eingabe vergleichen"},{"type":"M","value":"A(3)=-3^2=-9;\\qquad B(3)=(-3)^2=9"},{"type":"T","value":"Das Quadrieren macht die beiden Eingabevorzeichen gleich. Das äußere Minus bei A bleibt trotzdem erhalten."}]},"source-0":{"title":"Gehört das Minus zur Basis?","prompt":"","blocks":[{"type":"H","value":"Gehört das Minus zur Basis?"},{"type":"T","value":"Eine <b>Potenz</b> steht hier für wiederholtes Multiplizieren. Die <b>Basis</b> ist der Faktor, der wiederholt wird; der <b>Exponent</b> gibt seine Anzahl an. Bei (−3)² ist die ganze Zahl −3 die Basis. Bei −3² steht das Minus außerhalb der Potenz."},{"type":"M","value":"(-3)^2=(-3)\\cdot(-3)=9"},{"type":"M","value":"-3^2=-(3\\cdot3)=-9"},{"type":"T","value":"Die Klammer ist also entscheidend. Zwei negative Faktoren ergeben Plus. Bei drei negativen Faktoren bleibt ein Minus übrig; deshalb ist eine ungerade Potenz einer negativen Basis negativ."},{"type":"M","value":"(-3)^3=(-3)\\cdot(-3)\\cdot(-3)=-27"}],"prerequisites":["R02","R03","N04"]},"source-1":{"title":"In einen Term einsetzen, ohne seine Struktur zu ändern","prompt":"","blocks":[{"type":"H","value":"In einen Term einsetzen, ohne seine Struktur zu ändern"},{"type":"T","value":"Wir suchen den <b>Termwert</b> von T(x) = 2 − x² bei x = −3. Ersetze nur x, und zwar durch die vollständige negative Zahl in Klammern. Das schon vorhandene Minus bleibt davor stehen."},{"type":"M","value":"T(-3)=2-(-3)^2=2-9=-7"},{"type":"T","value":"Rückwärts hat x² = 9 zwei Lösungen: 3 und −3. Beide haben den Betrag 3 und dasselbe Quadrat. Es wäre deshalb falsch, bei einer solchen Frage automatisch nur die positive Zahl zu nennen."},{"type":"M","value":"x^2=9\\quad\\Longrightarrow\\quad x\\in\\{-3;3\\}"}],"prerequisites":["R02","R03","N04"]}},"taskExamples":{"R04_MINI":"transfer","R04_L4_01":"transfer","R04_L4_02":"transfer","R04_L4_03":"transfer","R04_L4_04":"transfer","R04_L4_05":"transfer","R04_POOL_01":"transfer","R04_POOL_02":"transfer","R04_POOL_03":"transfer","R04_POOL_04":"transfer","R04_NEU_01":"transfer","R04_NEU_02":"transfer","R04_NEU_03":"transfer","R04_NEU_04":"transfer","R04_NEU_05":"transfer","R04_NEU_06":"transfer","R04_TEST_01":"transfer","R04_TEST_02":"transfer","R04_TEST_03":"transfer","R04_NEU_07":"transfer","R04_NEU_08":"transfer","R04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"R05":{"default":"transfer","variants":{"transfer":{"title":"Mehrere Bewegungen zusammen oder einzeln lesen","prompt":"Ein Aufzug startet im zweiten Untergeschoss. Er fährt 5 Etagen hoch, 4 herunter und 2 hoch. Ein Protokoll meldet nur „insgesamt 3 nach oben“. Prüfe, was daraus folgt.","prerequisites":["R01","R02"],"blocks":[{"type":"H","value":"Mehrere Bewegungen zusammen oder einzeln lesen"},{"type":"T","value":"Ein Aufzug startet im zweiten Untergeschoss. Er fährt 5 Etagen hoch, 4 herunter und 2 hoch. Ein Protokoll meldet nur „insgesamt 3 nach oben“. Prüfe, was daraus folgt."},{"type":"H","value":"1. Die Änderungen zusammenfassen"},{"type":"M","value":"+5-4+2=+3"},{"type":"T","value":"Die Gesamtänderung ist unabhängig von der Anfangsetage."},{"type":"H","value":"2. Mit dem Anfangswert verbinden"},{"type":"M","value":" -2+3=1"},{"type":"T","value":"Der Aufzug endet in Etage 1, obwohl er insgesamt 3 Etagen aufwärts versetzt wurde."},{"type":"H","value":"3. Den Weg schrittweise kontrollieren"},{"type":"M","value":" -2\\to3\\to-1\\to1"},{"type":"T","value":"Endwert und Änderung sind verschiedene Zahlen. Aus „3 nach oben“ allein kann man keine Endetage bestimmen."}]},"source-0":{"title":"Temperatur: Wert und Änderung unterscheiden","prompt":"","blocks":[{"type":"H","value":"Temperatur: Wert und Änderung unterscheiden"},{"type":"T","value":"Morgens sind es −4 °C, mittags +2 °C. Das <b>Vorzeichen</b> eines Wertes beschreibt seine Lage zu null. Das Vorzeichen einer <b>Änderung</b> beschreibt dagegen die Richtung: Ein Anstieg ist positiv, ein Rückgang negativ."},{"type":"V","value":"R05"},{"type":"M","value":"\\Delta=2-(-4)=6\\quad\\mathrm{(^{\\circ}C)}"},{"type":"T","value":"Der griechische Buchstabe Δ („Delta“) steht hier für die Änderung. Wir ziehen den Anfangswert vom Endwert ab, weil wir die Strecke vom Anfang zum Ende suchen. Die Temperatur ist um 6 °C gestiegen, nicht um 2 °C."},{"type":"M","value":"\\mathrm{Endwert}=\\mathrm{Anfangswert}+\\mathrm{Aenderung}"}],"prerequisites":["R02","R03"]},"source-1":{"title":"Rückwärts vom Endwert zum Anfang","prompt":"","blocks":[{"type":"H","value":"Rückwärts vom Endwert zum Anfang"},{"type":"T","value":"Nach einer Einzahlung von 25 Euro steht ein Konto bei 7 Euro. Die Einzahlung ist +25 Euro. Um den Anfangswert zu finden, machen wir diese Änderung rückgängig und ziehen 25 Euro ab."},{"type":"M","value":"7-25=-18\\quad\\mathrm{(Euro)}\\qquad-18+25=7"},{"type":"T","value":"Der anfängliche Kontostand war −18 Euro. Werden anschließend 10 Euro abgebucht, ist die Änderung −10 Euro und der neue Stand −3 Euro. Ein negativer Stand und eine negative Änderung sind verschiedene Aussagen: Ein Konto kann negativ sein und trotzdem gerade steigen."}],"prerequisites":["R02","R03"]}},"taskExamples":{"R05_MINI":"transfer","R05_L4_01":"transfer","R05_L4_02":"transfer","R05_L4_03":"transfer","R05_L4_04":"transfer","R05_L4_05":"transfer","R05_POOL_01":"transfer","R05_POOL_02":"transfer","R05_POOL_03":"transfer","R05_POOL_04":"transfer","R05_NEU_01":"transfer","R05_NEU_02":"transfer","R05_NEU_03":"transfer","R05_NEU_04":"transfer","R05_NEU_05":"transfer","R05_NEU_06":"transfer","R05_TEST_01":"transfer","R05_TEST_02":"transfer","R05_TEST_03":"transfer","R05_NEU_07":"transfer","R05_NEU_08":"transfer","R05_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"P01":{"default":"transfer","variants":{"transfer":{"title":"Prozentpunkte sind nicht Prozent des Alten","prompt":"Der Anteil der Radfahrenden steigt von 20 % auf 25 %. Beschreibe den neuen Anteil als Bruch und unterscheide zwei Arten der Veränderungsangabe.","prerequisites":["B02","B07"],"blocks":[{"type":"H","value":"Prozentpunkte sind nicht Prozent des Alten"},{"type":"T","value":"Der Anteil der Radfahrenden steigt von 20 % auf 25 %. Beschreibe den neuen Anteil als Bruch und unterscheide zwei Arten der Veränderungsangabe."},{"type":"H","value":"1. Den neuen Anteil umschreiben"},{"type":"M","value":"25\\%=\\frac{25}{100}=\\frac14=0{,}25"},{"type":"H","value":"2. Die Prozentangaben subtrahieren"},{"type":"T","value":"25 % minus 20 % sind 5 Prozentpunkte. Hier werden Anteile am selben Ganzen verglichen."},{"type":"H","value":"3. Mit dem alten Anteil vergleichen"},{"type":"M","value":"\\frac{25-20}{20}=\\frac14=25\\%"},{"type":"T","value":"Der Anteil ist relativ zu seinem alten Wert um 25 % gestiegen. „5 Prozentpunkte“ und „25 % mehr“ können also dieselbe Änderung beschreiben."}]},"source-0":{"title":"35 Prozent in drei Schreibweisen","prompt":"","blocks":[{"type":"H","value":"35 Prozent in drei Schreibweisen"},{"type":"T","value":"<b>Prozent</b> bedeutet „von hundert“. 35 % sind also 35 von 100 gleich großen Teilen eines Ganzen. Der <b>Prozentsatz</b> beschreibt einen Anteil und hat keine Einheit wie Euro oder Zentimeter."},{"type":"V","value":"P01"},{"type":"M","value":"35\\%=\\frac{35}{100}=\\frac7{20}=0{,}35"},{"type":"T","value":"Zum Bruch ersetzen wir das Prozentzeichen durch den Nenner 100 und kürzen mit 5. Zur Dezimalzahl teilen wir 35 durch 100. Rückwärts entspricht 0,35 genau 35 Hundertsteln und damit 35 %."}],"prerequisites":["D03"]},"source-1":{"title":"Auch andere Brüche und mehr als ein Ganzes","prompt":"","blocks":[{"type":"H","value":"Auch andere Brüche und mehr als ein Ganzes"},{"type":"M","value":"\\frac38=\\frac{37{,}5}{100}=37{,}5\\%=0{,}375"},{"type":"T","value":"Ein Prozentsatz muss keine ganze Zahl sein. Drei Achtel entsprechen 37,5 Hundertsteln. Du kannst dafür auch zuerst 3 : 8 = 0,375 rechnen und den Dezimalanteil in Hundertsteln ausdrücken."},{"type":"M","value":"125\\%=\\frac{125}{100}=1{,}25=1\\frac14"},{"type":"T","value":"100 % sind ein Ganzes; 125 % sind ein Ganzes plus ein Viertel davon. Beispielsweise sind 125 % von 80 Euro gleich 100 Euro. Die Aussage braucht einen Bezugswert: 125 % allein sagt noch nicht, wie viele Euro gemeint sind."}],"prerequisites":["D03"]}},"taskExamples":{"P01_MINI":"transfer","P01_L4_01":"transfer","P01_L4_02":"transfer","P01_L4_03":"transfer","P01_L4_04":"transfer","P01_L4_05":"transfer","P01_POOL_01":"transfer","P01_POOL_02":"transfer","P01_POOL_03":"transfer","P01_POOL_04":"transfer","P01_NEU_01":"transfer","P01_NEU_02":"transfer","P01_NEU_03":"transfer","P01_NEU_04":"transfer","P01_NEU_05":"transfer","P01_NEU_06":"transfer","P01_TEST_01":"transfer","P01_TEST_02":"transfer","P01_TEST_03":"transfer","P01_NEU_07":"transfer","P01_NEU_08":"transfer","P01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"P02":{"default":"transfer","variants":{"transfer":{"title":"Zwei Bezugsgrößen im selben Bericht","prompt":"In einem Kurs sind 24 Lernende, davon 9 im Chor. Nach einem Wechsel sind es 30 Lernende und 12 im Chor. Vergleiche Anzahl und Anteil.","prerequisites":["P01","D02"],"blocks":[{"type":"H","value":"Zwei Bezugsgrößen im selben Bericht"},{"type":"T","value":"In einem Kurs sind 24 Lernende, davon 9 im Chor. Nach einem Wechsel sind es 30 Lernende und 12 im Chor. Vergleiche Anzahl und Anteil."},{"type":"H","value":"1. Die beiden Anteile bestimmen"},{"type":"M","value":"\\frac9{24}=0{,}375=37{,}5\\%;\\qquad\\frac{12}{30}=0{,}4=40\\%"},{"type":"H","value":"2. Anzahl und Prozentsatz getrennt vergleichen"},{"type":"T","value":"Die Anzahl steigt um 3. Der Anteil steigt um 2,5 Prozentpunkte. Der Grundwert ist von 24 auf 30 gewachsen."},{"type":"H","value":"3. Eine Rückrechnung prüfen"},{"type":"M","value":"0{,}4\\cdot30=12"},{"type":"T","value":"Nur mit dem neuen Grundwert ergibt der neue Prozentsatz wieder die richtige Anzahl. 40 % von 24 wären eine andere Frage."}]},"source-0":{"title":"Ein Zusammenhang – drei verschiedene Fragen","prompt":"","blocks":[{"type":"H","value":"Ein Zusammenhang – drei verschiedene Fragen"},{"type":"T","value":"Von 80 Kindern kommen 20 mit dem Fahrrad. Der <b>Grundwert G</b> ist das Ganze, also 80 Kinder. Der <b>Prozentwert W</b> ist der betrachtete Anteil, also 20 Kinder. Der <b>Prozentsatz p</b> beschreibt das Verhältnis; hier schreiben wir p als Dezimalzahl."},{"type":"V","value":"P02"},{"type":"M","value":"p=\\frac WG=\\frac{20}{80}=0{,}25=25\\%"},{"type":"T","value":"Wir teilen durch 80, weil wir wissen wollen, welcher Anteil des Ganzen 20 ist. Nicht die 20 Kinder sind der Bezugswert, sondern alle 80 Kinder."}],"prerequisites":["P01","B08","F01"]},"source-1":{"title":"Wenn stattdessen der Anteil gesucht ist","prompt":"","blocks":[{"type":"H","value":"Wenn stattdessen der Anteil gesucht ist"},{"type":"M","value":"W=p\\cdot G=0{,}25\\cdot80=20\\quad\\mathrm{(Kinder)}"},{"type":"T","value":"Multiplizieren mit 0,25 nimmt ein Viertel des Ganzen. Kennst du umgekehrt nur „20 Kinder sind 25 %“, musst du diese Multiplikation rückgängig machen, um das Ganze zu erhalten."},{"type":"M","value":"G=\\frac Wp=\\frac{20}{0{,}25}=80\\quad\\mathrm{(Kinder)}"},{"type":"T","value":"Prüfe jede Rechnung an derselben Situation: 25 % von 80 sind 20. G und W tragen hier die Einheit Kinder, p trägt keine Einheit. Die Formeln mit Division setzen einen Grundwert ungleich 0 bzw. einen Prozentsatz ungleich 0 voraus."}],"prerequisites":["P01","B08","F01"]}},"taskExamples":{"P02_MINI":"transfer","P02_L4_01":"transfer","P02_L4_02":"transfer","P02_L4_03":"transfer","P02_L4_04":"transfer","P02_L4_05":"transfer","P02_POOL_01":"transfer","P02_POOL_02":"transfer","P02_POOL_03":"transfer","P02_POOL_04":"transfer","P02_NEU_01":"transfer","P02_NEU_02":"transfer","P02_NEU_03":"transfer","P02_NEU_04":"transfer","P02_NEU_05":"transfer","P02_NEU_06":"transfer","P02_TEST_01":"transfer","P02_TEST_02":"transfer","P02_TEST_03":"transfer","P02_NEU_07":"transfer","P02_NEU_08":"transfer","P02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"P03":{"default":"transfer","variants":{"transfer":{"title":"Welche Erhöhung macht einen Rabatt rückgängig?","prompt":"Ein Preis von 120 Euro wird um 25 % gesenkt. Anschließend soll der alte Preis wieder erreicht werden. Muss er um 25 % steigen?","prerequisites":["P02","B07"],"blocks":[{"type":"H","value":"Welche Erhöhung macht einen Rabatt rückgängig?"},{"type":"T","value":"Ein Preis von 120 Euro wird um 25 % gesenkt. Anschließend soll der alte Preis wieder erreicht werden. Muss er um 25 % steigen?"},{"type":"H","value":"1. Den neuen Preis berechnen"},{"type":"M","value":"120\\cdot0{,}75=90"},{"type":"H","value":"2. Die nötige Erhöhung auf den neuen Preis beziehen"},{"type":"M","value":"\\frac{120-90}{90}=\\frac13"},{"type":"T","value":"Die nötigen 30 Euro sind ein Drittel von 90 Euro. Benötigt werden 33 1/3 % Erhöhung."},{"type":"H","value":"3. Den Faktor prüfen"},{"type":"M","value":"90\\cdot\\frac43=120"},{"type":"T","value":"Eine Erhöhung um 25 % ergäbe dagegen nur 112,50 Euro. Jeder Prozentsatz braucht seinen jeweiligen Grundwert."}]},"source-0":{"title":"20 Prozent Rabatt auf 80 Euro","prompt":"","blocks":[{"type":"H","value":"20 Prozent Rabatt auf 80 Euro"},{"type":"T","value":"Ein Rabatt von 20 % lässt 80 % des alten Preises übrig. Der <b>Änderungsfaktor</b> ist daher 0,8. Er sagt, welchen Anteil des alten Wertes der neue Wert ausmacht. Der alte Preis ist die Bezugsgröße für den Rabatt."},{"type":"M","value":"80\\cdot(1-0{,}20)=80\\cdot0{,}8=64\\quad\\mathrm{(Euro)}"},{"type":"V","value":"P03"},{"type":"T","value":"Rückwärts sind 64 Euro also 80 %, nicht 100 %. Wir teilen durch 0,8, weil dies die Multiplikation mit dem Faktor rückgängig macht. 20 % auf 64 Euro aufzuschlagen wäre eine andere Rechnung mit einem anderen Grundwert."},{"type":"M","value":"64:0{,}8=80\\quad\\mathrm{(Euro)}"}],"prerequisites":["P02"]},"source-1":{"title":"Zwei Änderungen beziehen sich auf zwei Ausgangswerte","prompt":"","blocks":[{"type":"H","value":"Zwei Änderungen beziehen sich auf zwei Ausgangswerte"},{"type":"T","value":"Ein Preis steigt zunächst um 20 %, danach fällt er um 20 %. Beim Anstieg ist der Faktor 1,2, beim Rückgang 0,8. Der zweite Prozentsatz bezieht sich bereits auf den erhöhten Preis."},{"type":"M","value":"80\\cdot1{,}2=96\\qquad96\\cdot0{,}8=76{,}80"},{"type":"M","value":"1{,}2\\cdot0{,}8=0{,}96"},{"type":"T","value":"Am Ende bleiben 96 % des Anfangspreises: insgesamt 4 % weniger. Deshalb dürfen aufeinanderfolgende Prozentänderungen nicht einfach addiert oder gegeneinander gestrichen werden. Multipliziere die zugehörigen Faktoren."}],"prerequisites":["P02"]}},"taskExamples":{"P03_MINI":"transfer","P03_L4_01":"transfer","P03_L4_02":"transfer","P03_L4_03":"transfer","P03_L4_04":"transfer","P03_L4_05":"transfer","P03_POOL_01":"transfer","P03_POOL_02":"transfer","P03_POOL_03":"transfer","P03_POOL_04":"transfer","P03_NEU_01":"transfer","P03_NEU_02":"transfer","P03_NEU_03":"transfer","P03_NEU_04":"transfer","P03_NEU_05":"transfer","P03_NEU_06":"transfer","P03_TEST_01":"transfer","P03_TEST_02":"transfer","P03_TEST_03":"transfer","P03_NEU_07":"transfer","P03_NEU_08":"transfer","P03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"P04":{"default":"transfer","variants":{"transfer":{"title":"Bonus und Zinssatz getrennt vergleichen","prompt":"Ein Kapital von 600 Euro liegt genau ein Jahr auf einem Konto. Angebot A zahlt 2 % Zinsen und 4 Euro Bonus, Angebot B 3 % ohne Bonus. Beide Angaben gelten ohne Gebühren.","prerequisites":["P02","E02"],"blocks":[{"type":"H","value":"Bonus und Zinssatz getrennt vergleichen"},{"type":"T","value":"Ein Kapital von 600 Euro liegt genau ein Jahr auf einem Konto. Angebot A zahlt 2 % Zinsen und 4 Euro Bonus, Angebot B 3 % ohne Bonus. Beide Angaben gelten ohne Gebühren."},{"type":"H","value":"1. Zinsen und Bonus getrennt rechnen"},{"type":"M","value":"A:600\\cdot0{,}02+4=16;\\qquad B:600\\cdot0{,}03=18"},{"type":"T","value":"B liefert bei 600 Euro zwei Euro mehr. Der feste Bonus ist kein Zinssatz."},{"type":"H","value":"2. Den Gleichstand rückwärts finden"},{"type":"T","value":"B zahlt einen Prozentpunkt mehr Zinsen. Dieser zusätzliche Anteil muss 4 Euro erreichen, um den Bonus auszugleichen."},{"type":"M","value":"0{,}01\\cdot K=4;\\qquad K=400"},{"type":"H","value":"3. Die Grenze prüfen"},{"type":"M","value":"A:400\\cdot0{,}02+4=12;\\qquad B:400\\cdot0{,}03=12"},{"type":"T","value":"Unter 400 Euro bringt A mehr Zinsen plus Bonus, über 400 Euro B. Betrachtet wird nur ein ganzes Jahr."}]},"source-0":{"title":"Was 3 Prozent pro Jahr bedeuten","prompt":"","blocks":[{"type":"H","value":"Was 3 Prozent pro Jahr bedeuten"},{"type":"T","value":"Wir betrachten eine Anlage von 600 Euro für genau ein Jahr, ohne Gebühren und ohne Zinseszins. Das angelegte Geld heißt <b>Kapital K</b>. Die Vergütung heißt <b>Zinsen Z</b>. Der <b>Zinssatz</b> 3 % p.a. bedeutet „3 Prozent pro Jahr“; als Dezimalzahl ist p = 0,03."},{"type":"M","value":"Z=K\\cdot p=600\\cdot0{,}03=18\\quad\\mathrm{(Euro)}"},{"type":"T","value":"Die Zinsen sind der Prozentwert, das Kapital ist der Grundwert. Für den Betrag am Jahresende addieren wir die Zinsen zum Kapital. Die 18 Euro sind also nicht das gesamte Guthaben."},{"type":"M","value":"600+18=618\\quad\\mathrm{(Euro)}"}],"prerequisites":["P02"]},"source-1":{"title":"Aus den Zinsen auf das Kapital schließen","prompt":"","blocks":[{"type":"H","value":"Aus den Zinsen auf das Kapital schließen"},{"type":"T","value":"Sind nur 18 Euro Jahreszinsen und 3 % bekannt, teilen wir durch 0,03. Wir suchen das Ganze, von dem 18 Euro drei Hundertstel sind."},{"type":"M","value":"K=Z:p=18:0{,}03=600\\quad\\mathrm{(Euro)}"},{"type":"T","value":"Zum Vergleich bringen 300 Euro bei 6 % ebenfalls 18 Euro Jahreszinsen. Das halbe Kapital wird durch den doppelten Zinssatz ausgeglichen. Ein höherer Zinssatz allein garantiert daher keinen höheren Zinsbetrag."},{"type":"T","value":"Die Zeitangabe gehört zum Modell: 3 % p.a. bedeutet nicht 3 % jeden Monat. Bei anderen Laufzeiten muss die Zeitregel ausdrücklich festgelegt werden; dieses Blatt rechnet jeweils ein volles Jahr."}],"prerequisites":["P02"]}},"taskExamples":{"P04_MINI":"transfer","P04_L4_01":"transfer","P04_L4_02":"transfer","P04_L4_03":"transfer","P04_L4_04":"transfer","P04_L4_05":"transfer","P04_POOL_01":"transfer","P04_POOL_02":"transfer","P04_POOL_03":"transfer","P04_POOL_04":"transfer","P04_NEU_01":"transfer","P04_NEU_02":"transfer","P04_NEU_03":"transfer","P04_NEU_04":"transfer","P04_NEU_05":"transfer","P04_NEU_06":"transfer","P04_TEST_01":"transfer","P04_TEST_02":"transfer","P04_TEST_03":"transfer","P04_NEU_07":"transfer","P04_NEU_08":"transfer","P04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T01":{"default":"transfer","variants":{"transfer":{"title":"Zwei Eingaben, ein Rechenplan","prompt":"Eine Maschine verwendet V(a,b)=2(a+b)²−b. Setze a=−2 und b=5 ein. Vergleiche danach, was passiert, wenn nur das Vorzeichen von a wechselt.","prerequisites":["R02","R04","N04"],"blocks":[{"type":"H","value":"Zwei Eingaben, ein Rechenplan"},{"type":"T","value":"Eine Maschine verwendet V(a,b)=2(a+b)²−b. Setze a=−2 und b=5 ein. Vergleiche danach, was passiert, wenn nur das Vorzeichen von a wechselt."},{"type":"H","value":"1. Beide Platzhalter vollständig ersetzen"},{"type":"M","value":"V(-2,5)=2\\cdot((-2)+5)^2-5"},{"type":"T","value":"Die negative Eingabe erhält Klammern. Jedes a wird durch −2, jedes b durch 5 ersetzt."},{"type":"H","value":"2. Von innen nach außen rechnen"},{"type":"M","value":"V(-2,5)=2\\cdot3^2-5=2\\cdot9-5=13"},{"type":"T","value":"Erst wird die innere Summe gebildet, dann quadriert, dann verdoppelt und zuletzt 5 abgezogen."},{"type":"H","value":"3. Den geänderten Rechenauftrag vergleichen"},{"type":"M","value":"V(2,5)=2\\cdot(2+5)^2-5=98-5=93"},{"type":"T","value":"Der Term ist die Anleitung. Die Eingaben dürfen wechseln; die Reihenfolge und die Positionen der Variablen bleiben."}]},"source-0":{"title":"Eine Rechenvorschrift lesen","prompt":"","blocks":[{"type":"H","value":"Eine Rechenvorschrift lesen"},{"type":"T","value":"T(x) = 3x − 7 beschreibt einen <b>Term</b>, also einen Rechenausdruck. Die <b>Variable x</b> steht für eine einsetzbare Zahl. 3x bedeutet 3 · x; die 3 heißt <b>Koeffizient</b>, der Zahlenfaktor vor x. −7 ist ein konstanter Summand, weil er sich beim Einsetzen nicht ändert."},{"type":"M","value":"T(-2)=3\\cdot(-2)-7=-6-7=-13"},{"type":"T","value":"Wir ersetzen jedes x durch dieselbe ganze Zahl −2. Die Klammer hält deren Minus mit der Zahl zusammen. Erst wird multipliziert, dann subtrahiert. Der entstandene Zahlenwert −13 heißt <b>Termwert</b>."}],"prerequisites":["N04","R02"]},"source-1":{"title":"Von innen nach außen denken","prompt":"","blocks":[{"type":"H","value":"Von innen nach außen denken"},{"type":"T","value":"Beim Term U(x) = 2(x + 2)² ist die letzte Rechenoperation eine Multiplikation mit 2. Davor wird die Summe quadriert; ganz innen wird 2 addiert. Dieser <b>Rechenplan</b> bestimmt, in welcher Reihenfolge wir arbeiten."},{"type":"V","value":"T01"},{"type":"M","value":"U(-3)=2\\cdot(-3+2)^2=2\\cdot(-1)^2=2"},{"type":"T","value":"Das Quadrat betrifft die ganze Klammer. 2(x + 2)² bedeutet daher etwas anderes als 2x + 4. Zum Vergleich kann man Werte einsetzen; einen allgemeinen Nachweis der Gleichwertigkeit liefern aber Umformungen, die für alle erlaubten x gelten."}],"prerequisites":["N04","R02"]}},"taskExamples":{"T01_MINI":"transfer","T01_L4_01":"transfer","T01_L4_02":"transfer","T01_L4_03":"transfer","T01_L4_04":"transfer","T01_L4_05":"transfer","T01_POOL_01":"transfer","T01_POOL_02":"source-1","T01_POOL_03":"transfer","T01_POOL_04":"transfer","T01_NEU_01":"transfer","T01_NEU_02":"transfer","T01_NEU_03":"transfer","T01_NEU_04":"transfer","T01_NEU_05":"transfer","T01_NEU_06":"source-1","T01_TEST_01":"transfer","T01_TEST_02":"source-1","T01_TEST_03":"transfer","T01_NEU_07":"transfer","T01_NEU_08":"transfer","T01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T02":{"default":"transfer","variants":{"transfer":{"title":"Eine fehlende Stelle mit gleichartigen Termen finden","prompt":"Für jede Zahl x soll 3x + □x + 2 = 7x + 2 gelten. Eine zweite Person schlägt stattdessen 3x + 4x² + 2 vor. Kläre beide Aussagen.","prerequisites":["T01","R04"],"blocks":[{"type":"H","value":"Eine fehlende Stelle mit gleichartigen Termen finden"},{"type":"T","value":"Für jede Zahl x soll 3x + □x + 2 = 7x + 2 gelten. Eine zweite Person schlägt stattdessen 3x + 4x² + 2 vor. Kläre beide Aussagen."},{"type":"H","value":"1. Die Koeffizienten vergleichen"},{"type":"T","value":"Die konstanten Summanden stimmen schon überein. Vor x müssen die Faktoren zusammen 7 ergeben: 3 + □ = 7. Also gehört 4 in die Lücke."},{"type":"H","value":"2. Den Variablenteil erhalten"},{"type":"M","value":"3x+4x+2=7x+2"},{"type":"T","value":"Wir zählen x-Terme. Das x wird dabei nicht mit sich selbst multipliziert."},{"type":"H","value":"3. Die falsche Alternative prüfen"},{"type":"M","value":"x=2:\\quad3\\cdot2+4\\cdot2^2+2=24;\\quad7\\cdot2+2=16"},{"type":"T","value":"Eine einzige nicht passende Einsetzung widerlegt eine behauptete Identität. x und x² sind unterschiedliche Termarten."}]},"source-0":{"title":"Was lässt sich gemeinsam zählen?","prompt":"","blocks":[{"type":"H","value":"Was lässt sich gemeinsam zählen?"},{"type":"T","value":"Im Term 3x + 4 − x + 2x² + 2x − 1 sind die durch Plus bzw. Minus verbundenen Teile <b>Summanden</b>. Schreibe −x gedanklich als (−1) · x. Der Zahlenfaktor vor dem <b>Variablenteil</b> heißt <b>Koeffizient</b>; bei −x ist er −1."},{"type":"M","value":"3x+4-x+2x^2+2x-1"},{"type":"T","value":"3x, −x und 2x sind <b>gleichartig</b>, denn ihr Variablenteil ist jeweils x. x² ist ein anderer Typ: x · x statt x. Die Zahlen 4 und −1 sind konstante Summanden ohne Variable. Wir ordnen mit den Vorzeichen um und sammeln nur gleiche Typen."},{"type":"M","value":"=(3-1+2)x+2x^2+(4-1)"},{"type":"M","value":"=4x+2x^2+3"},{"type":"V","value":"T02"},{"type":"T","value":"Warum bleibt x stehen? Drei x-Einheiten minus eine x-Einheit plus zwei x-Einheiten sind vier x-Einheiten. Wir zählen ihre Anzahl, die Einheit selbst bleibt dieselbe. Dagegen können wir 4x und 3 nicht zu 7x machen: Für x = 2 wäre links 11 und rechts 14."}],"prerequisites":["T01"]},"source-1":{"title":"Einen Koeffizienten rückwärts finden","prompt":"","blocks":[{"type":"H","value":"Einen Koeffizienten rückwärts finden"},{"type":"M","value":"cx+2x=5x\\quad\\Longrightarrow\\quad c+2=5\\quad\\Longrightarrow\\quad c=3"},{"type":"T","value":"Die Gleichheit soll für alle x gelten. Deshalb müssen die Anzahlen der x-Einheiten übereinstimmen. Einzelne Sonderwerte wie x = 0 reichen dafür nicht als Begründung."}],"prerequisites":["T01"]}},"taskExamples":{"T02_MINI":"transfer","T02_L4_01":"transfer","T02_L4_02":"transfer","T02_L4_03":"transfer","T02_L4_04":"transfer","T02_L4_05":"transfer","T02_POOL_01":"transfer","T02_POOL_02":"transfer","T02_POOL_03":"transfer","T02_POOL_04":"transfer","T02_NEU_01":"transfer","T02_NEU_02":"transfer","T02_NEU_03":"transfer","T02_NEU_04":"transfer","T02_NEU_05":"transfer","T02_NEU_06":"transfer","T02_TEST_01":"transfer","T02_TEST_02":"transfer","T02_TEST_03":"transfer","T02_NEU_07":"transfer","T02_NEU_08":"transfer","T02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T03":{"default":"transfer","variants":{"transfer":{"title":"Ein Rabatt auf zwei verschiedene Preisbestandteile","prompt":"Vier Eintrittskarten kosten jeweils x Euro. Auf jede Karte gibt es 2 Euro Rabatt; anschließend kommt eine einmalige Gebühr von 3 Euro hinzu. Vergleiche das mit 2 Euro Rabatt auf den ganzen Einkauf.","prerequisites":["T01","T02"],"blocks":[{"type":"H","value":"Ein Rabatt auf zwei verschiedene Preisbestandteile"},{"type":"T","value":"Vier Eintrittskarten kosten jeweils x Euro. Auf jede Karte gibt es 2 Euro Rabatt; anschließend kommt eine einmalige Gebühr von 3 Euro hinzu. Vergleiche das mit 2 Euro Rabatt auf den ganzen Einkauf."},{"type":"H","value":"1. Den Rabatt je Karte ausdrücken"},{"type":"M","value":"4(x-2)+3=4x-8+3=4x-5"},{"type":"T","value":"Der Faktor 4 wirkt auf beide Summanden in der Klammer."},{"type":"H","value":"2. Den einmaligen Rabatt ausdrücken"},{"type":"M","value":"4x-2+3=4x+1"},{"type":"T","value":"Diese Geschichte enthält insgesamt nur 2 Euro Rabatt und führt zu einem anderen Term."},{"type":"H","value":"3. Den Unterschied prüfen"},{"type":"M","value":"x=5:\\quad4(5-2)+3=15;\\quad4\\cdot5-2+3=21"},{"type":"T","value":"Zwischen den Ergebnissen liegen 6 Euro, weil im ersten Fall drei weitere Rabatte abgezogen werden."}]},"source-0":{"title":"Ein Faktor wirkt auf die ganze Klammer","prompt":"","blocks":[{"type":"H","value":"Ein Faktor wirkt auf die ganze Klammer"},{"type":"T","value":"Wir vereinfachen 3(2x − 4) − (x − 5). Ein <b>Faktor</b> wird multipliziert; <b>Summanden</b> werden addiert. Der Faktor 3 steht vor der ganzen Klammer. Deshalb werden sowohl 2x als auch −4 verdreifacht. Das ist das <b>Distributivgesetz</b>."},{"type":"M","value":"3(2x-4)-(x-5)=6x-12-(x-5)"},{"type":"T","value":"Vor der zweiten Klammer steht ein Minus. Du kannst es als Faktor −1 lesen. Wir ziehen also die ganze Differenz x − 5 ab. Das Abziehen von −5 entspricht dem Addieren von +5."},{"type":"M","value":"=6x-12-x+5"},{"type":"M","value":"=(6-1)x+(-12+5)=5x-7"},{"type":"T","value":"Erst nach dem Auflösen fassen wir gleichartige Summanden zusammen. Der <b>Koeffizient</b> 5 zählt nun die x-Anteile. Zum Kontrollieren setzen wir x = 2 in den ursprünglichen und den vereinfachten Term ein."},{"type":"M","value":"3(4-4)-(2-5)=3\\qquad5\\cdot2-7=3"}],"prerequisites":["T01","R03"]},"source-1":{"title":"Warum jeder Summand mitgenommen werden muss","prompt":"","blocks":[{"type":"H","value":"Warum jeder Summand mitgenommen werden muss"},{"type":"V","value":"T03"},{"type":"T","value":"Das Rechteck zeigt 3(x + 2): Drei Zeilen enthalten jeweils einen x-Teil und einen 2-Teil. Insgesamt entstehen 3x + 6. Würde nur x verdreifacht, fehlten zwei der drei 2-Teile. Das erklärt denselben Verteilungsgedanken auch ohne Zahlenprobe."}],"prerequisites":["T01","R03"]}},"taskExamples":{"T03_MINI":"transfer","T03_L4_01":"transfer","T03_L4_02":"transfer","T03_L4_03":"transfer","T03_L4_04":"transfer","T03_L4_05":"transfer","T03_POOL_01":"transfer","T03_POOL_02":"transfer","T03_POOL_03":"transfer","T03_POOL_04":"transfer","T03_NEU_01":"transfer","T03_NEU_02":"transfer","T03_NEU_03":"transfer","T03_NEU_04":"transfer","T03_NEU_05":"transfer","T03_NEU_06":"transfer","T03_TEST_01":"transfer","T03_TEST_02":"transfer","T03_TEST_03":"transfer","T03_NEU_07":"transfer","T03_NEU_08":"transfer","T03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T04":{"default":"transfer","variants":{"transfer":{"title":"Einen Faktor für eine geschickte Rechnung freilegen","prompt":"Berechne 18·27 + 18·13, ohne beide großen Produkte einzeln auszurechnen. Übertrage denselben Gedanken auf einen Term mit Variable.","prerequisites":["N05","T03"],"blocks":[{"type":"H","value":"Einen Faktor für eine geschickte Rechnung freilegen"},{"type":"T","value":"Berechne 18·27 + 18·13, ohne beide großen Produkte einzeln auszurechnen. Übertrage denselben Gedanken auf einen Term mit Variable."},{"type":"H","value":"1. Die gemeinsame Gruppengröße sehen"},{"type":"M","value":"18\\cdot27+18\\cdot13=18(27+13)"},{"type":"T","value":"In beiden Summanden steht derselbe Faktor 18. Er zählt gemeinsame Gruppen."},{"type":"H","value":"2. Erst die Klammer auswerten"},{"type":"M","value":"18\\cdot40=720"},{"type":"T","value":"Die Summanden in der Klammer sind die jeweiligen anderen Faktoren."},{"type":"H","value":"3. Auf eine Variable übertragen und rückwärts prüfen"},{"type":"M","value":"18x+234=18(x+13);\\qquad18(x+13)=18x+234"},{"type":"T","value":"Jeder Summand wird durch den ausgeklammerten Faktor geteilt. Die Kontrolle erfolgt durch Ausmultiplizieren."}]},"source-0":{"title":"Aus einer Summe ein Produkt machen","prompt":"","blocks":[{"type":"H","value":"Aus einer Summe ein Produkt machen"},{"type":"T","value":"Im Term 12x² + 18x suchen wir einen <b>gemeinsamen Faktor</b>, also einen Baustein, der in jedem Summanden steckt. 12 und 18 haben den größten gemeinsamen Teiler 6. Beide Summanden enthalten außerdem mindestens ein x."},{"type":"M","value":"12x^2=6x\\cdot2x\\qquad18x=6x\\cdot3"},{"type":"T","value":"Beim <b>Ausklammern</b> schreiben wir den gemeinsamen Faktor einmal vor die Klammer. In der Klammer bleiben genau die restlichen Faktoren. So entsteht aus der Summe ein Produkt, ohne den Termwert zu ändern."},{"type":"M","value":"12x^2+18x=6x(2x+3)"},{"type":"T","value":"Das funktioniert auch bei x = 0: Beide Seiten sind dann 0. Wir haben hier Faktoren zerlegt, nicht eine Gleichung durch einen möglicherweise null werdenden Ausdruck geteilt. Die Probe ist das Ausmultiplizieren."},{"type":"M","value":"6x(2x+3)=12x^2+18x"}],"prerequisites":["T03","N03"]},"source-1":{"title":"Ein Flächenbild erklärt die Richtung rückwärts","prompt":"","blocks":[{"type":"H","value":"Ein Flächenbild erklärt die Richtung rückwärts"},{"type":"V","value":"T04"},{"type":"T","value":"Bei 6x + 12 haben zwei Rechteckteile die gemeinsame Höhe 6. Ihre Breiten sind x und 2. Die Gesamtfläche lässt sich daher auch als 6(x + 2) schreiben. Für das Flächenbild gilt x > 0; die algebraische Gleichheit gilt für jede reelle Zahl x."}],"prerequisites":["T03","N03"]}},"taskExamples":{"T04_MINI":"transfer","T04_L4_01":"transfer","T04_L4_02":"transfer","T04_L4_03":"transfer","T04_L4_04":"transfer","T04_L4_05":"transfer","T04_POOL_01":"transfer","T04_POOL_02":"transfer","T04_POOL_03":"transfer","T04_POOL_04":"transfer","T04_NEU_01":"transfer","T04_NEU_02":"transfer","T04_NEU_03":"transfer","T04_NEU_04":"transfer","T04_NEU_05":"transfer","T04_NEU_06":"transfer","T04_TEST_01":"transfer","T04_TEST_02":"transfer","T04_TEST_03":"transfer","T04_NEU_07":"transfer","T04_NEU_08":"transfer","T04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T05":{"default":"transfer","variants":{"transfer":{"title":"Ein Rechteck bekommt einen Randstreifen","prompt":"Ein Rechteck hat Seiten x+2 und x+5, dabei ist x > −2. Wird die kürzere Seite um 3 verlängert, entsteht ein Quadrat. Bestimme zunächst die alte Fläche und dann die hinzukommende Fläche.","prerequisites":["T02","T03","M03"],"blocks":[{"type":"H","value":"Ein Rechteck bekommt einen Randstreifen"},{"type":"T","value":"Ein Rechteck hat Seiten x+2 und x+5, dabei ist x > −2. Wird die kürzere Seite um 3 verlängert, entsteht ein Quadrat. Bestimme zunächst die alte Fläche und dann die hinzukommende Fläche."},{"type":"H","value":"1. Die alte Fläche aus vier Teilprodukten gewinnen"},{"type":"M","value":" (x+2)(x+5)=x^2+5x+2x+10=x^2+7x+10"},{"type":"H","value":"2. Die neue Fläche berechnen"},{"type":"M","value":" (x+5)(x+5)=x^2+10x+25"},{"type":"H","value":"3. Die Differenz geometrisch prüfen"},{"type":"M","value":" (x^2+10x+25)-(x^2+7x+10)=3x+15=3(x+5)"},{"type":"T","value":"Genau ein Streifen der Breite 3 und Länge x+5 kam hinzu. Die vier Teilprodukte erklären dieselbe Fläche wie das Bild."}]},"source-0":{"title":"Jeder Teil trifft jeden Teil","prompt":"","blocks":[{"type":"H","value":"Jeder Teil trifft jeden Teil"},{"type":"T","value":"Ein Rechteck hat für x > 0 die Seitenlängen x + 2 und x + 3. Sein Flächeninhalt ist das <b>Produkt</b> dieser beiden Summen. Wir zerlegen beide Seiten: So entstehen vier Teilrechtecke, nicht nur zwei."},{"type":"V","value":"T05"},{"type":"M","value":"(x+2)(x+3)=x\\cdot x+x\\cdot3+2\\cdot x+2\\cdot3"},{"type":"M","value":"=x^2+3x+2x+6=x^2+5x+6"},{"type":"T","value":"Die vier <b>Teilprodukte</b> entsprechen genau den vier Flächen. 3x und 2x sind gleichartig, weil sie denselben Variablenteil x besitzen; ihre Zahlenfaktoren, die Koeffizienten 3 und 2, addieren sich zu 5. x² und 6 bleiben eigene Summanden."}],"prerequisites":["T03"]},"source-1":{"title":"Dieselbe Regel mit einem Minus","prompt":"","blocks":[{"type":"H","value":"Dieselbe Regel mit einem Minus"},{"type":"M","value":"(x+2)(x-3)=x^2-3x+2x-6=x^2-x-6"},{"type":"T","value":"Auch hier wird jeder Summand mit jedem multipliziert. Die Vorzeichen gehören zu den Summanden: x mal −3 ergibt −3x, 2 mal −3 ergibt −6. Als Zahlenprobe liefert x = 4 links 6 · 1 = 6 und rechts 16 − 4 − 6 = 6."},{"type":"T","value":"Rückwärts erkennst du bei x² + 5x + 6 die Zahlen 2 und 3: Ihre Summe ist 5, ihr Produkt 6. Beide Bedingungen müssen passen, damit (x + 2)(x + 3) die richtige Produktform ist."}],"prerequisites":["T03"]}},"taskExamples":{"T05_MINI":"transfer","T05_L4_01":"transfer","T05_L4_02":"transfer","T05_L4_03":"transfer","T05_L4_04":"transfer","T05_L4_05":"transfer","T05_POOL_01":"transfer","T05_POOL_02":"transfer","T05_POOL_03":"transfer","T05_POOL_04":"transfer","T05_NEU_01":"transfer","T05_NEU_02":"transfer","T05_NEU_03":"transfer","T05_NEU_04":"transfer","T05_NEU_05":"transfer","T05_NEU_06":"transfer","T05_TEST_01":"transfer","T05_TEST_02":"transfer","T05_TEST_03":"transfer","T05_NEU_07":"transfer","T05_NEU_08":"transfer","T05_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T06":{"default":"transfer","variants":{"transfer":{"title":"Zwei Quadrate vergleichen, ohne große Zahlen zu quadrieren","prompt":"Wie viel größer ist 52² als 48²? Vergleiche einen Weg mit der dritten binomischen Formel und einen Weg über die Mitte 50.","prerequisites":["T05","R02"],"blocks":[{"type":"H","value":"Zwei Quadrate vergleichen, ohne große Zahlen zu quadrieren"},{"type":"T","value":"Wie viel größer ist 52² als 48²? Vergleiche einen Weg mit der dritten binomischen Formel und einen Weg über die Mitte 50."},{"type":"H","value":"1. Die Differenz von Quadraten faktorisieren"},{"type":"M","value":"52^2-48^2=(52-48)(52+48)=4\\cdot100=400"},{"type":"H","value":"2. Beide Quadrate um 50 entwickeln"},{"type":"M","value":" (50+2)^2=2500+200+4;\\qquad(50-2)^2=2500-200+4"},{"type":"H","value":"3. Die verbleibenden Teile erklären"},{"type":"T","value":"Beim Subtrahieren fallen 2500 und 4 jeweils weg. Übrig bleiben 200 − (−200) = 400. Die mittleren Produkte dürfen beim Quadrieren nicht fehlen."}]},"source-0":{"title":"Die erste Formel entsteht aus vier Teilflächen","prompt":"","blocks":[{"type":"H","value":"Die erste Formel entsteht aus vier Teilflächen"},{"type":"V","value":"T06"},{"type":"T","value":"Ein Quadrat mit Seite x + 3 besteht aus x², zweimal 3x und 9. Die beiden Rechtecke erklären das <b>doppelte Produkt</b> 2 · x · 3. Ein Quadrat einer Summe ist also mehr als die Summe der Quadrate."},{"type":"M","value":"(x+3)^2=x^2+6x+9"}],"prerequisites":["T05"]},"source-1":{"title":"Die zweite Formel: ein Minus bleibt im Mittelglied","prompt":"","blocks":[{"type":"H","value":"Die zweite Formel: ein Minus bleibt im Mittelglied"},{"type":"M","value":"(x-3)^2=(x-3)(x-3)=x^2-3x-3x+9"},{"type":"M","value":"=x^2-6x+9"},{"type":"T","value":"Beide gemischten Produkte sind negativ; das letzte Produkt (−3) · (−3) ist positiv. Deshalb endet auch die zweite <b>binomische Formel</b> mit +9. Allgemein steht hier a² − 2ab + b²."}],"prerequisites":["T05"]},"source-2":{"title":"Die dritte Formel: gemischte Produkte verschwinden","prompt":"","blocks":[{"type":"H","value":"Die dritte Formel: gemischte Produkte verschwinden"},{"type":"M","value":"(x-3)(x+3)=x^2+3x-3x-9=x^2-9"},{"type":"T","value":"Die +3x und −3x heben sich auf. Rückwärts wird aus der <b>Quadratdifferenz</b> x² − 9 ein Produkt: (x − 3)(x + 3). Das heißt <b>Faktorisieren</b>. Dagegen wird x² − 6x + 9 zu (x − 3)². Entscheidend ist, ob ein passendes Mittelglied vorhanden ist."}],"prerequisites":["T05"]}},"taskExamples":{"T06_MINI":"transfer","T06_L4_01":"transfer","T06_L4_02":"transfer","T06_L4_03":"transfer","T06_L4_04":"transfer","T06_L4_05":"transfer","T06_POOL_01":"transfer","T06_POOL_02":"transfer","T06_POOL_03":"transfer","T06_POOL_04":"transfer","T06_NEU_01":"transfer","T06_NEU_02":"transfer","T06_NEU_03":"transfer","T06_NEU_04":"transfer","T06_NEU_05":"transfer","T06_NEU_06":"transfer","T06_TEST_01":"transfer","T06_TEST_02":"transfer","T06_TEST_03":"transfer","T06_NEU_07":"transfer","T06_NEU_08":"transfer","T06_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"T07":{"default":"transfer","variants":{"transfer":{"title":"Von zwei Geschichten zu zwei Termen","prompt":"Vier Teams kaufen je ein Set. Jedes Set enthält zwei Hefte zu x Euro und einen Stift zu 1,50 Euro. Daneben gibt es ein anderes Angebot mit vier Heften und nur einem Stift. Stelle beide Gesamtpreise auf.","prerequisites":["T03","D02"],"blocks":[{"type":"H","value":"Von zwei Geschichten zu zwei Termen"},{"type":"T","value":"Vier Teams kaufen je ein Set. Jedes Set enthält zwei Hefte zu x Euro und einen Stift zu 1,50 Euro. Daneben gibt es ein anderes Angebot mit vier Heften und nur einem Stift. Stelle beide Gesamtpreise auf."},{"type":"H","value":"1. Zuerst ein Set beschreiben"},{"type":"M","value":"2x+1{,}5"},{"type":"T","value":"x ist ein Preis je Heft; 1,50 Euro fällt je Set einmal an."},{"type":"H","value":"2. Vier Sets berechnen"},{"type":"M","value":"4(2x+1{,}5)=8x+6"},{"type":"H","value":"3. Das zweite Angebot abgrenzen"},{"type":"M","value":"4x+1{,}5"},{"type":"T","value":"Die Klammer zeigt, welche Bestandteile gemeinsam vervielfacht werden. Zahlen und Variable erhalten ihre Bedeutung aus der Situation."}]},"source-0":{"title":"Ein Rechteck auf zwei Arten beschreiben","prompt":"","blocks":[{"type":"H","value":"Ein Rechteck auf zwei Arten beschreiben"},{"type":"T","value":"Ein Rechteck ist 2 cm länger als breit. Wir legen die <b>Variable</b> fest: x ist die Breite in Zentimetern; die Länge ist dann x + 2. Sinnvoll sind nur x > 0. Diese erlaubten Eingaben gehören zur Bedeutung des Terms."},{"type":"V","value":"T07"},{"type":"M","value":"U(x)=2x+2(x+2)=4x+4\\quad\\mathrm{(cm)}"},{"type":"T","value":"Der <b>Umfang</b> ist die gesamte Randlänge. Jede Seitenlänge kommt zweimal vor. Einmal zählen wir die vier Seiten einzeln; einmal sammeln wir alle x-Anteile. Die Terme heißen <b>gleichwertig</b>, weil die Umformung bei jedem erlaubten x denselben Wert erhält."},{"type":"M","value":"U(3)=2\\cdot3+2\\cdot5=16\\qquad4\\cdot3+4=16"},{"type":"T","value":"Die Zahlenprobe hilft beim Finden von Fehlern, beweist aber allein keine Gleichwertigkeit für alle x. Dafür nutzen wir Ausmultiplizieren und Zusammenfassen."}],"prerequisites":["T02","T03"]},"source-1":{"title":"Einen Term in eine Geschichte übersetzen","prompt":"","blocks":[{"type":"H","value":"Einen Term in eine Geschichte übersetzen"},{"type":"T","value":"3(x + 2) kann die Kosten von drei gleichen Paketen beschreiben. Jedes enthält einen Artikel für x Euro und einen für 2 Euro. Die Klammer steht für ein Paket; der Faktor 3 zählt die Pakete. 3x + 2 würde nur einmal 2 Euro berechnen und passt deshalb nicht zu dieser Geschichte."},{"type":"M","value":"3(x+2)=3x+6"}],"prerequisites":["T02","T03"]}},"taskExamples":{"T07_MINI":"transfer","T07_L4_01":"transfer","T07_L4_02":"transfer","T07_L4_03":"transfer","T07_L4_04":"transfer","T07_L4_05":"transfer","T07_POOL_01":"transfer","T07_POOL_02":"transfer","T07_POOL_03":"transfer","T07_POOL_04":"transfer","T07_NEU_01":"transfer","T07_NEU_02":"transfer","T07_NEU_03":"transfer","T07_NEU_04":"transfer","T07_NEU_05":"transfer","T07_NEU_06":"transfer","T07_TEST_01":"transfer","T07_TEST_02":"transfer","T07_TEST_03":"transfer","T07_NEU_07":"transfer","T07_NEU_08":"transfer","T07_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E01":{"default":"transfer","variants":{"transfer":{"title":"Eine Gleichung bauen und eine falsche Probe erkennen","prompt":"Gesucht ist eine Gleichung mit Lösung x=−2. Beginne mit einem Rechenausdruck und baue daraus zwei verschiedene passende Gleichungen.","prerequisites":["T01","R02"],"blocks":[{"type":"H","value":"Eine Gleichung bauen und eine falsche Probe erkennen"},{"type":"T","value":"Gesucht ist eine Gleichung mit Lösung x=−2. Beginne mit einem Rechenausdruck und baue daraus zwei verschiedene passende Gleichungen."},{"type":"H","value":"1. Einen Term bei der gewünschten Zahl auswerten"},{"type":"M","value":"3\\cdot(-2)+4=-2"},{"type":"T","value":"Daraus wird die Gleichung 3x+4=−2."},{"type":"H","value":"2. Eine zweite Gleichung bilden"},{"type":"M","value":"2((-2)+5)=6"},{"type":"T","value":"Also passt auch 2(x+5)=6. Eine Lösung kann zu vielen verschiedenen Gleichungen gehören."},{"type":"H","value":"3. Eine Probe richtig lesen"},{"type":"T","value":"Bei einer Probe werden linke und rechte Seite der ursprünglichen Gleichung berechnet. „x=−2 eingesetzt“ ist noch keine Begründung; beide Seiten müssen denselben Wert haben."}]},"source-0":{"title":"Ein Ausdruck ist noch keine Gleichung","prompt":"","blocks":[{"type":"H","value":"Ein Ausdruck ist noch keine Gleichung"},{"type":"T","value":"3x − 2 ist ein <b>Term</b>. Erst 3x − 2 = 10 ist eine <b>Gleichung</b>: Sie behauptet, dass der Term links und der Term rechts denselben Wert haben. Eine <b>Lösung</b> ist eine Zahl für x, die diese Behauptung wahr macht."},{"type":"M","value":"3x-2=10"},{"type":"T","value":"Wir prüfen den Vorschlag x = 4. Bei der <b>Probe</b> setzen wir in die ursprüngliche Gleichung ein. Wir berechnen zunächst die linke Seite und vergleichen sie mit der rechten Seite; wir nehmen die Gleichheit nicht einfach als gegeben an."},{"type":"M","value":"\\mathrm{links}:\\ 3\\cdot4-2=12-2=10\\qquad\\mathrm{rechts}:\\ 10"},{"type":"T","value":"Beide Seiten ergeben 10; also ist 4 eine Lösung. Für x = 3 entsteht links dagegen 7. Weil 7 und 10 verschieden sind, ist 3 keine Lösung."},{"type":"M","value":"3\\cdot3-2=7\\ne10"}],"prerequisites":["T01"]},"source-1":{"title":"Eine Lösung finden und dann prüfen","prompt":"","blocks":[{"type":"H","value":"Eine Lösung finden und dann prüfen"},{"type":"T","value":"Denk rückwärts: Vor dem Abziehen von 2 muss links 12 gestanden haben. Drei gleiche x-Anteile ergeben also 12; ein Anteil ist 4. Diese Überlegung führt zur Lösung, die Probe sichert sie am Original ab."},{"type":"M","value":"3x=12\\quad\\Longrightarrow\\quad x=4\\qquad L=\\{4\\}"},{"type":"T","value":"L bezeichnet hier die <b>Lösungsmenge</b>. Sie enthält die Zahlen, die die Gleichung erfüllen. Ein Termwert und eine Lösung sind verschiedene Dinge: Bei x = 4 hat der Term 3x − 2 den Wert 10."}],"prerequisites":["T01"]}},"taskExamples":{"E01_MINI":"transfer","E01_L4_01":"transfer","E01_L4_02":"transfer","E01_L4_03":"transfer","E01_L4_04":"transfer","E01_L4_05":"transfer","E01_POOL_01":"transfer","E01_POOL_02":"transfer","E01_POOL_03":"transfer","E01_POOL_04":"transfer","E01_NEU_01":"transfer","E01_NEU_02":"transfer","E01_NEU_03":"transfer","E01_NEU_04":"transfer","E01_NEU_05":"transfer","E01_NEU_06":"transfer","E01_TEST_01":"transfer","E01_TEST_02":"transfer","E01_TEST_03":"transfer","E01_NEU_07":"transfer","E01_NEU_08":"transfer","E01_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E02":{"default":"transfer","variants":{"transfer":{"title":"Eine Gleichung lösen und den Weg umkehren","prompt":"Eine unbekannte Zahl wird um 3 vergrößert, anschließend mit 4 multipliziert. Das Ergebnis ist genauso groß wie das Zweifache der Zahl plus 18. Löse die Gleichung und prüfe im ursprünglichen Rechenplan.","prerequisites":["T03","T01"],"blocks":[{"type":"H","value":"Eine Gleichung lösen und den Weg umkehren"},{"type":"T","value":"Eine unbekannte Zahl wird um 3 vergrößert, anschließend mit 4 multipliziert. Das Ergebnis ist genauso groß wie das Zweifache der Zahl plus 18. Löse die Gleichung und prüfe im ursprünglichen Rechenplan."},{"type":"H","value":"1. Die beiden Pläne gleichsetzen"},{"type":"M","value":"4(x+3)=2x+18"},{"type":"H","value":"2. Auf beiden Seiten gleich umformen"},{"type":"M","value":"4x+12=2x+18;\\qquad2x+12=18;\\qquad2x=6;\\qquad x=3"},{"type":"T","value":"Zuerst verteilen, dann auf beiden Seiten 2x und 12 abziehen, zuletzt durch 2 teilen."},{"type":"H","value":"3. Beide ursprünglichen Pläne prüfen"},{"type":"M","value":"4(3+3)=24;\\qquad2\\cdot3+18=24"},{"type":"T","value":"Die Probe prüft auch die zuvor aufgelöste Klammer."}]},"source-0":{"title":"Die unbekannte Zahl schrittweise freistellen","prompt":"","blocks":[{"type":"H","value":"Die unbekannte Zahl schrittweise freistellen"},{"type":"T","value":"Wir lösen 3x + 5 = x + 13. Die Gleichung ist <b>linear</b>: x kommt nur in der ersten Potenz vor. Die 3 vor x ist ein <b>Koeffizient</b>, also die Anzahl der x-Anteile. Wir wollen alle x-Anteile auf einer und die bekannten Zahlen auf der anderen Seite sammeln."},{"type":"M","value":"3x+5=x+13\\quad|\\;-x"},{"type":"M","value":"2x+5=13\\quad|\\;-5"},{"type":"M","value":"2x=8\\quad|\\;:2"},{"type":"M","value":"x=4"},{"type":"T","value":"Wir ziehen auf <b>beiden</b> Seiten erst x, dann 5 ab. Damit entfernen wir gleiche Mengen von gleichen Werten. Danach teilen wir beide Seiten durch 2, damit aus zwei x-Anteilen einer wird. Der Strich rechts notiert die Operation für beide Seiten."},{"type":"V","value":"E02"},{"type":"T","value":"Solche umkehrbaren Schritte heißen <b>Äquivalenzumformungen</b>: Die Lösungsmenge bleibt gleich. Addieren und Subtrahieren sind rückgängig zu machen; beim Multiplizieren oder Dividieren darf der verwendete Faktor nicht 0 sein."},{"type":"M","value":"3\\cdot4+5=17\\qquad4+13=17\\qquad L=\\{4\\}"},{"type":"T","value":"Die Probe gehört zur ursprünglichen Gleichung. Sie überprüft auch, ob wir beim Abschreiben oder Auflösen ein Vorzeichen verloren haben."}],"prerequisites":["E01","R02","R03","T03"]}},"taskExamples":{"E02_MINI":"transfer","E02_L4_01":"transfer","E02_L4_02":"transfer","E02_L4_03":"transfer","E02_L4_04":"transfer","E02_L4_05":"transfer","E02_POOL_01":"transfer","E02_POOL_02":"transfer","E02_POOL_03":"transfer","E02_POOL_04":"transfer","E02_NEU_01":"transfer","E02_NEU_02":"transfer","E02_NEU_03":"transfer","E02_NEU_04":"transfer","E02_NEU_05":"transfer","E02_NEU_06":"transfer","E02_TEST_01":"transfer","E02_TEST_02":"transfer","E02_TEST_03":"transfer","E02_NEU_07":"transfer","E02_NEU_08":"transfer","E02_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E03":{"default":"transfer","variants":{"transfer":{"title":"Alle Summanden mit demselben Faktor behandeln","prompt":"Ein Band besteht aus drei Teilen. Der erste ist x/3 Meter lang, der zweite x/2 Meter und der dritte genau 2 Meter. Zusammen sind es 7 Meter. Löse die Gleichung und prüfe zusätzlich die Teilstücke.","prerequisites":["B02","E02"],"blocks":[{"type":"H","value":"Alle Summanden mit demselben Faktor behandeln"},{"type":"T","value":"Ein Band besteht aus drei Teilen. Der erste ist x/3 Meter lang, der zweite x/2 Meter und der dritte genau 2 Meter. Zusammen sind es 7 Meter. Löse die Gleichung und prüfe zusätzlich die Teilstücke."},{"type":"H","value":"1. Die Summe als Gleichung schreiben"},{"type":"M","value":"\\frac{x}{3}+\\frac{x}{2}+2=7"},{"type":"H","value":"2. Mit dem gemeinsamen Nenner multiplizieren"},{"type":"M","value":"6\\cdot\\frac{x}{3}+6\\cdot\\frac{x}{2}+6\\cdot2=6\\cdot7;\\qquad2x+3x+12=42;\\qquad5x=30;\\qquad x=6"},{"type":"T","value":"Auch die ganze Zahl 2 und die rechte Seite werden mit 6 multipliziert. Kein Summand darf ausgelassen werden."},{"type":"H","value":"3. Die Größen im Text prüfen"},{"type":"M","value":"6:3=2;\\qquad6:2=3;\\qquad2+3+2=7"},{"type":"T","value":"Die gesuchte Zahl x ist 6, obwohl die Gesamtlänge des Bandes 7 Meter beträgt. x ist hier ein Parameter der Teilstücke."}]},"source-0":{"title":"Brüche entfernen, ohne einen Summanden zu verlieren","prompt":"","blocks":[{"type":"H","value":"Brüche entfernen, ohne einen Summanden zu verlieren"},{"type":"T","value":"Wir lösen x/3 + 1/2 = 5/6. Die Nenner 3, 2 und 6 sind bekannte Zahlen. Ihr kleinster gemeinsamer positiver Vielfacher ist 6, der <b>Hauptnenner</b>. Multiplizieren wir die ganze Gleichung mit 6, werden alle Nenner zu Teilern des Faktors."},{"type":"M","value":"\\frac x3+\\frac12=\\frac56\\quad|\\;\\cdot6"},{"type":"M","value":"6\\cdot\\frac x3+6\\cdot\\frac12=6\\cdot\\frac56"},{"type":"M","value":"2x+3=5\\quad\\Longrightarrow\\quad2x=2\\quad\\Longrightarrow\\quad x=1"},{"type":"T","value":"Jeder Summand wird mit 6 multipliziert, weil die gesamte linke Seite sechsmal genommen wird. Nur den ersten Bruch zu verändern würde eine andere Gleichung erzeugen. Die Probe zeigt, ob die gefundene Zahl die ursprünglichen Brüche richtig ergänzt."},{"type":"M","value":"\\frac13+\\frac12=\\frac26+\\frac36=\\frac56"}],"prerequisites":["E02","B07"]},"source-1":{"title":"Ein Verhältnis als Gleichung lesen","prompt":"","blocks":[{"type":"H","value":"Ein Verhältnis als Gleichung lesen"},{"type":"T","value":"x : 4 = 3 : 2 bedeutet, dass zwei Quotienten gleich sind. Wir schreiben sie als Brüche. Weil x durch 4 geteilt wird, machen wir die Division durch Multiplikation mit 4 rückgängig."},{"type":"M","value":"\\frac x4=\\frac32\\quad\\Longrightarrow\\quad x=4\\cdot\\frac32=6"},{"type":"T","value":"Zur Probe gilt 6 : 4 = 1,5 und 3 : 2 = 1,5. Dieses Blatt verwendet Zahlennenner. Wenn eine Variable im Nenner steht, muss zusätzlich ausgeschlossen werden, dass der Nenner 0 wird."}],"prerequisites":["E02","B07"]}},"taskExamples":{"E03_MINI":"transfer","E03_L4_01":"transfer","E03_L4_02":"transfer","E03_L4_03":"transfer","E03_L4_04":"transfer","E03_L4_05":"transfer","E03_POOL_01":"transfer","E03_POOL_02":"transfer","E03_POOL_03":"transfer","E03_POOL_04":"transfer","E03_NEU_01":"transfer","E03_NEU_02":"transfer","E03_NEU_03":"transfer","E03_NEU_04":"transfer","E03_NEU_05":"transfer","E03_NEU_06":"transfer","E03_TEST_01":"transfer","E03_TEST_02":"transfer","E03_TEST_03":"transfer","E03_NEU_07":"transfer","E03_NEU_08":"transfer","E03_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E04":{"default":"transfer","variants":{"transfer":{"title":"Eine Formel für eine andere Frage öffnen","prompt":"Für einen rechteckigen Rahmen gilt U=2a+2b. Es soll eine Regel entstehen, die zu Umfang U und Seitenunterschied d die kürzere Seite b liefert; dabei ist a=b+d.","prerequisites":["T03","E02","M03"],"blocks":[{"type":"H","value":"Eine Formel für eine andere Frage öffnen"},{"type":"T","value":"Für einen rechteckigen Rahmen gilt U=2a+2b. Es soll eine Regel entstehen, die zu Umfang U und Seitenunterschied d die kürzere Seite b liefert; dabei ist a=b+d."},{"type":"H","value":"1. Die Seitenbeziehung einsetzen"},{"type":"M","value":"U=2(b+d)+2b=4b+2d"},{"type":"H","value":"2. Nach der kürzeren Seite umstellen"},{"type":"M","value":"U-2d=4b;\\qquad b=\\frac{U-2d}{4}"},{"type":"T","value":"U und d bleiben Größen. Umstellen erzeugt eine Formel für viele mögliche Werte."},{"type":"H","value":"3. Eine konkrete Rahmenform prüfen"},{"type":"M","value":"U=28,\\ d=2:\\quad b=6,\\ a=8;\\quad2\\cdot8+2\\cdot6=28"},{"type":"T","value":"Für einen echten Rahmen müssen beide Seiten positiv sein; hier muss insbesondere U größer als 2d sein."}]},"source-0":{"title":"Aus der Umfangsformel eine Seitenlänge gewinnen","prompt":"","blocks":[{"type":"H","value":"Aus der Umfangsformel eine Seitenlänge gewinnen"},{"type":"T","value":"Die <b>Formel</b> U = 2a + 2b verknüpft Umfang und Seitenlängen eines Rechtecks. Gesucht ist b. Wir behandeln U und a wie bekannte Zahlen und machen zuerst die Addition von 2a rückgängig. Erst danach teilen wir durch 2."},{"type":"M","value":"U=2a+2b\\quad|\\;-2a"},{"type":"M","value":"U-2a=2b\\quad|\\;:2"},{"type":"M","value":"b=\\frac{U-2a}{2}=\\frac U2-a"},{"type":"T","value":"Der Bruchstrich fasst den gesamten Zähler zusammen: Auch −2a wird durch 2 geteilt. Für U = 18 cm und a = 5 cm ergibt sich b = 9 − 5 = 4 cm. Die Probe 2 · 5 + 2 · 4 = 18 bestätigt die Länge."}],"prerequisites":["E02","T07"]},"source-1":{"title":"Wenn der Divisor selbst eine Variable ist","prompt":"","blocks":[{"type":"H","value":"Wenn der Divisor selbst eine Variable ist"},{"type":"M","value":"A=gh\\quad\\Longrightarrow\\quad h=\\frac Ag\\quad(g\\ne0)"},{"type":"T","value":"Hier steht g als Faktor vor h. Die Division durch g stellt h frei, ist aber nur erlaubt, wenn g nicht 0 ist. Für eine positive Grundseite ist das erfüllt. Aus 0 = 0 · h könnte man dagegen keinen bestimmten Wert für h gewinnen."},{"type":"T","value":"Warum die Umformung allgemein nützlich ist: Du brauchst sie nur einmal herzuleiten und kannst danach viele passende Zahlen einsetzen. Einheiten und erlaubte Werte prüfst du trotzdem bei jeder konkreten Situation."}],"prerequisites":["E02","T07"]}},"taskExamples":{"E04_MINI":"transfer","E04_L4_01":"transfer","E04_L4_02":"transfer","E04_L4_03":"transfer","E04_L4_04":"transfer","E04_L4_05":"transfer","E04_POOL_01":"transfer","E04_POOL_02":"transfer","E04_POOL_03":"transfer","E04_POOL_04":"transfer","E04_NEU_01":"transfer","E04_NEU_02":"transfer","E04_NEU_03":"transfer","E04_NEU_04":"transfer","E04_NEU_05":"transfer","E04_NEU_06":"transfer","E04_TEST_01":"transfer","E04_TEST_02":"transfer","E04_TEST_03":"transfer","E04_NEU_07":"transfer","E04_NEU_08":"transfer","E04_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E05":{"default":"transfer","variants":{"transfer":{"title":"Ein Text enthält zwei verschiedene Unbekannte","prompt":"Ein Vater ist heute dreimal so alt wie sein Kind. In 12 Jahren ist er doppelt so alt wie das Kind dann. Bestimme die heutigen Alter.","prerequisites":["T07","E02"],"blocks":[{"type":"H","value":"Ein Text enthält zwei verschiedene Unbekannte"},{"type":"T","value":"Ein Vater ist heute dreimal so alt wie sein Kind. In 12 Jahren ist er doppelt so alt wie das Kind dann. Bestimme die heutigen Alter."},{"type":"H","value":"1. Eine Variable festlegen"},{"type":"T","value":"x ist das heutige Alter des Kindes. Der Vater ist heute 3x Jahre alt. In 12 Jahren sind die Alter x+12 und 3x+12."},{"type":"H","value":"2. Den späteren Vergleich übersetzen"},{"type":"M","value":"3x+12=2(x+12);\\qquad3x+12=2x+24;\\qquad x=12"},{"type":"H","value":"3. Zur Situation zurückkehren"},{"type":"T","value":"Heute sind das Kind 12 und der Vater 36 Jahre alt. In 12 Jahren sind sie 24 und 48. Die zweite Bedingung passt, weil 48 doppelt so viel wie 24 ist."}]},"source-0":{"title":"Vom Text zur Gleichung – und wieder zurück","prompt":"","blocks":[{"type":"H","value":"Vom Text zur Gleichung – und wieder zurück"},{"type":"T","value":"Drei gleiche Hefte und ein Stift für 2 Euro kosten zusammen 11 Euro. Gesucht ist der Heftpreis. Wir legen fest: <b>x ist der Preis eines Heftes in Euro</b>. Die drei Hefte kosten 3x; der Stift wird einmal addiert."},{"type":"M","value":"3x+2=11"},{"type":"T","value":"Diese Gleichung ist unser <b>Modell</b> der Einkaufssituation. Wir ziehen zuerst 2 Euro für den bekannten Stift ab. So bleiben die Kosten der drei Hefte. Durch Division durch 3 erhalten wir den Preis eines Heftes."},{"type":"M","value":"3x=9\\quad\\Longrightarrow\\quad x=3"},{"type":"T","value":"Die Antwort lautet: Ein Heft kostet 3 Euro. Die <b>Sachprobe</b> rechnet den Einkauf nach: 3 · 3 Euro + 2 Euro = 11 Euro. Ein negativer Preis wäre zwar eventuell ein Rechenergebnis, würde hier aber nicht zur Situation passen."}],"prerequisites":["E02","T07"]},"source-1":{"title":"Eine andere Beziehung: Zahlen statt Preise","prompt":"","blocks":[{"type":"H","value":"Eine andere Beziehung: Zahlen statt Preise"},{"type":"T","value":"„Verdoppelt man eine Zahl und zieht 5 ab, erhält man dieselbe Zahl plus 4.“ x steht nun für die gesuchte Zahl. Links übersetzen wir die erste Rechenkette, rechts den Vergleichsausdruck."},{"type":"M","value":"2x-5=x+4\\quad\\Longrightarrow\\quad x-5=4\\quad\\Longrightarrow\\quad x=9"},{"type":"T","value":"Zur Probe: 2 · 9 − 5 = 13 und 9 + 4 = 13. Die gleiche Variable muss in beiden Teilen dieselbe Zahl bedeuten. Schreibe diese Bedeutung auf, bevor du anfängst umzuformen."}],"prerequisites":["E02","T07"]}},"taskExamples":{"E05_MINI":"transfer","E05_L4_01":"transfer","E05_L4_02":"transfer","E05_L4_03":"transfer","E05_L4_04":"transfer","E05_L4_05":"transfer","E05_POOL_01":"transfer","E05_POOL_02":"transfer","E05_POOL_03":"transfer","E05_POOL_04":"transfer","E05_NEU_01":"transfer","E05_NEU_02":"transfer","E05_NEU_03":"transfer","E05_NEU_04":"transfer","E05_NEU_05":"transfer","E05_NEU_06":"transfer","E05_TEST_01":"transfer","E05_TEST_02":"transfer","E05_TEST_03":"transfer","E05_NEU_07":"transfer","E05_NEU_08":"transfer","E05_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E06":{"default":"transfer","variants":{"transfer":{"title":"Ein Schnittpunkt genügt für beide Tarifbedingungen","prompt":"Ein Verleih verlangt A(t)=2t+6 Euro, ein anderer B(t)=5t Euro. Zeige zuerst einen Punkt, der nur auf einer Geraden liegt, und dann den gemeinsamen Punkt.","prerequisites":["F02","E02","G03"],"blocks":[{"type":"H","value":"Ein Schnittpunkt genügt für beide Tarifbedingungen"},{"type":"T","value":"Ein Verleih verlangt A(t)=2t+6 Euro, ein anderer B(t)=5t Euro. Zeige zuerst einen Punkt, der nur auf einer Geraden liegt, und dann den gemeinsamen Punkt."},{"type":"H","value":"1. Einen einzelnen Tarifpunkt prüfen"},{"type":"M","value":"A(1)=8;\\qquad B(1)=5"},{"type":"T","value":"(1|8) liegt auf A, aber nicht auf B. Ein gemeinsamer Punkt muss bei derselben Eingabe beide Ausgaben erfüllen."},{"type":"H","value":"2. Die gleiche Ausgabe suchen"},{"type":"M","value":"2t+6=5t;\\qquad t=2;\\qquad A(2)=B(2)=10"},{"type":"H","value":"3. Den Schnittpunkt deuten"},{"type":"T","value":"S(2|10) bedeutet: Bei zwei Stunden kosten beide Tarife zehn Euro. Die Koordinaten sind Stunden und Euro; sie dürfen nicht vertauscht werden."}]},"source-0":{"title":"Ein Punkt soll zwei Bedingungen zugleich erfüllen","prompt":"","blocks":[{"type":"H","value":"Ein Punkt soll zwei Bedingungen zugleich erfüllen"},{"type":"T","value":"Das <b>Gleichungssystem</b> besteht aus y = x + 1 und y = −x + 5. Jede Gleichung beschreibt eine Gerade. Wir berechnen Punkte und zeichnen beide Geraden in dasselbe Koordinatensystem, weil dieselben x- und y-Werte verglichen werden sollen."},{"type":"V","value":"E06"},{"type":"T","value":"Der <b>Schnittpunkt</b> ist S(2| 3). Sein <b>Koordinatenpaar</b> sagt x = 2 und y = 3. Nur an dieser Stelle geben beide Regeln denselben y-Wert. Wir lesen daher nicht nur x oder nur y als Lösung ab."},{"type":"M","value":"3=2+1\\qquad3=-2+5"},{"type":"T","value":"Beide Proben stimmen. Die gemeinsame Lösung ist also das Paar (2| 3). Beim Zeichnen reichen für jede Gerade zwei verschiedene Punkte; ein dritter Punkt hilft als Kontrolle."},{"type":"M","value":"y=x+1:\\ (0|1),(2|3)\\qquad y=-x+5:\\ (0|5),(2|3)"},{"type":"T","value":"Warum die Probe nötig ist: Aus einer Zeichnung liest man oft nur ungefähr ab. Die Rechnung mit beiden ursprünglichen Gleichungen zeigt, ob der abgelesene Schnittpunkt exakt stimmt. Ein Punkt auf nur einer der Geraden löst das System noch nicht."}],"prerequisites":["F02","F03"]}},"taskExamples":{"E06_MINI":"transfer","E06_L4_01":"transfer","E06_L4_02":"transfer","E06_L4_03":"transfer","E06_L4_04":"transfer","E06_L4_05":"transfer","E06_POOL_01":"transfer","E06_POOL_02":"transfer","E06_POOL_03":"transfer","E06_POOL_04":"transfer","E06_NEU_01":"transfer","E06_NEU_02":"transfer","E06_NEU_03":"transfer","E06_NEU_04":"transfer","E06_NEU_05":"transfer","E06_NEU_06":"transfer","E06_TEST_01":"transfer","E06_TEST_02":"transfer","E06_TEST_03":"transfer","E06_NEU_07":"transfer","E06_NEU_08":"transfer","E06_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E07":{"default":"transfer","variants":{"transfer":{"title":"Eine Summe und ein Unterschied liefern zwei Preise","prompt":"Zwei Eintrittskarten zusammen kosten 23 Euro. Die Erwachsenenkarte kostet 5 Euro mehr als die Kinderkarte. Löse auf zwei Wegen und vergleiche die Rollen der Variablen.","prerequisites":["E02","E05"],"blocks":[{"type":"H","value":"Eine Summe und ein Unterschied liefern zwei Preise"},{"type":"T","value":"Zwei Eintrittskarten zusammen kosten 23 Euro. Die Erwachsenenkarte kostet 5 Euro mehr als die Kinderkarte. Löse auf zwei Wegen und vergleiche die Rollen der Variablen."},{"type":"H","value":"1. Zwei Bedingungen notieren"},{"type":"M","value":"e+k=23;\\qquad e=k+5"},{"type":"T","value":"e ist der Erwachsenenpreis, k der Kinderpreis."},{"type":"H","value":"2. Einen Ausdruck einsetzen"},{"type":"M","value":"k+5+k=23;\\qquad2k=18;\\qquad k=9;\\quad e=14"},{"type":"H","value":"3. Mit der Differenz kontrollieren"},{"type":"M","value":"14+9=23;\\qquad14-9=5"},{"type":"T","value":"Man kann auch e−k=5 von e+k=23 abziehen. Dann bleibt 2k=18. Beide Wege bewahren beide Bedingungen."}]},"source-0":{"title":"Einsetzen: einen Ausdruck durch einen gleichen ersetzen","prompt":"","blocks":[{"type":"H","value":"Einsetzen: einen Ausdruck durch einen gleichen ersetzen"},{"type":"T","value":"Im System y = 2x und x + y = 9 ist y bereits allein. Mit dem <b>Einsetzungsverfahren</b> ersetzen wir y in der zweiten Gleichung durch 2x, denn die erste Gleichung fordert genau diese Gleichheit. So bleibt nur eine Variable übrig."},{"type":"M","value":"x+2x=9\\quad\\Longrightarrow\\quad3x=9\\quad\\Longrightarrow\\quad x=3"},{"type":"M","value":"y=2\\cdot3=6"},{"type":"T","value":"Die Lösung ist das Paar (3| 6). Wir prüfen beide Bedingungen: 6 = 2 · 3 und 3 + 6 = 9. Nur x = 3 anzugeben wäre unvollständig, weil zwei Größen gesucht sind."}],"prerequisites":["E02","E06"]},"source-1":{"title":"Gleichsetzen: zwei Ausdrücke für denselben Wert","prompt":"","blocks":[{"type":"H","value":"Gleichsetzen: zwei Ausdrücke für denselben Wert"},{"type":"T","value":"Im System y = 2x und y = −x + 9 sind beide Gleichungen nach y aufgelöst. Mit dem <b>Gleichsetzungsverfahren</b> setzen wir deshalb die rechten Seiten gleich: Am gemeinsamen Punkt müssen beide denselben y-Wert liefern."},{"type":"M","value":"2x=-x+9\\quad\\Longrightarrow\\quad3x=9\\quad\\Longrightarrow\\quad x=3"},{"type":"M","value":"y=6\\qquad6=2\\cdot3\\qquad6=-3+9"},{"type":"T","value":"Beide Verfahren nutzen dieselbe Idee: Gleiche Werte dürfen durch gleiche Ausdrücke ersetzt werden. Wähle das Verfahren, das die vorhandene Schreibweise am einfachsten nutzt. Die Probe erfolgt immer im ursprünglichen System."}],"prerequisites":["E02","E06"]}},"taskExamples":{"E07_MINI":"transfer","E07_L4_01":"transfer","E07_L4_02":"transfer","E07_L4_03":"transfer","E07_L4_04":"transfer","E07_L4_05":"transfer","E07_POOL_01":"transfer","E07_POOL_02":"transfer","E07_POOL_03":"transfer","E07_POOL_04":"transfer","E07_NEU_01":"transfer","E07_NEU_02":"transfer","E07_NEU_03":"transfer","E07_NEU_04":"transfer","E07_NEU_05":"transfer","E07_NEU_06":"transfer","E07_TEST_01":"transfer","E07_TEST_02":"transfer","E07_TEST_03":"transfer","E07_NEU_07":"transfer","E07_NEU_08":"transfer","E07_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"E08":{"default":"transfer","variants":{"transfer":{"title":"Steigung und Achsenabschnitt entscheiden über den Lösungsfall","prompt":"Vergleiche y=2x+1 mit y=mx+b. Wähle m und b so, dass die beiden Geraden genau eine, keine oder unendlich viele gemeinsame Lösungen haben.","prerequisites":["E06","E07","F02"],"blocks":[{"type":"H","value":"Steigung und Achsenabschnitt entscheiden über den Lösungsfall"},{"type":"T","value":"Vergleiche y=2x+1 mit y=mx+b. Wähle m und b so, dass die beiden Geraden genau eine, keine oder unendlich viele gemeinsame Lösungen haben."},{"type":"H","value":"1. Gleiche Steigung, anderer Start"},{"type":"M","value":"m=2,\\ b=4:\\quad2x+1=2x+4\\Rightarrow1=4"},{"type":"T","value":"Ein Widerspruch bedeutet: keine gemeinsame Lösung. Die Geraden sind parallel und verschieden."},{"type":"H","value":"2. Gleiche Steigung, gleicher Start"},{"type":"M","value":"m=2,\\ b=1:\\quad2x+1=2x+1"},{"type":"T","value":"Jedes x erfüllt die Gleichheit. Die beiden Beschreibungen gehören zur selben Geraden."},{"type":"H","value":"3. Verschiedene Steigungen"},{"type":"M","value":"m=-1,\\ b=4:\\quad2x+1=-x+4\\Rightarrow x=1,\\ y=3"},{"type":"T","value":"Die Geraden schneiden sich genau einmal. Eine Null beim Umformen muss deshalb immer zusammen mit der restlichen Gleichung gelesen werden."}]},"source-0":{"title":"Drei Fälle – rechnerisch und im Bild","prompt":"","blocks":[{"type":"H","value":"Drei Fälle – rechnerisch und im Bild"},{"type":"T","value":"Ein lineares Gleichungssystem fragt nach Punkten, die auf beiden Geraden liegen. Ihre <b>Steigung</b> beschreibt den Anstieg pro Schritt nach rechts; der y-Achsenabschnitt ist der Wert bei x = 0. Mit diesen beiden Angaben unterscheiden wir die Fälle."},{"type":"V","value":"E08"},{"type":"T","value":"<b>Genau eine Lösung:</b> y = x + 1 und y = −x + 5 haben verschiedene Steigungen. Gleichsetzen liefert x + 1 = −x + 5, also x = 2 und y = 3. Die Geraden schneiden sich einmal."},{"type":"M","value":"L=\\{(2|3)\\}"},{"type":"T","value":"<b>Keine Lösung:</b> y = x + 1 und y = x + 3 haben gleiche Steigung, aber verschiedene Abschnitte. Aus x + 1 = x + 3 wird 1 = 3, ein <b>Widerspruch</b>. Die Geraden sind echt parallel."},{"type":"M","value":"L=\\varnothing"},{"type":"T","value":"<b>Unendlich viele Lösungen:</b> y = x + 1 und 2y = 2x + 2 beschreiben dieselbe Gerade. Die zweite Gleichung ist das Doppelte der ersten. Nach Einsetzen entsteht 2x + 2 = 2x + 2, also eine immer wahre Aussage."},{"type":"M","value":"L=\\{(x|x+1)\\mid x\\in\\mathbb{R}\\}"},{"type":"T","value":"„Unendlich viele“ bedeutet hier alle Punkte dieser Geraden, nicht alle Punkte der Ebene. „Keine Lösung“ bedeutet, dass überhaupt kein gemeinsames Koordinatenpaar existiert."}],"prerequisites":["E02","E06"]}},"taskExamples":{"E08_MINI":"transfer","E08_L4_01":"transfer","E08_L4_02":"transfer","E08_L4_03":"transfer","E08_L4_04":"transfer","E08_L4_05":"transfer","E08_POOL_01":"transfer","E08_POOL_02":"transfer","E08_POOL_03":"transfer","E08_POOL_04":"transfer","E08_NEU_01":"transfer","E08_NEU_02":"transfer","E08_NEU_03":"transfer","E08_NEU_04":"transfer","E08_NEU_05":"transfer","E08_NEU_06":"transfer","E08_TEST_01":"transfer","E08_TEST_02":"transfer","E08_TEST_03":"transfer","E08_NEU_07":"transfer","E08_NEU_08":"transfer","E08_H":"transfer"},"selectionReason":"Das ergänzende Beispiel verändert die Fragestellung: kontrastierende Fälle, Rückwärtsfrage, mehrere Bezugsmengen oder Kontrolle in einer zweiten Darstellung. Es ist aus keiner Aufgaben-Zahlenvorlage erzeugt."},"F00":{"default":"transfer","variants":{"transfer":{"title":"Verschiedene Eingaben dürfen dieselbe Ausgabe haben","prerequisites":["T01","R02"],"rationale":"Kontrastiert Eindeutigkeit der Ausgabe mit Eindeutigkeit der Umkehrung anhand einer konstanten Regel; kein neuer Zahlenwert in einer linearen Vorwärtsaufgabe.","blocks":[{"type":"H","value":"1. Die Regel lesen"},{"type":"T","value":"Ein Eintritt kostet für Kinder jeden Alters 4 Euro. Innerhalb der erlaubten Kinderalter lautet die Regel: Gib immer 4 aus."},{"type":"M","value":"K(a)=4"},{"type":"H","value":"2. Verschiedene Eingaben prüfen"},{"type":"T","value":"Die Alter 8, 10 und 12 führen alle zum Preis 4. Das ist erlaubt: Jeder einzelnen Eingabe ist genau ein Preis zugeordnet."},{"type":"M","value":"8\\mapsto4,\\quad10\\mapsto4,\\quad12\\mapsto4"},{"type":"H","value":"3. Die Richtung umkehren"},{"type":"T","value":"Aus einem bezahlten Preis von 4 Euro lässt sich das Alter nicht eindeutig zurückgewinnen. Die umgekehrte Zuordnung hätte mehrere Ausgaben für dieselbe Eingabe."},{"type":"H","value":"4. Das Kriterium festhalten"},{"type":"T","value":"Für eine Funktion braucht jede erlaubte Eingabe genau eine Ausgabe. Verschiedene Eingaben dürfen dieselbe Ausgabe besitzen. Ob eine Umkehrung ebenfalls eine Funktion ist, ist eine neue Frage."}]},"source-0":{"title":"Wie hängt der Preis von der Anzahl ab?","blocks":[{"type":"H","value":"Wie hängt der Preis von der Anzahl ab?"},{"type":"T","value":"Ein Heft kostet 2 Euro. Die <b>Eingabe x</b> ist die Anzahl der Hefte, die <b>Ausgabe y</b> der Gesamtpreis in Euro. Eine <b>Funktion</b> ist eine eindeutige Zuordnung: Zu jeder erlaubten Eingabe gehört genau eine Ausgabe. Verschiedene Eingaben dürfen dieselbe Ausgabe haben. Die Regel lautet: Multipliziere die Heftanzahl mit 2."},{"type":"M","value":"y=2x"},{"type":"V","value":"F00"},{"type":"T","value":"Die <b>Tabelle</b> zeigt dieselbe Regel für einzelne Eingaben. Bei x = 3 erhalten wir y = 6. Die Einheiten gehören zu den Spalten: 3 Hefte kosten 6 Euro. Hier sind nur ganze Anzahlen ab 0 sinnvoll; 2,5 Hefte werden nicht verkauft."}],"prerequisites":["N02"]},"source-1":{"title":"Rückwärts nach einer Eingabe fragen","blocks":[{"type":"H","value":"Rückwärts nach einer Eingabe fragen"},{"type":"T","value":"Bei einem Preis von 8 Euro suchen wir die passende Anzahl. Wir teilen durch den Preis eines Heftes, weil Division die Multiplikation mit 2 rückgängig macht."},{"type":"M","value":"2x=8\\quad\\Longrightarrow\\quad x=4"},{"type":"T","value":"Die Probe lautet: 4 Hefte zu je 2 Euro kosten 8 Euro. Eine Tabelle nennt einzelne Wertepaare; die Gleichung beschreibt die Regel für alle erlaubten Anzahlen. Die Beschreibung in Worten erklärt, welche Größen diese Zahlen bedeuten."}],"prerequisites":["N02"]}},"taskExamples":{"F00_H":"source-1"}},"F01":{"default":"transfer","variants":{"transfer":{"title":"Proportionalität nach Abzug einer festen Gebühr","prerequisites":["D02","T01","F00"],"rationale":"Kontrastiert Gesamtpreis und variablen Anteil bei einem Versandpreis; analysiert die Modellbedingung statt nur einen Dreisatz zu rechnen.","blocks":[{"type":"H","value":"1. Bestandteile trennen"},{"type":"T","value":"Ein Versand verlangt 3 Euro Verpackungsgebühr plus 2 Euro je Kilogramm. Der Gesamtpreis enthält einen festen und einen mengenabhängigen Teil."},{"type":"M","value":"K(m)=3+2m"},{"type":"H","value":"2. Verdoppeln wirklich prüfen"},{"type":"T","value":"Bei 2 kg kostet der Versand 7 Euro, bei 4 kg 11 Euro. Die Masse verdoppelt sich, der Gesamtpreis aber nicht."},{"type":"M","value":"K(2)=7,\\quad K(4)=11\\ne2\\cdot7"},{"type":"H","value":"3. Nur den variablen Anteil betrachten"},{"type":"T","value":"Ziehe die Verpackungsgebühr ab. Dann bleiben 4 bzw. 8 Euro. Für diesen Anteil ist der Quotient Preis durch Masse konstant."},{"type":"M","value":"V(m)=K(m)-3=2m,\\qquad\\frac42=\\frac84=2"},{"type":"H","value":"4. Die Aussage genau formulieren"},{"type":"T","value":"Masse und Gesamtpreis sind nicht proportional. Masse und reiner Transportanteil sind proportional, solange derselbe Kilopreis gilt. Das Bezugsobjekt gehört zur Aussage."}]},"source-0":{"title":"Vom Preis einer Menge zum Preis einer Einheit","blocks":[{"type":"H","value":"Vom Preis einer Menge zum Preis einer Einheit"},{"type":"T","value":"3 kg Äpfel kosten 6 Euro, ohne Grundgebühr und bei festem Kilopreis. Dann ist die Zuordnung <b>proportional</b>: Doppelte Masse kostet doppelt so viel. Der konstante <b>Quotient</b> y/x ist der Preis pro Kilogramm, der <b>Proportionalitätsfaktor k</b>."},{"type":"M","value":"k=\\frac63=2\\quad\\mathrm{(Euro/kg)}\\qquad y=2x"},{"type":"V","value":"F01"},{"type":"T","value":"Der Graph ist eine Gerade durch den <b>Ursprung</b> (0| 0), denn 0 kg kosten 0 Euro. Der Punkt (3| 6) zeigt den gegebenen Einkauf. Zwischenwerte wie 1,5 kg sind hier sinnvoll."}],"prerequisites":["B08","D02"]},"source-1":{"title":"Der Dreisatz nutzt dieselbe feste Rate","blocks":[{"type":"H","value":"Der Dreisatz nutzt dieselbe feste Rate"},{"type":"M","value":"3\\,\\mathrm{kg}\\to6\\,\\mathrm{Euro};\\quad1\\,\\mathrm{kg}\\to2\\,\\mathrm{Euro};\\quad5\\,\\mathrm{kg}\\to10\\,\\mathrm{Euro}"},{"type":"T","value":"Wir teilen zuerst durch 3, um eine Einheit zu erhalten, und multiplizieren danach mit 5. Das ist der <b>Dreisatz</b>. Rückwärts reichen 9 Euro für 9 : 2 = 4,5 kg. Der Quotient y/x darf nur für x ≠ 0 gebildet werden; die Regel y = 2x gilt auch bei x = 0."}],"prerequisites":["B08","D02"]}},"taskExamples":{"F01_NEU_08":"source-0","F01_NEU_03":"source-0"}},"F02":{"default":"transfer","variants":{"transfer":{"title":"Mehr Anfangswert oder mehr Steigung?","prerequisites":["T01","R02","F00"],"rationale":"Vergleicht eine Änderung des Anfangswerts mit einer Änderung der Rate über Differenzfunktionen; keine bloße Parameterableseaufgabe.","blocks":[{"type":"H","value":"1. Einen Grundtarif aufstellen"},{"type":"T","value":"Eine Reparatur kostet 12 Euro Anfahrt und 8 Euro je Arbeitsstunde. Für h Stunden beträgt der Modellpreis 12 + 8h."},{"type":"M","value":"K(h)=12+8h"},{"type":"H","value":"2. Nur den Anfangswert ändern"},{"type":"T","value":"Wird die Anfahrt um 5 Euro teurer, steigen alle Preise genau um 5 Euro. Die Steigung bleibt 8."},{"type":"M","value":"A(h)=17+8h,\\qquad A(h)-K(h)=5"},{"type":"H","value":"3. Nur die Rate ändern"},{"type":"T","value":"Steigt stattdessen der Stundenpreis um 5 Euro, wächst der Aufpreis mit der Arbeitszeit: bei einer Stunde 5 Euro, bei drei Stunden 15 Euro."},{"type":"M","value":"B(h)=12+13h,\\qquad B(h)-K(h)=5h"},{"type":"H","value":"4. Am Graphen unterscheiden"},{"type":"T","value":"Mehr Anfangswert verschiebt die Gerade parallel nach oben. Mehr Steigung lässt sie bei demselben y-Achsenabschnitt steiler ansteigen. Preise brauchen Einheiten: Euro und Euro je Stunde."}]},"source-0":{"title":"Eine Gerade aus zwei Angaben zeichnen","blocks":[{"type":"H","value":"Eine Gerade aus zwei Angaben zeichnen"},{"type":"T","value":"Bei y = −2x + 5 ist 5 der <b>y-Achsenabschnitt b</b>: Für x = 0 ist y = 5. Der Zahlenfaktor −2 vor x heißt <b>Koeffizient</b> und ist hier die <b>Steigung m</b>. Er gibt die Änderung von y an, wenn x um 1 wächst. Negativ bedeutet hier: Die Gerade fällt nach rechts."},{"type":"V","value":"F02"},{"type":"T","value":"Wir markieren (0| 5), gehen 1 nach rechts und 2 nach unten zum Punkt (1| 3). Das <b>Steigungsdreieck</b> zeigt waagerechte Änderung Δx = 1 und senkrechte Änderung Δy = −2. Durch die beiden Punkte zeichnen wir die Gerade."},{"type":"M","value":"m=\\frac{\\Delta y}{\\Delta x}=\\frac{-2}{1}=-2\\qquad y=mx+b=-2x+5"},{"type":"T","value":"Auch 2 nach rechts und 4 nach unten ergeben dieselbe Steigung: −4/2 = −2. Es geht also um das Verhältnis der Änderungen, nicht nur um die Länge eines Pfeils."}],"prerequisites":["T01","R02"]},"source-1":{"title":"Rückwärts aus einer Beschreibung zur Gleichung","blocks":[{"type":"H","value":"Rückwärts aus einer Beschreibung zur Gleichung"},{"type":"T","value":"Eine Gerade startet an der y-Achse bei 1 und steigt bei 2 Schritten nach rechts um 3. Dann ist b = 1 und m = 3/2. Die lineare Funktionsgleichung lautet y = 1,5x + 1. „Steigt um 3“ allein reicht ohne den waagerechten Schritt nicht aus."},{"type":"M","value":"y=\\frac32x+1"}],"prerequisites":["T01","R02"]}},"taskExamples":{}},"F03":{"default":"transfer","variants":{"transfer":{"title":"Eine Tabelle kann eine Gerade widerlegen","prerequisites":["T01","F02"],"rationale":"Fokussiert Kontrollpunkt und ungeeignete Verbindung von Tabellenpunkten statt reine Wertetabelle/Zeichnung.","blocks":[{"type":"H","value":"1. Zwei Punkte als Vorschlag nutzen"},{"type":"T","value":"Eine Tabelle enthält (0|1), (2|5) und (4|10). Die ersten beiden Punkte schlagen eine Gerade mit Steigung 2 und Achsenabschnitt 1 vor."},{"type":"M","value":"m=\\frac{5-1}{2-0}=2,\\qquad y=2x+1"},{"type":"H","value":"2. Den dritten Punkt vorhersagen"},{"type":"T","value":"Die vorgeschlagene Gerade liefert bei x = 4 den Wert 9. In der Tabelle steht jedoch 10."},{"type":"M","value":"2\\cdot4+1=9\\ne10"},{"type":"H","value":"3. Die Zeichnung kontrollieren"},{"type":"T","value":"Die ersten zwei Punkte lassen sich mit einer Geraden verbinden. Der dritte liegt eine Einheit über ihr. Eine geknickte Verbindung aller drei Punkte wäre nicht der Graph derselben linearen Funktion."},{"type":"H","value":"4. Nicht vorschnell korrigieren"},{"type":"T","value":"Die Daten können nicht alle exakt zu dieser Geraden gehören. Ob ein Tabellenfehler vorliegt oder die Zuordnung nicht linear ist, lässt sich nur mit weiteren Angaben entscheiden. Bei Messdaten könnte eine Näherung sinnvoll sein."}]},"source-0":{"title":"Eine Funktion in drei Darstellungen","blocks":[{"type":"H","value":"Eine Funktion in drei Darstellungen"},{"type":"T","value":"Die <b>Funktionsgleichung</b> y = 2x + 1 ist die Rechenregel. x ist die Eingabe, y die Ausgabe. Die 2 ist der <b>Koeffizient</b>, also der Zahlenfaktor vor x, und zugleich die Steigung: Ein Schritt mehr bei x ergibt zwei mehr bei y. Die 1 ist der y-Wert bei x = 0."},{"type":"M","value":"x=-1:\\quad y=2\\cdot(-1)+1=-1\\qquad x=2:\\quad y=2\\cdot2+1=5"},{"type":"T","value":"Wir setzen mehrere x-Werte ein. Jede Spalte der <b>Wertetabelle</b> enthält ein zusammengehöriges <b>Wertepaar</b>. Das Paar (2| 5) wird im Koordinatensystem zum Punkt: 2 nach rechts, 5 nach oben."},{"type":"V","value":"F03"},{"type":"T","value":"Der <b>Graph</b> besteht aus allen Punkten, deren Koordinaten die Gleichung erfüllen. Weil die Funktion linear ist, liegen die Punkte auf einer Geraden. Wir verbinden sie mit dem Lineal und setzen die Gerade im dargestellten Bereich fort; ein dritter Punkt kontrolliert die Zeichnung."}],"prerequisites":["F02","G03"]},"source-1":{"title":"Rückwärts aus der Tabelle die Regel erkennen","blocks":[{"type":"H","value":"Rückwärts aus der Tabelle die Regel erkennen"},{"type":"T","value":"Bei gleich großen x-Schritten von 1 steigen die y-Werte jeweils um 2. Also ist die Steigung 2. Die Spalte x = 0 liefert den Achsenabschnitt 1. Zusammen erhalten wir wieder y = 2x + 1. Aus wenigen Tabellenwerten folgt diese Regel nur dann eindeutig, wenn ein lineares Modell vorausgesetzt wird."}],"prerequisites":["F02","G03"]}},"taskExamples":{"F03_NEU_05":"source-1","F03_NEU_06":"source-1"}},"F04":{"default":"transfer","variants":{"transfer":{"title":"Zwei Punkte: waagerecht ist erlaubt, senkrecht nicht","prerequisites":["G03","F00","R02"],"rationale":"Kontrastiert Nullzähler und Nullnenner der Steigung; behandelt Definitionsgrenze statt weitere reguläre Zweipunktrechnung.","blocks":[{"type":"H","value":"1. Gleiche Höhe untersuchen"},{"type":"T","value":"A(−2|3) und B(5|3) haben verschiedene x-Werte, aber dieselbe Höhe. Die y-Änderung ist null."},{"type":"M","value":"m=\\frac{3-3}{5-(-2)}=\\frac07=0"},{"type":"H","value":"2. Die passende Funktion angeben"},{"type":"T","value":"Die waagerechte Gerade liefert bei jedem x den Wert 3. Das ist eine lineare Funktion mit Steigung 0."},{"type":"M","value":"y=3"},{"type":"H","value":"3. Gleiche x-Koordinate vergleichen"},{"type":"T","value":"C(2|−1) und D(2|4) haben denselben x-Wert. Nun wäre der Nenner null. Durch null kann man nicht teilen."},{"type":"M","value":"\\Delta x=2-2=0,\\qquad\\Delta y=4-(-1)=5"},{"type":"H","value":"4. Geometrie und Funktion verbinden"},{"type":"T","value":"Die Gerade durch C und D ist senkrecht. Sie existiert geometrisch, lässt sich aber nicht als y = mx + b beschreiben: Zur Eingabe 2 gehörten mehrere y-Werte. Nullsteigung und fehlende definierte Steigung sind verschieden."}]},"source-0":{"title":"Aus A(1| 3) und B(3| 7) eine Regel gewinnen","blocks":[{"type":"H","value":"Aus A(1| 3) und B(3| 7) eine Regel gewinnen"},{"type":"T","value":"Zwei Punkte mit verschiedenen x-Werten bestimmen genau eine Gerade als Funktionsgraph. Von A zu B wächst x um 2 und y um 4. Die <b>Steigung</b> ist der y-Zuwachs pro x-Schritt; deshalb teilen wir beide Änderungen durcheinander."},{"type":"M","value":"m=\\frac{7-3}{3-1}=\\frac42=2"},{"type":"V","value":"F04"},{"type":"T","value":"In y = mx + b kennen wir nun m = 2. Um den <b>Achsenabschnitt b</b>, also den y-Wert bei x = 0, zu finden, setzen wir einen bekannten Punkt ein. Für A muss gelten: 3 = 2 · 1 + b. Also bleibt b = 1."},{"type":"M","value":"y=2x+1"},{"type":"T","value":"Beide Punkte prüfen die Gleichung: Bei x = 1 ergibt sich 3, bei x = 3 ergibt sich 7. Berechne die Differenzen im Bruch in derselben Punktreihenfolge; sonst entsteht ein falsches Vorzeichen."},{"type":"M","value":"2\\cdot1+1=3\\qquad2\\cdot3+1=7"},{"type":"T","value":"Hätten die Punkte denselben x-Wert, etwa (1| 3) und (1| 7), entstünde eine senkrechte Gerade. Sie lässt sich nicht als y = mx + b schreiben: Einer Eingabe x = 1 wären dann mehrere y-Werte zugeordnet, und im Steigungsbruch stünde eine Division durch 0."}],"prerequisites":["F02","E02"]}},"taskExamples":{"F04_POOL_04":"source-0","F04_NEU_05":"source-0","F04_NEU_08":"source-0"}},"F05":{"default":"transfer","variants":{"transfer":{"title":"Kein Schnittpunkt oder unendlich viele?","prerequisites":["E01","F02","T02"],"rationale":"Unterscheidet drei Fälle des Gleichsetzens mit identischer Steigung und schützt vor unzulässiger Division durch null.","blocks":[{"type":"H","value":"1. Zwei parallel verlaufende Tarife vergleichen"},{"type":"T","value":"Tarif A kostet 2x + 3, Tarif B kostet 2x + 8. Für einen Schnittpunkt setzt man beide Preise gleich."},{"type":"M","value":"2x+3=2x+8"},{"type":"H","value":"2. Gemeinsame Veränderung abziehen"},{"type":"T","value":"Nach Abziehen von 2x bleibt 3 = 8. Das ist falsch, unabhängig von x. Es gibt keinen Schnittpunkt; B ist immer 5 teurer."},{"type":"M","value":"3=8\\quad\\text{ist falsch}"},{"type":"H","value":"3. Anders geschriebene identische Regeln prüfen"},{"type":"T","value":"Tarif C lautet 2(x + 1,5). Ausmultiplizieren ergibt 2x + 3. A und C beschreiben dieselbe Gerade."},{"type":"M","value":"2(x+1{,}5)=2x+3"},{"type":"H","value":"4. Die Lösungsfälle erkennen"},{"type":"T","value":"A = C führt auf 3 = 3: Jeder erlaubte x-Wert passt. Gleichsetzen kann genau einen, keinen oder unendlich viele gemeinsame Punkte ergeben. Nicht jede Aufgabe endet mit einer einzelnen Zahl."}]},"source-0":{"title":"Wo trifft eine Gerade die x-Achse?","blocks":[{"type":"H","value":"Wo trifft eine Gerade die x-Achse?"},{"type":"T","value":"Für f(x) = 2x − 4 suchen wir die <b>Nullstelle</b>, also den x-Wert mit Funktionswert 0. Auf der x-Achse ist die y-Koordinate immer 0. Genau deshalb setzen wir die Funktionsgleichung gleich null."},{"type":"M","value":"2x-4=0\\quad\\Longrightarrow\\quad x=2\\qquad N(2|0)"},{"type":"T","value":"Die <b>Stelle</b> ist die Zahl 2. Der <b>Punkt</b> N besitzt zwei Koordinaten: (2| 0). Diese Begriffe meinen also nicht dasselbe."},{"type":"V","value":"F05"}],"prerequisites":["F03","E02","E07"]},"source-1":{"title":"Wo treffen sich zwei Funktionsgraphen?","blocks":[{"type":"H","value":"Wo treffen sich zwei Funktionsgraphen?"},{"type":"T","value":"Für g(x) = −x + 5 muss am Schnittpunkt derselbe x-Wert denselben y-Wert liefern wie f. Darum setzen wir die beiden Terme <b>gleich</b>. Anschließend fehlt noch die y-Koordinate."},{"type":"M","value":"2x-4=-x+5\\quad\\Longrightarrow\\quad3x=9\\quad\\Longrightarrow\\quad x=3"},{"type":"M","value":"f(3)=2\\cdot3-4=2\\qquad g(3)=-3+5=2"},{"type":"T","value":"Der Schnittpunkt ist S(3| 2). Beide Funktionswerte stimmen überein, das ist die Probe. x = 3 allein wäre nur die Schnittstelle; für den gemeinsamen Punkt müssen wir beide Koordinaten nennen."}],"prerequisites":["F03","E02","E07"]}},"taskExamples":{}},"F06":{"default":"transfer","variants":{"transfer":{"title":"Zwei verschieden starke Pumpen sind nicht einfach zwei gleiche","prerequisites":["D02","F01","T01"],"rationale":"Prüft die gleiche-Leistung-Annahme; addiert reale Raten statt gleich starke Pumpenzahlen nur zu variieren.","blocks":[{"type":"H","value":"1. Die Gesamtarbeit festhalten"},{"type":"T","value":"Ein Behälter enthält 600 Liter. Pumpe A fördert 100 Liter je Minute, Pumpe B nur 50. Die gemeinsame Aufgabe bleibt das Leeren derselben Wassermenge."},{"type":"H","value":"2. Einzelzeiten berechnen"},{"type":"T","value":"Allein braucht A sechs Minuten, B zwölf Minuten. Die Anzahl „eine Pumpe“ reicht also ohne Leistung nicht zur Zeitbestimmung."},{"type":"M","value":"t_A=600:100=6,\\qquad t_B=600:50=12"},{"type":"H","value":"3. Gemeinsam die Leistungen addieren"},{"type":"T","value":"Ohne gegenseitige Behinderung fördern beide zusammen 150 Liter je Minute. Die Zeit beträgt vier Minuten."},{"type":"M","value":"t=\\frac{600}{100+50}=4\\ \\mathrm{min}"},{"type":"H","value":"4. Das falsche Modell erklären"},{"type":"T","value":"Zwei Pumpen halbieren die sechs Minuten von A nicht, weil B schwächer ist. Antiproportional ist hier Zeit zur gesamten konstanten Förderrate, nicht blind zur Pumpenzahl."}]},"source-0":{"title":"Mehr Helfer – weniger Zeit unter klaren Bedingungen","blocks":[{"type":"H","value":"Mehr Helfer – weniger Zeit unter klaren Bedingungen"},{"type":"T","value":"Für eine Arbeit benötigen 2 gleich schnelle Helfer 6 Stunden. Wir nehmen an: Die Arbeit ist beliebig aufteilbar, alle arbeiten gleich schnell und behindern sich nicht. Dann ist die Zuordnung <b>antiproportional</b>: Doppelt so viele Helfer benötigen halb so viel Zeit."},{"type":"M","value":"x\\cdot y=2\\cdot6=12\\qquad y=\\frac{12}{x}\\quad(x>0)"},{"type":"V","value":"F06"},{"type":"T","value":"Das konstante <b>Produkt</b> 12 beschreibt die benötigten Helferstunden. 3 Helfer brauchen daher 12 : 3 = 4 Stunden. Anders als bei Proportionalität bleibt hier das Produkt gleich, nicht der Quotient."},{"type":"M","value":"2\\cdot6=3\\cdot4=4\\cdot3=12"},{"type":"T","value":"Die gezeichnete Kurve ist ein Teil einer <b>Hyperbel</b>. Das mathematische Modell lässt positive Zwischenwerte zu; in der Helferaufgabe wählen wir ganze Helferzahlen. Bei x = 0 ist die Formel nicht definiert: Ohne Helfer wird die Arbeit nicht in endlicher Zeit fertig."},{"type":"T","value":"Die Annahmen sind entscheidend. Wenn nur ein Gerät verfügbar ist und die Helfer warten müssen, halbiert doppelte Helferzahl die Zeit möglicherweise nicht. Prüfe die Situation, bevor du antiproportional rechnest."}],"prerequisites":["D02","F01"]}},"taskExamples":{}},"F07":{"default":"transfer","variants":{"transfer":{"title":"Sinkende Werte reichen zur Einordnung nicht","prerequisites":["F01","F06","R02"],"rationale":"Vergleicht fallendes lineares mit antiproportionalem Modell an gleichzeitiger Produkt- und Änderungsprüfung.","blocks":[{"type":"H","value":"1. Zwei fallende Regeln ansehen"},{"type":"T","value":"Für positive Eingaben betrachten wir A(x) = 12 − 2x und B(x) = 12/x. Beide fallen, wenn x größer wird."},{"type":"M","value":"A(1)=10,\\ A(2)=8,\\ A(3)=6;\\qquad B(1)=12,\\ B(2)=6,\\ B(3)=4"},{"type":"H","value":"2. Feste Änderungen prüfen"},{"type":"T","value":"Bei A sinkt y mit jedem x-Schritt um 2. Das ist ein lineares Modell. Die Produkte 10, 16 und 18 sind nicht konstant."},{"type":"M","value":"\\Delta A=-2,\\qquad 1\\cdot10\\ne2\\cdot8"},{"type":"H","value":"3. Feste Produkte prüfen"},{"type":"T","value":"Bei B sind die y-Abnahmen zuerst 6 und dann 2, also nicht gleich. Dafür ist das Produkt xy immer 12."},{"type":"M","value":"1\\cdot12=2\\cdot6=3\\cdot4=12"},{"type":"H","value":"4. Mit dem richtigen Kennzeichen entscheiden"},{"type":"T","value":"A ist linear, aber wegen des Anfangswerts 12 nicht proportional. B ist antiproportional. Die Richtung „fallend“ ist eine Beobachtung; entscheidend sind Rate, Quotient oder Produkt."}]},"source-0":{"title":"Drei Tabellen systematisch unterscheiden","blocks":[{"type":"H","value":"Drei Tabellen systematisch unterscheiden"},{"type":"V","value":"F07"},{"type":"T","value":"Bei A bleibt y/x = 2: 2/1, 4/2 und 8/4 ergeben denselben Wert. Das ist eine <b>proportionale</b> Zuordnung mit y = 2x. Ihr Graph ist eine Gerade durch den Ursprung."},{"type":"M","value":"A:\\ y=2x"},{"type":"T","value":"Bei B bleibt xy = 12: 1 · 12, 2 · 6 und 4 · 3 sind gleich. Das ist <b>antiproportional</b> mit y = 12/x. Bei einer Verdoppelung von x halbiert sich y."},{"type":"M","value":"B:\\ y=\\frac{12}{x}\\quad(x\\ne0)"},{"type":"T","value":"Bei C steigt y pro x-Schritt um 2. Von x = 2 zu x = 4 sind es zwei Schritte, also ein Zuwachs von 4. Die Quotienten y/x sind dagegen verschieden. C ist <b>linear</b> mit Achsenabschnitt 1, aber nicht proportional."},{"type":"M","value":"C:\\ y=2x+1"},{"type":"T","value":"Proportionale Zuordnungen sind ein besonderer Fall linearer Funktionen mit b = 0. Vergleiche bei „konstantem Zuwachs“ immer gleich große x-Schritte oder den Quotienten Δy/Δx. Eine Tabelle allein beweist keinen Modelltyp für alle weiteren Werte; die Regel oder der Sachzusammenhang muss die Fortsetzung rechtfertigen."}],"prerequisites":["F01","F02","F06"]}},"taskExamples":{"F07_L4_04":"source-0"}},"F08":{"default":"transfer","variants":{"transfer":{"title":"Ein Tarif startet erst nach einer Freiphase","prerequisites":["T01","E01","F02"],"rationale":"Stückweises Modell mit verschobenem Zeitursprung statt Tankvolumen mit bloß anderem Anfangswert.","blocks":[{"type":"H","value":"1. Die Bedingungen lesen"},{"type":"T","value":"Die ersten 30 Minuten eines Verleihs sind kostenlos. Danach werden minutengenau 4 Euro je zusätzliche Stunde berechnet. Wir verwenden t in Stunden."},{"type":"H","value":"2. Die kostenlose Phase abgrenzen"},{"type":"T","value":"Eine halbe Stunde entspricht 0,5 Stunden. Bis dahin ist der Preis null, auch wenn Zeit verstreicht."},{"type":"M","value":"K(t)=0\\quad\\text{für }0\\le t\\le0{,}5"},{"type":"H","value":"3. Nur die bezahlte Dauer einsetzen"},{"type":"T","value":"Nach zwei Stunden sind 1,5 Stunden kostenpflichtig. Der Preis ist deshalb 6 Euro und nicht 8 Euro."},{"type":"M","value":"K(t)=4(t-0{,}5)\\quad\\text{für }t>0{,}5,\\qquad K(2)=6"},{"type":"H","value":"4. Die Grenze kontrollieren"},{"type":"T","value":"Bei t = 0,5 liefert auch die zweite Formel 0. Sie darf trotzdem nicht auf frühere Zeiten als realer Preis ausgedehnt werden: Negative Gebühren wären hier sinnlos. Eine Situation kann mehrere passende Modellabschnitte brauchen."}]},"source-0":{"title":"Zwei Fahrradverleihe vergleichen","blocks":[{"type":"H","value":"Zwei Fahrradverleihe vergleichen"},{"type":"T","value":"Verleih A verlangt 4 Euro Grundgebühr plus 2 Euro je Stunde. Verleih B verlangt 1 Euro Grundgebühr plus 3 Euro je Stunde. Wir nehmen minutengenaue Abrechnung und höchstens 6 Stunden an. x ist die Dauer in Stunden, K der Preis in Euro."},{"type":"M","value":"K_A(x)=4+2x\\qquad K_B(x)=1+3x\\qquad0\\le x\\le6"},{"type":"T","value":"Die <b>Grundgebühr</b> ist der Preis bei x = 0; die <b>Rate</b> beschreibt die Zunahme pro Stunde. Diese feste Zunahme begründet das lineare Modell. Der <b>Gültigkeitsbereich</b> schränkt ein, welche Eingaben zur angenommenen Situation gehören."},{"type":"V","value":"F08"},{"type":"T","value":"Gleiche Kosten bedeuten gleiche Funktionswerte. Wir setzen die Terme gleich: 4 + 2x = 1 + 3x, also x = 3. Beide kosten dann 10 Euro. Für 2 Stunden ist B mit 7 Euro günstiger als A mit 8 Euro; für 4 Stunden ist A günstiger."},{"type":"M","value":"K_A(3)=K_B(3)=10"},{"type":"T","value":"Negative Mietzeiten sind unmöglich. Für 20 Stunden dürfen wir die Formel ohne Kenntnis des Tarifs nicht verwenden. Wenn nur volle Stunden abgerechnet werden, passen auch nicht alle Zwischenwerte zur linearen Geraden; das Modell muss dann angepasst werden."}],"prerequisites":["F02","E05"]}},"taskExamples":{}},"F09":{"default":"transfer","variants":{"transfer":{"title":"Gleiche Abweichungssumme kann täuschen","prerequisites":["R02","R04","S04"],"rationale":"Kontrastiert vorzeichenbehaftete Summe mit Betrags-/Quadratkriterium; keine weitere einfache Einzelabweichung.","blocks":[{"type":"H","value":"1. Ein einfaches Modell prüfen"},{"type":"T","value":"Drei Messungen bei x = 0, 1, 2 liefern y = 1, 4, 4. Der Modellvorschlag y = 2x + 1 liefert 1, 3, 5."},{"type":"M","value":"\\text{Messung}-\\text{Modell}:\\quad 0,\\ 1,\\ -1"},{"type":"H","value":"2. Das Aufheben erkennen"},{"type":"T","value":"Die vorzeichenbehaftete Summe ist 0. Das bedeutet nicht, dass alle Messpunkte getroffen werden: +1 und −1 heben sich nur auf."},{"type":"M","value":"0+1-1=0"},{"type":"H","value":"3. Fehlergrößen vergleichen"},{"type":"T","value":"Beträge zählen beide Abweichungen positiv. Auch Quadrate vermeiden das gegenseitige Aufheben und gewichten größere Abweichungen stärker."},{"type":"M","value":"|0|+|1|+|-1|=2,\\qquad0^2+1^2+(-1)^2=2"},{"type":"H","value":"4. Das Urteil begrenzen"},{"type":"T","value":"Ein Modellvergleich muss sein Kriterium nennen. Eine verschwindende einfache Fehlersumme beweist weder exakte Passung noch optimale Modellwahl. Zusätzlich braucht man Messbereich und sachliche Plausibilität."}]},"source-0":{"title":"Eine Gerade beschreibt einen Trend, nicht jeden Messwert","blocks":[{"type":"H","value":"Eine Gerade beschreibt einen Trend, nicht jeden Messwert"},{"type":"T","value":"Wir messen zu x = 0, 1, 2, 3 die Werte y = 1,1; 2,9; 5,1; 6,9. Die <b>Messpunkte</b> liegen fast auf einer Geraden. Als einfache <b>Ausgleichsgerade</b> schlagen wir y = 2x + 1 vor: Sie beschreibt den mittleren Verlauf, ohne jeden Punkt genau zu treffen."},{"type":"V","value":"F09"},{"type":"T","value":"Eine <b>Abweichung</b> ist Messwert minus Modellwert. Bei x = 1 sagt das Modell 3 voraus, gemessen wurde 2,9. Die Abweichung ist −0,1. An den vier Stellen lauten die Abweichungen +0,1; −0,1; +0,1; −0,1. Es gibt kleine Abweichungen auf beiden Seiten."},{"type":"M","value":"2{,}9-(2\\cdot1+1)=-0{,}1"},{"type":"T","value":"Für x = 1,5 liefert das Modell y ≈ 4. Das ist eine Schätzung <b>innerhalb</b> der Messspanne, eine Interpolation. Wir schreiben ≈, weil die Daten nur näherungsweise beschrieben werden."},{"type":"M","value":"y\\approx2\\cdot1{,}5+1=4"},{"type":"T","value":"Für x = 20 ergäbe die Gerade zwar 41, aber diese <b>Extrapolation</b> liegt weit außerhalb der Messspanne. Der Zusammenhang könnte sich dort ändern. Unsere Gerade ist ein begründeter Vorschlag; eine rechnerische Regression kann ihre Parameter nach einem festgelegten Fehlermaß weiter optimieren."}],"prerequisites":["F03","F04"]}},"taskExamples":{}},"G01":{"default":"transfer","variants":{"transfer":{"title":"Ein gedrehtes Quadrat behält seine Namen","prerequisites":["G02"],"rationale":"Kontrastiert Lagewirkung mit definierenden Eigenschaften und inklusiver Klassifikation.","blocks":[{"type":"H","value":"1. Eigenschaften statt Lage lesen"},{"type":"T","value":"Ein Viereck hat vier gleich lange Seiten und vier rechte Winkel. Es ist ein Quadrat und erfüllt zugleich die Definition eines Rechtecks."},{"type":"H","value":"2. Die Figur drehen"},{"type":"T","value":"Drehe das ganze Blatt um 45°. Keine Seitenlänge und kein Winkel ändern sich. Die Figur bleibt Quadrat und Rechteck, auch wenn eine Ecke nach oben zeigt."},{"type":"H","value":"3. Ein ähnliches Aussehen unterscheiden"},{"type":"T","value":"Eine Raute mit Winkeln 60° und 120° hat ebenfalls vier gleiche Seiten. Ihr fehlen aber rechte Winkel; deshalb ist sie kein Quadrat."},{"type":"M","value":"60^\\circ\\ne90^\\circ"},{"type":"H","value":"4. Die Entscheidung begründen"},{"type":"T","value":"„Sie sieht aus wie ein Diamant“ ist keine mathematische Definition. Prüfe gleiche Seiten, parallele Seiten und rechte Winkel. Mehrere passende Figurennamen schließen einander nicht aus."}]},"source-0":{"title":"Geometrische Objekte durch Eigenschaften erkennen","blocks":[{"type":"H","value":"Geometrische Objekte durch Eigenschaften erkennen"},{"type":"V","value":"G01"},{"type":"T","value":"Eine <b>Strecke</b> hat zwei Endpunkte und eine bestimmte Länge. Ein <b>Strahl</b> hat einen Anfangspunkt und läuft in eine Richtung unbegrenzt weiter; eine <b>Gerade</b> in beide Richtungen. In Zeichnungen zeigen Pfeile die Fortsetzung. Zwei Geraden sind parallel, wenn sie in einer Ebene keinen gemeinsamen Punkt haben; senkrechte Geraden schneiden sich im rechten Winkel."}],"prerequisites":[]},"source-1":{"title":"Warum jedes Quadrat auch ein Rechteck ist","blocks":[{"type":"H","value":"Warum jedes Quadrat auch ein Rechteck ist"},{"type":"T","value":"Ein <b>Rechteck</b> hat vier rechte Winkel. Ein <b>Quadrat</b> erfüllt diese Bedingung ebenfalls und hat zusätzlich vier gleich lange Seiten. Es gehört daher zur Menge der Rechtecke. Ein Rechteck mit Seiten 3 cm und 5 cm ist dagegen kein Quadrat."},{"type":"M","value":"\\mathrm{Quadrate}\\subset\\mathrm{Rechtecke}"},{"type":"T","value":"Ein <b>Quader</b> ist räumlich: Er hat 6 rechteckige Flächen, 12 Kanten und 8 Ecken. Eine <b>Kante</b> ist die gemeinsame Begrenzungsstrecke zweier Flächen; an einer <b>Ecke</b> treffen beim Quader drei Kanten zusammen. Ein Würfel ist ein besonderer Quader mit gleich langen Kanten."},{"type":"T","value":"Zählen hilft beim Unterscheiden: Ein Rechteck hat 4 Seiten und 4 Eckpunkte in einer Ebene. Der Körper Quader hat dagegen Flächen, Kanten und räumliche Ecken. Eine perspektivische Zeichnung ändert diese Eigenschaften nicht."}],"prerequisites":[]}},"taskExamples":{}},"G02":{"default":"transfer","variants":{"transfer":{"title":"Ein Winkel wird größer gezeichnet, aber nicht größer geöffnet","prerequisites":["G01"],"rationale":"Trennt Schenkellänge, Drehung und Winkelgröße; explizite Fehlskalenkontrolle ohne weitere Winkelsummenvariation.","blocks":[{"type":"H","value":"1. Die Öffnung messen"},{"type":"T","value":"Zwei Schenkel bilden 40°. Der Scheitel ist ihr gemeinsamer Anfangspunkt; der Winkel beschreibt ihre Öffnung, nicht ihre Länge."},{"type":"H","value":"2. Die Schenkel verlängern"},{"type":"T","value":"Verdopple beide gezeichneten Schenkellängen. Die Richtungen bleiben gleich, also bleibt die Öffnung 40°."},{"type":"M","value":"\\alpha=40^\\circ\\quad\\text{vorher und nachher}"},{"type":"H","value":"3. Die Skala passend auswählen"},{"type":"T","value":"Beim Geodreieck liegt 0 am ersten Schenkel. Der passende Ablesewert ist 40°, nicht 140°. Die Skizze ist spitz, also kleiner als 90°."},{"type":"M","value":"40^\\circ<90^\\circ<140^\\circ"},{"type":"H","value":"4. Eine echte Änderung erkennen"},{"type":"T","value":"Erst das Drehen eines Schenkels relativ zum anderen verändert den Winkel. Das Drehen der gesamten Figur oder längeres Zeichnen tut es nicht."}]},"source-0":{"title":"Einen Winkel zeichnen und an der richtigen Skala lesen","blocks":[{"type":"H","value":"Einen Winkel zeichnen und an der richtigen Skala lesen"},{"type":"T","value":"Ein <b>Winkel</b> wird von zwei Schenkeln mit gemeinsamem <b>Scheitel</b> begrenzt. Für 60° zeichnen wir einen Schenkel, legen den Mittelpunkt des Geodreiecks auf den Scheitel und die Nulllinie an den Schenkel. Wir wählen die Skala, die dort bei 0° beginnt, markieren 60° und zeichnen den zweiten Schenkel durch die Markierung."},{"type":"V","value":"G02"},{"type":"T","value":"Beim Messen gehen wir genauso vor: Mittelpunkt auf den Scheitel, Nulllinie auf einen Schenkel, Wert am anderen ablesen. Das Winkelmaß hängt von der Öffnung ab, nicht von den gezeichneten Schenkellängen."}],"prerequisites":["G01"]},"source-1":{"title":"Winkel mit Sätzen berechnen","blocks":[{"type":"H","value":"Winkel mit Sätzen berechnen"},{"type":"T","value":"An zwei sich schneidenden Geraden ist ein Winkel 60°. Sein <b>Nebenwinkel</b> ergänzt ihn zu einem gestreckten Winkel von 180°, ist also 120°. Der gegenüberliegende <b>Scheitelwinkel</b> ist wieder 60°: Beide ergänzen denselben Nebenwinkel zu 180°."},{"type":"M","value":"180^\\circ-60^\\circ=120^\\circ"},{"type":"T","value":"In einem Dreieck mit Innenwinkeln 50° und 60° fehlt der dritte Winkel γ. Die <b>Innenwinkelsumme</b> beträgt 180°, deshalb ziehen wir die beiden bekannten Winkel davon ab."},{"type":"M","value":"\\gamma=180^\\circ-50^\\circ-60^\\circ=70^\\circ"}],"prerequisites":["G01"]}},"taskExamples":{}},"G03":{"default":"transfer","variants":{"transfer":{"title":"Die Zeichenlänge hängt von der Achseneinheit ab","prerequisites":["M01","N01"],"rationale":"Vergleicht zwei Maßstäbe desselben Koordinatenpunkts; klärt Einheiten vs Papierabstände statt nur Punkte setzen.","blocks":[{"type":"H","value":"1. Den Punkt unabhängig vom Papier lesen"},{"type":"T","value":"P(−3|2) bedeutet drei Einheiten nach links und zwei nach oben. Das Koordinatenpaar beschreibt Einheiten, keine automatisch festgelegten Zentimeter."},{"type":"H","value":"2. Mit einer halben Zentimetereinheit zeichnen"},{"type":"T","value":"Bei 0,5 cm je Einheit geht man 1,5 cm links und 1 cm oben."},{"type":"M","value":"3\\cdot0{,}5=1{,}5,\\qquad2\\cdot0{,}5=1"},{"type":"H","value":"3. Auf eine zweite Zeichnung übertragen"},{"type":"T","value":"Bei 1 cm je Einheit sind es 3 cm links und 2 cm oben. Der Punkt heißt weiterhin P(−3|2), obwohl die gezeichneten Abstände doppelt so groß sind."},{"type":"H","value":"4. Koordinaten und Abstand unterscheiden"},{"type":"T","value":"Eine andere Skalierung verändert die Zeichnung, nicht die Werte. Zum Ablesen benötigt man Achsenbeschriftung und Einheit. Die erste Koordinate bleibt immer x."}]},"source-0":{"title":"Vom Zahlenpaar zum Punkt","blocks":[{"type":"H","value":"Vom Zahlenpaar zum Punkt"},{"type":"T","value":"Der Punkt P(−2| 3) besitzt zwei <b>Koordinaten</b>. Zuerst kommt x: vom <b>Ursprung</b> zwei Einheiten nach links. Danach kommt y: drei Einheiten nach oben. Die waagerechte Achse heißt x-Achse, die senkrechte y-Achse. Der Ursprung hat die Koordinaten (0| 0)."},{"type":"V","value":"G03"},{"type":"T","value":"Der Punkt Q(2| 3) liegt auf derselben Höhe. Zwischen P und Q liegen 4 waagerechte Einheiten, denn von −2 bis 0 sind es zwei und von 0 bis 2 nochmals zwei. Für diese waagerechte Strecke nehmen wir die Differenz der x-Koordinaten als positiven Abstand."},{"type":"M","value":"\\lvert2-(-2)\\rvert=4"},{"type":"T","value":"R(2| −1) liegt vier Einheiten unter Q. Dort stimmen die x-Koordinaten überein, also bestimmen die y-Koordinaten den senkrechten Abstand. Die Achsenskalierung muss dabei beachtet werden: Ein Kästchen muss nicht automatisch eine Einheit sein."},{"type":"M","value":"\\lvert3-(-1)\\rvert=4"},{"type":"T","value":"Die Reihenfolge ist wichtig: (−2| 3) und (3| −2) sind unterschiedliche Punkte. Für schräg liegende Strecken reicht das Abziehen nur einer Koordinate nicht; dieses Beispiel nutzt bewusst waagerechte und senkrechte Abstände."}],"prerequisites":["R01","G01"]}},"taskExamples":{}},"G04":{"default":"transfer","variants":{"transfer":{"title":"Zweimal spiegeln kann verschieben","prerequisites":["G03","R02"],"rationale":"Verknüpft zwei nicht identische Spiegelachsen und leitet den resultierenden Verschiebungsvektor her.","blocks":[{"type":"H","value":"1. Erst an der y-Achse spiegeln"},{"type":"T","value":"P(1|2) wird zu P₁(−1|2). Nur die x-Koordinate ändert ihr Vorzeichen."},{"type":"H","value":"2. An einer zweiten Achse spiegeln"},{"type":"T","value":"Spiegle danach an x = 3. P₁ liegt vier Einheiten links davon; sein Bild liegt vier Einheiten rechts, also bei x = 7."},{"type":"M","value":"P_2=(7|2)"},{"type":"H","value":"3. Den ganzen Weg vergleichen"},{"type":"T","value":"Vom ursprünglichen P(1|2) zum Endpunkt P₂(7|2) geht es sechs Einheiten nach rechts. Die Höhe bleibt unverändert."},{"type":"M","value":"7-1=6"},{"type":"H","value":"4. Für jeden Punkt begründen"},{"type":"T","value":"Erst wird x zu −x, danach zu 6 − (−x) = x + 6. Zwei Spiegelungen an diesen parallelen Achsen ergeben eine feste Verschiebung; zweimal an derselben Achse ergäbe dagegen den Anfangspunkt."},{"type":"M","value":"x\\longmapsto-x\\longmapsto6+x"}]},"source-0":{"title":"Denselben Punkt auf drei Arten abbilden","blocks":[{"type":"H","value":"Denselben Punkt auf drei Arten abbilden"},{"type":"T","value":"Wir starten bei P(2| 1). Bei der <b>Spiegelung</b> an der y-Achse bleibt die Höhe 1 erhalten, aber der Punkt liegt gleich weit links statt rechts: P′(−2| 1). Die Verbindung zwischen Punkt und Bildpunkt steht senkrecht auf der <b>Spiegelachse</b>; ihr Mittelpunkt liegt auf der Achse."},{"type":"V","value":"G04"},{"type":"T","value":"Bei der <b>Verschiebung</b> um 1 nach links und 2 nach oben ändern wir beide Koordinaten entsprechend. Jeder Punkt einer Figur wird um dieselbe Strecke in dieselbe Richtung bewegt."},{"type":"M","value":"(2|1)\\mapsto(2-1|1+2)=(1|3)"},{"type":"T","value":"Bei der <b>Drehung</b> um 90° gegen den Uhrzeigersinn um den Ursprung entsteht P″(−1| 2). Der Ursprung ist das <b>Drehzentrum</b>; der Abstand des Punktes zum Zentrum bleibt gleich. „90°“ reicht ohne Drehrichtung und Zentrum nicht als vollständige Angabe."},{"type":"M","value":"(x|y)\\mapsto(-y|x)\\quad\\mathrm{(90^\\circ\\ gegen\\ den\\ Uhrzeigersinn)}"},{"type":"T","value":"Alle drei Abbildungen erhalten Längen und Winkel. Eine Figur und ihr Bild sind daher kongruent, also deckungsgleich. Bei einer Spiegelung kehrt sich die Orientierung um; die Abstände der Punkte untereinander bleiben trotzdem erhalten."}],"prerequisites":["G01"]}},"taskExamples":{}},"G05":{"default":"transfer","variants":{"transfer":{"title":"Genau, höchstens und mindestens verändern die Lösungsmenge","prerequisites":["G03","N01"],"rationale":"Vergleicht Gleichheit und Ungleichheit als geometrische Bedingung, statt bloß einen Radius auszutauschen.","blocks":[{"type":"H","value":"1. „Genau“ als Linie auffassen"},{"type":"T","value":"Gesucht sind Punkte genau 2 cm von M entfernt. Nur die Kreislinie mit Radius 2 erfüllt diese Bedingung."},{"type":"M","value":"PM=2\\ \\mathrm{cm}"},{"type":"H","value":"2. „Höchstens“ ergänzen"},{"type":"T","value":"Bei höchstens 2 cm gehören auch alle inneren Punkte dazu, einschließlich M. Es entsteht die Kreisfläche samt Rand."},{"type":"M","value":"PM\\le2\\ \\mathrm{cm}"},{"type":"H","value":"3. Eine zweite Bedingung gleichzeitig verlangen"},{"type":"T","value":"Sollen die Punkte zusätzlich auf einer Geraden durch M liegen, bleiben bei „genau“ zwei Randpunkte. Bei „höchstens“ passt die ganze Strecke zwischen ihnen."},{"type":"H","value":"4. Die Wortwahl prüfen"},{"type":"T","value":"Ortslinienaufgaben hängen an der genauen Bedingung. Gleiche Entfernung ist nicht dasselbe wie höchstens diese Entfernung. Mehrere Bedingungen werden über den gemeinsamen Teil der Lösungsmengen verbunden."}]},"source-0":{"title":"Eine Bedingung beschreibt eine ganze Punktmenge","blocks":[{"type":"H","value":"Eine Bedingung beschreibt eine ganze Punktmenge"},{"type":"T","value":"Eine <b>Ortslinie</b> enthält genau alle Punkte mit einer bestimmten Eigenschaft. Alle Punkte mit Abstand 3 cm von M bilden einen <b>Kreis</b> mit Mittelpunkt M und <b>Radius</b> 3 cm. Punkte im Inneren haben kleineren Abstand und gehören nicht zur Kreislinie."},{"type":"V","value":"G05"},{"type":"T","value":"Alle Punkte mit gleichem Abstand zu A und B liegen auf der <b>Mittelsenkrechten</b> der Strecke AB. Sie geht durch deren Mittelpunkt und steht senkrecht auf AB. Im Bild ist PA = PB; P liegt deshalb auf dieser Geraden. Umgekehrt hat jeder Punkt der Mittelsenkrechten gleiche Abstände zu A und B."},{"type":"T","value":"Alle Punkte im Inneren eines Winkels mit gleichem Abstand zu seinen Schenkeln liegen auf der <b>Winkelhalbierenden</b>. Abstand zu einer Geraden wird immer senkrecht gemessen, nicht entlang einer beliebig schrägen Strecke. Die Winkelhalbierende teilt den Winkel in zwei gleich große Winkel."}],"prerequisites":["G01","G04"]},"source-1":{"title":"Zwei Bedingungen gleichzeitig erfüllen","blocks":[{"type":"H","value":"Zwei Bedingungen gleichzeitig erfüllen"},{"type":"T","value":"Gesucht ist ein Punkt mit PA = PB und PM = 3 cm. Wir zeichnen die Mittelsenkrechte von AB und den Kreis um M mit Radius 3 cm. Nur ihre Schnittpunkte erfüllen beide Bedingungen. Je nach Lage gibt es keinen, einen oder zwei Schnittpunkte; eine passende Skizze allein garantiert also noch keine Lösung."}],"prerequisites":["G01","G04"]}},"taskExamples":{}},"G06":{"default":"transfer","variants":{"transfer":{"title":"Ein Bauplan braucht die Lage einer angegebenen Seite","prerequisites":["G02","G01"],"rationale":"Vergleicht zwei WSW/WWS-Zuordnungen derselben Winkelwerte bei festem Seitenwert statt reine SSS-Zahlenvariation.","blocks":[{"type":"H","value":"1. Die Form erkennen"},{"type":"T","value":"Die Winkel eines Dreiecks sollen 30°, 60° und 90° sein. Diese Angaben legen die Form fest, aber noch keine Größe."},{"type":"H","value":"2. Die Länge eindeutig zuordnen"},{"type":"T","value":"Im ersten Bauplan soll die dem 30°-Winkel gegenüberliegende Seite 3 cm lang sein. Im zweiten soll die dem 90°-Winkel gegenüberliegende Seite 3 cm lang sein."},{"type":"H","value":"3. Die beiden Größen unterscheiden"},{"type":"T","value":"Die Seite gegenüber dem rechten Winkel ist die längste. Im ersten Plan muss sie daher länger als 3 cm sein; im zweiten ist gerade sie 3 cm. Die Dreiecke können nicht kongruent sein."},{"type":"H","value":"4. Den fehlenden Teil des Auftrags benennen"},{"type":"T","value":"„Zwei Winkel und eine Seite von 3 cm“ ist erst mit eindeutiger Zuordnung ein Bauplan. Danach liefern WSW bzw. der berechnete dritte Winkel eine eindeutige Form und Größe bis auf Kongruenz."}]},"source-0":{"title":"Ein Dreieck aus drei Seiten konstruieren","blocks":[{"type":"H","value":"Ein Dreieck aus drei Seiten konstruieren"},{"type":"T","value":"Gegeben sind AB = 6 cm, AC = 5 cm und BC = 4 cm. Wir zeichnen zuerst AB. C muss 5 cm von A und 4 cm von B entfernt sein. Deshalb zeichnen wir zwei Kreise; ein Schnittpunkt ist C. Anschließend verbinden wir C mit A und B."},{"type":"V","value":"G06"},{"type":"T","value":"Das ist <b>SSS</b>: Seite–Seite–Seite. Die beiden möglichen Lagen von C sind Spiegelbilder und <b>kongruent</b>, also deckungsgleich. Die Daten bestimmen daher die Form und Größe eindeutig, obwohl das Dreieck ober- oder unterhalb von AB liegen kann."}],"prerequisites":["G02","G05"]},"source-1":{"title":"Welche anderen Angaben sichern die Form?","blocks":[{"type":"H","value":"Welche anderen Angaben sichern die Form?"},{"type":"T","value":"<b>SWS</b> gibt zwei Seiten und den eingeschlossenen Winkel vor, etwa 5 cm, 60°, 4 cm. Man zeichnet den Winkel und trägt die Seiten auf seinen Schenkeln ab. <b>WSW</b> gibt eine Seite und ihre beiden anliegenden Winkel vor, etwa AB = 6 cm, α = 50°, β = 60°. Die Winkelschenkel schneiden sich in C."},{"type":"T","value":"Bei zwei Seiten und einem nicht eingeschlossenen Winkel kann es zwei verschiedene Formen geben. „Zwei Seiten und ein Winkel“ ist daher keine ausreichende Eindeutigkeitsbegründung."},{"type":"M","value":"2+3<6\\quad\\Longrightarrow\\quad\\mathrm{kein\\ Dreieck}"},{"type":"T","value":"Die <b>Dreiecksungleichung</b> verlangt: Die beiden kürzeren Seiten zusammen sind länger als die längste. Bei Gleichheit entsteht nur eine gestreckte Figur, kein Dreieck."}],"prerequisites":["G02","G05"]}},"taskExamples":{"G06_NEU_03":"source-0","G06_POOL_04":"source-0"}},"G07":{"default":"transfer","variants":{"transfer":{"title":"Eine Linie trifft die Seitenmitte und ist trotzdem keine Höhe","prerequisites":["G03","G02"],"rationale":"Nutzt ein bewusst schiefes Koordinatendreieck mit getrennten Fuß-/Mittelpunkten und Winkeltest.","blocks":[{"type":"H","value":"1. Die Grundseite festlegen"},{"type":"T","value":"A(0|0), B(10|0), C(3|4) bilden ein Dreieck. AB liegt waagerecht. Ihr Mittelpunkt ist M(5|0)."},{"type":"H","value":"2. Die Seitenhalbierende bauen"},{"type":"T","value":"Verbinde C mit M. Weil AM = MB = 5 gilt, ist CM die Seitenhalbierende von C."},{"type":"M","value":"M=(5|0),\\qquad AM=MB=5"},{"type":"H","value":"3. Die Höhe separat suchen"},{"type":"T","value":"Eine Senkrechte zur waagerechten Grundseite ist senkrecht nach unten gerichtet. Von C trifft sie H(3|0), also einen anderen Punkt als M."},{"type":"M","value":"H=(3|0)\\ne M"},{"type":"H","value":"4. Die Definitionen vergleichen"},{"type":"T","value":"CM halbiert die Gegenseite, CH steht senkrecht auf ihr. Keine dieser Eigenschaften ersetzt die andere. Nur in besonderen symmetrischen Dreiecken fallen beide Linien zusammen."}]},"source-0":{"title":"Vier Linien mit vier verschiedenen Aufträgen","blocks":[{"type":"H","value":"Vier Linien mit vier verschiedenen Aufträgen"},{"type":"V","value":"G07"},{"type":"T","value":"Die <b>Höhe</b> von C auf AB geht durch C und steht senkrecht auf der Geraden AB. Der rechte Winkel ist ihr Kennzeichen; der Fußpunkt muss nicht der Mittelpunkt sein. Bei einem stumpfwinkligen Dreieck kann er auf der Verlängerung der Seite liegen."},{"type":"T","value":"Die <b>Seitenhalbierende</b> verbindet C mit dem Mittelpunkt M von AB. Sie halbiert die Seite: AM = MB. Sie muss dabei nicht senkrecht auf AB stehen."},{"type":"T","value":"Die <b>Mittelsenkrechte</b> geht ebenfalls durch M und steht senkrecht auf AB. Sie muss aber nicht durch C gehen. Ihre Punkte haben gleiche Abstände zu A und B. Das Wort „Mitte“ bezieht sich auf die Seite, nicht auf einen Winkel."},{"type":"T","value":"Die <b>Winkelhalbierende</b> bei C teilt den Winkel ACB in zwei gleich große Winkel. Ihr Schnittpunkt mit AB muss weder der Mittelpunkt noch ein rechter Winkel sein. Sie wird deshalb an gleichen Winkelmarkierungen erkannt."}],"prerequisites":["G05","G06"]},"source-1":{"title":"Wann fallen Linien zusammen?","blocks":[{"type":"H","value":"Wann fallen Linien zusammen?"},{"type":"T","value":"In einem gleichschenkligen Dreieck mit CA = CB liegt C auf der Mittelsenkrechten von AB. Die Linie durch C und M ist dann zugleich Höhe, Seitenhalbierende, Mittelsenkrechte und Winkelhalbierende bei C. In einem beliebigen Dreieck gilt das nicht. Die vier Bilder verwenden bewusst dasselbe unsymmetrische Dreieck."}],"prerequisites":["G05","G06"]}},"taskExamples":{"G07_NEU_02":"source-1","G07_NEU_03":"source-1"}},"G08":{"default":"transfer","variants":{"transfer":{"title":"Eine Sehne ist noch kein Durchmesser","prerequisites":["G05","G02"],"rationale":"Kontrastiert Kreissehne und Durchmesser an einem gleichseitigen Gegenbeispiel, gefolgt von gezielter Reparatur.","blocks":[{"type":"H","value":"1. Ein Gegenbeispiel betrachten"},{"type":"T","value":"Ein gleichseitiges Dreieck lässt sich auf einen Kreis zeichnen. Seine drei Winkel sind jeweils 60°, also ist keiner recht."},{"type":"M","value":"60^\\circ+60^\\circ+60^\\circ=180^\\circ"},{"type":"H","value":"2. Die fehlende Voraussetzung finden"},{"type":"T","value":"Keine seiner Seiten ist ein Durchmesser dieses Kreises. Drei Kreispunkte allein genügen dem Satz des Thales daher nicht."},{"type":"H","value":"3. Die Konstruktion gezielt ändern"},{"type":"T","value":"Wähle A auf dem Kreis und B genau gegenüber, sodass AB durch den Mittelpunkt läuft. Wähle C irgendwo anders auf der Kreislinie. Jetzt ist AB ein Durchmesser."},{"type":"H","value":"4. Erst jetzt den Satz verwenden"},{"type":"T","value":"Nach Thales ist der Winkel bei C 90°. Wenn C wandert und die Endpunkte meidet, bleibt dieser Winkel gleich; die Winkel bei A und B können sich dagegen ändern."},{"type":"M","value":"\\angle ACB=90^\\circ"}]},"source-0":{"title":"Der Durchmesser ist die entscheidende Voraussetzung","blocks":[{"type":"H","value":"Der Durchmesser ist die entscheidende Voraussetzung"},{"type":"T","value":"AB ist der <b>Durchmesser</b> eines Kreises: Die Strecke geht durch den Mittelpunkt M, und A sowie B liegen auf dem Kreis. C ist ein anderer Punkt auf der Kreislinie. Nach dem <b>Satz des Thales</b> ist dann der Winkel ACB genau 90°."},{"type":"V","value":"G08"},{"type":"T","value":"Warum? MA, MB und MC sind Radien desselben Kreises, also gleich lang. Die Dreiecke AMC und BMC sind deshalb gleichschenklig. Ihre Basiswinkel sind jeweils gleich. Nennen wir die Winkel bei A und B α und β, dann setzt sich der Winkel bei C aus α + β zusammen."},{"type":"M","value":"\\alpha+\\beta+(\\alpha+\\beta)=180^\\circ\\quad\\Longrightarrow\\quad\\alpha+\\beta=90^\\circ"}],"prerequisites":["G02","G06"]},"source-1":{"title":"Die Umkehrung für eine Konstruktion nutzen","blocks":[{"type":"H","value":"Die Umkehrung für eine Konstruktion nutzen"},{"type":"T","value":"Hat ein Dreieck bei C einen rechten Winkel, liegt C auf dem Kreis über dem Durchmesser AB. Diese <b>Umkehrung</b> hilft, mögliche C-Punkte zu finden: Zeichne den Mittelpunkt von AB und den Kreis mit Radius AB/2. Jeder Kreispunkt außer A und B liefert einen rechten Winkel bei C."},{"type":"T","value":"C darf kein Endpunkt sein, sonst entsteht kein Dreieck. Und AB darf nicht irgendeine Sehne sein: Ohne die Durchmessereigenschaft folgt aus „C liegt auf einem Kreis“ noch kein rechter Winkel."}],"prerequisites":["G02","G06"]}},"taskExamples":{"G08_L4_04":"source-1","G08_POOL_01":"source-1","G08_NEU_03":"source-1"}},"G09":{"default":"transfer","variants":{"transfer":{"title":"Eine Fläche fehlt trotz sechs gezeichneter Quadrate","prerequisites":["G01"],"rationale":"Faltet zwei benachbarte obere Laschen auf dieselbe Würfelseite und repariert die Lage; keine neue Netzfläche-Rechnung.","blocks":[{"type":"H","value":"1. Vier Quadrate als Gürtel vorstellen"},{"type":"T","value":"Zeichne vier Quadrate A, B, C, D in einer Reihe. Beim Falten bilden sie die vier Seitenflächen eines Würfels; A liegt C gegenüber und B liegt D gegenüber."},{"type":"H","value":"2. Zwei Laschen auf derselben Seite prüfen"},{"type":"T","value":"Füge ein Quadrat oberhalb von B und eines oberhalb von C an. Beide klappen zur gleichen noch offenen Würfelseite. Sie würden sich überdecken."},{"type":"H","value":"3. Eine Lasche verlegen"},{"type":"T","value":"Setze die zweite Lasche unterhalb von C. Nun schließt sie die andere Öffnung. Die beiden Laschen liegen später gegenüber."},{"type":"H","value":"4. Die richtige Prüfidee festhalten"},{"type":"T","value":"Sechs zusammenhängende Quadrate genügen nicht. Jedes Quadrat muss beim Falten genau eine der sechs Körperseiten bedecken, ohne Überlappung und ohne offene Seite."}]},"source-0":{"title":"Einen Quader aufklappen und räumlich darstellen","blocks":[{"type":"H","value":"Einen Quader aufklappen und räumlich darstellen"},{"type":"T","value":"Ein Quader mit Kantenlängen 3 cm, 2 cm und 1 cm hat sechs Rechteckflächen: zweimal 3 × 2, zweimal 3 × 1 und zweimal 2 × 1. Ein <b>Netz</b> legt diese Flächen zusammenhängend in eine Ebene, sodass sie sich ohne Überlappung zum Körper falten lassen."},{"type":"V","value":"G09"},{"type":"T","value":"Im Netz bilden vier Seitenflächen den <b>Mantel</b>; die beiden gegenüberliegenden 3 × 2-Flächen sind Grund- und Deckfläche. Beim Falten müssen Kanten, die aufeinandertreffen, gleich lang sein. Sechs beliebig angeordnete Rechtecke ergeben deshalb noch kein passendes Netz."}],"prerequisites":["G01"]},"source-1":{"title":"Ein Schrägbild folgt einer Zeichenvereinbarung","blocks":[{"type":"H","value":"Ein Schrägbild folgt einer Zeichenvereinbarung"},{"type":"T","value":"Im <b>Schrägbild</b> ist die Vorderfläche unverzerrt gezeichnet. Wir zeichnen die <b>Tiefenkanten</b> hier unter 45° und halb so lang: Die wirkliche Tiefe 2 cm erscheint als 1 cm auf dem Papier. Parallele Kanten bleiben parallel; verdeckte Kanten sind gestrichelt."},{"type":"T","value":"Aus einer verkürzten Tiefenkante darfst du die wirkliche Länge nicht direkt mit dem Lineal ablesen. Nutze die Maßangabe oder die vereinbarte Verkürzung. Netz und Schrägbild zeigen denselben Körper, betonen aber verschiedene Informationen: Flächenanordnung bzw. räumliche Gestalt."}],"prerequisites":["G01"]}},"taskExamples":{"G09_H":"source-0","G09_TEST_02":"source-0","G09_POOL_02":"source-0"}},"G10":{"default":"transfer","variants":{"transfer":{"title":"Ein Gegenbeispiel genügt zum Widerlegen","prerequisites":["G01","G02"],"rationale":"Unterscheidet Beweisen und Widerlegen anhand quantifizierter Figurenaussage, statt gleiche Radien erneut einzusetzen.","blocks":[{"type":"H","value":"1. Die Behauptung genau lesen"},{"type":"T","value":"„Jedes Viereck mit zwei gleich langen Diagonalen ist ein Rechteck.“ Das Wort „jedes“ behauptet die Aussage für alle solchen Vierecke."},{"type":"H","value":"2. Eine passende Gegenfigur wählen"},{"type":"T","value":"Ein gleichschenkliges Trapez mit verschieden langen parallelen Seiten besitzt gleich lange Diagonalen, aber keine vier rechten Winkel. Zum Beispiel A(−3|0), B(3|0), C(2|2), D(−2|2)."},{"type":"H","value":"3. Beide Bedingungen prüfen"},{"type":"T","value":"Die Spiegelung an der y-Achse vertauscht AC und BD, also sind die Diagonalen gleich lang. AB und CD sind unterschiedlich lang; die schrägen Schenkel stehen nicht senkrecht auf AB."},{"type":"H","value":"4. Die Reichweite erklären"},{"type":"T","value":"Dieses eine gültige Gegenbeispiel widerlegt die allgemeine Behauptung. Zehn passende Rechtecke hätten die Behauptung dagegen nicht allgemein bewiesen. Für ein Parallelogramm wäre eine zusätzliche Voraussetzung vorhanden."}]},"source-0":{"title":"Warum die Zirkelkonstruktion die Mitte trifft","blocks":[{"type":"H","value":"Warum die Zirkelkonstruktion die Mitte trifft"},{"type":"T","value":"Wir zeichnen um A und B Kreise mit demselben Radius r, der größer als AB/2 ist. Die beiden Schnittpunkte heißen P und Q. Verbinden wir P und Q, erhalten wir die Mittelsenkrechte von AB. Das lässt sich begründen, ohne die Zeichnung auszumessen."},{"type":"V","value":"G10"},{"type":"T","value":"P liegt auf beiden Kreisen. Daher ist PA = r und PB = r, also PA = PB. Genau solche Punkte liegen auf der <b>Mittelsenkrechten</b> von AB. Für Q gilt aus demselben Grund QA = QB; auch Q liegt auf dieser Mittelsenkrechten."},{"type":"M","value":"PA=PB=r\\qquad QA=QB=r"},{"type":"T","value":"Durch zwei verschiedene Punkte geht genau eine Gerade. Die Gerade PQ ist deshalb die Mittelsenkrechte: Sie halbiert AB und steht senkrecht darauf. Der gemeinsame Radius ist entscheidend; bei verschiedenen Radien folgt PA = PB nicht."}],"prerequisites":["G05","G06","G07"]},"source-1":{"title":"Entdecken und begründen sind verschiedene Schritte","blocks":[{"type":"H","value":"Entdecken und begründen sind verschiedene Schritte"},{"type":"T","value":"„Im Bild sieht PQ senkrecht aus“ ist eine <b>Vermutung</b>. Auch Nachmessen kann sie nur für diese Zeichnung stützen. Die <b>Begründung</b> verknüpft dagegen die Kreisradien mit einer bekannten Ortslinieneigenschaft und gilt für jede korrekte Konstruktion. Ein solcher allgemeingültiger Gedankengang ist ein <b>Beweis</b>."}],"prerequisites":["G05","G06","G07"]}},"taskExamples":{}},"M01":{"default":"transfer","variants":{"transfer":{"title":"Eine Dezimalstunde ist kein Uhrzeitformat","prerequisites":["D02","B08"],"rationale":"Kontrastiert 1,40h und1h40min und rechnet die beiden Schreibweisen rückwärts in gemeinsame Einheiten.","blocks":[{"type":"H","value":"1. Zwei Angaben auseinanderhalten"},{"type":"T","value":"Auf zwei Trainingsplänen stehen „1,40 h“ und „1 h 40 min“. Die Schreibweisen sehen ähnlich aus, verwenden aber unterschiedliche Zahlensysteme."},{"type":"H","value":"2. Den Dezimalanteil umrechnen"},{"type":"T","value":"0,40 Stunden sind 40 Hundertstel von 60 Minuten, also 24 Minuten."},{"type":"M","value":"1{,}40\\ \\mathrm h=1\\ \\mathrm h+0{,}40\\cdot60\\ \\mathrm{min}=84\\ \\mathrm{min}"},{"type":"H","value":"3. Die gemischte Angabe umrechnen"},{"type":"T","value":"Eine Stunde plus 40 Minuten ergibt 100 Minuten. In Dezimalstunden sind das 5/3 Stunden, nicht 1,40."},{"type":"M","value":"60+40=100,\\qquad\\frac{100}{60}=\\frac53"},{"type":"H","value":"4. Den Unterschied prüfen"},{"type":"T","value":"Die zweite Trainingszeit ist 16 Minuten länger. Bei Zeit entscheidet die Einheit, ob eine Nachkommastelle einen Stundenanteil oder eine separate Minutenangabe meint."},{"type":"M","value":"100-84=16\\ \\mathrm{min}"}]},"source-0":{"title":"Die Größe bleibt, die Einheit wechselt","blocks":[{"type":"H","value":"Die Größe bleibt, die Einheit wechselt"},{"type":"T","value":"Eine <b>Größenangabe</b> besteht aus Zahl und Einheit. 1,5 m und 150 cm beschreiben dieselbe Länge. Die kleinere Einheit wird häufiger benötigt; deshalb wird die Maßzahl größer. Vor dem Rechnen schreiben wir die Beziehung der Einheiten auf."},{"type":"M","value":"1\\,\\mathrm m=100\\,\\mathrm{cm}\\quad\\Longrightarrow\\quad1{,}5\\,\\mathrm m=150\\,\\mathrm{cm}"},{"type":"M","value":"1\\,\\mathrm{kg}=1000\\,\\mathrm g\\quad\\Longrightarrow\\quad750\\,\\mathrm g=0{,}75\\,\\mathrm{kg}"},{"type":"T","value":"Bei Geld entsprechen 100 Cent einem Euro: 235 Cent = 2,35 Euro. Beim Addieren müssen die Einheiten zusammenpassen. 1,5 m + 40 cm wird deshalb zuerst zu 150 cm + 40 cm = 190 cm."}],"prerequisites":["D01","D02"]},"source-1":{"title":"Zeit verwendet andere Faktoren","blocks":[{"type":"H","value":"Zeit verwendet andere Faktoren"},{"type":"M","value":"1\\,\\mathrm h=60\\,\\mathrm{min}\\qquad1{,}5\\,\\mathrm h=60\\,\\mathrm{min}+30\\,\\mathrm{min}=90\\,\\mathrm{min}"},{"type":"T","value":"Eine halbe Stunde hat 30 Minuten, nicht 50. Rückwärts teilen wir 90 durch 60 und erhalten 1,5 Stunden. Die Schreibweise 1 h 30 min ist eine zusammengesetzte Zeitangabe; 1,30 h bedeutet dagegen 1 h plus 0,30 h, also 1 h 18 min."},{"type":"T","value":"Für eine Fahrt von 14:45 bis 16:10 zählen wir zunächst 15 Minuten bis 15:00, dann 60 Minuten bis 16:00 und 10 Minuten bis 16:10. Insgesamt sind es 85 Minuten. Eine Uhrzeit und eine Zeitdauer sind verschiedene Größenangaben."}],"prerequisites":["D01","D02"]}},"taskExamples":{}},"M02":{"default":"transfer","variants":{"transfer":{"title":"Eine Literflasche hat zugleich ein Kubikvolumen","prerequisites":["M01","M04"],"rationale":"Leitet Literrelation aus einem 10-cm-Würfel und einer anderen gleichvolumigen Form her.","blocks":[{"type":"H","value":"1. Einen Einheitskörper aufbauen"},{"type":"T","value":"Ein Würfel mit Kanten 10 cm hat Volumen 1000 cm³. Seine Kanten sind zugleich jeweils 1 dm."},{"type":"M","value":"10\\cdot10\\cdot10=1000\\ \\mathrm{cm}^3=1\\ \\mathrm{dm}^3"},{"type":"H","value":"2. Den Liternamen zuordnen"},{"type":"T","value":"1 dm³ wird auch 1 Liter genannt. Darum entsprechen 1000 cm³ einem Liter und 1 cm³ einem Milliliter."},{"type":"M","value":"1\\ \\mathrm l=1\\ \\mathrm{dm}^3=1000\\ \\mathrm{cm}^3"},{"type":"H","value":"3. Eine andere Form vergleichen"},{"type":"T","value":"Ein quaderförmiger Behälter mit Innenmaßen 20 × 10 × 5 cm hat ebenfalls 1000 cm³. Die Form darf anders sein, das Fassungsvermögen bleibt ein Liter."},{"type":"M","value":"20\\cdot10\\cdot5=1000"},{"type":"H","value":"4. Größen nicht verwechseln"},{"type":"T","value":"Die Literangabe beschreibt Volumen. Eine Bodenfläche von 100 cm² reicht ohne Höhe nicht aus, um das Fassungsvermögen zu bestimmen."}]},"source-0":{"title":"Warum aus zehn hundert oder tausend wird","blocks":[{"type":"H","value":"Warum aus zehn hundert oder tausend wird"},{"type":"T","value":"1 dm sind 10 cm. Ein Quadrat mit Seite 1 dm besteht daher aus 10 Reihen mit je 10 Quadraten der Größe 1 cm². Der Längenfaktor wirkt in zwei Richtungen. Deshalb enthält 1 dm² genau 100 cm²."},{"type":"V","value":"M02"},{"type":"M","value":"1\\,\\mathrm{dm}^2=10\\cdot10\\,\\mathrm{cm}^2=100\\,\\mathrm{cm}^2"},{"type":"T","value":"Ein Würfel mit Kantenlänge 1 dm hat 10 solche Schichten. Für das <b>Volumen</b> wirkt der Faktor in drei Richtungen: 10 · 10 · 10 = 1000. Ein Kubikdezimeter heißt auch ein <b>Liter</b>."},{"type":"M","value":"1\\,\\mathrm{dm}^3=1000\\,\\mathrm{cm}^3=1\\,\\mathrm l\\qquad1\\,\\mathrm{cm}^3=1\\,\\mathrm{ml}"},{"type":"T","value":"So wird aus 2,5 dm² die Fläche 250 cm², aus 2,5 dm³ aber das Volumen 2500 cm³. Die gleiche Maßzahl führt wegen der verschiedenen Dimensionen zu verschiedenen Umrechnungsfaktoren."},{"type":"M","value":"750\\,\\mathrm{cm}^3=0{,}75\\,\\mathrm{dm}^3=0{,}75\\,\\mathrm l"},{"type":"T","value":"Rückwärts teilen wir durch 1000, weil die größere Volumeneinheit weniger oft in die Menge passt. cm² und cm³ darf man nicht ineinander umrechnen: Das eine misst Fläche, das andere Raum."}],"prerequisites":["M01"]}},"taskExamples":{"M02_NEU_04":"source-0"}},"M03":{"default":"transfer","variants":{"transfer":{"title":"Ein Innenloch verändert Rand und Fläche verschieden","prerequisites":["N02","M01"],"rationale":"Kontrastiert äußeren Rand, Innenrand und Restfläche statt bloßer Rechteckfläche mit neuem Lochmaß.","blocks":[{"type":"H","value":"1. Außenfläche und Rand berechnen"},{"type":"T","value":"Eine rechteckige Platte ist 9 cm lang und 6 cm breit. Ihre Fläche beträgt 54 cm², der äußere Rand 30 cm."},{"type":"M","value":"A=9\\cdot6=54,\\qquad U=2(9+6)=30"},{"type":"H","value":"2. Ein inneres Fenster ausschneiden"},{"type":"T","value":"Ein vollständig innen liegendes 3 × 2-cm-Fenster entfernt 6 cm². Die verbleibende Materialfläche ist 48 cm²."},{"type":"M","value":"A_{\\mathrm{Rest}}=54-3\\cdot2=48"},{"type":"H","value":"3. Alle Materialränder zählen"},{"type":"T","value":"Der äußere Rand bleibt 30 cm. Zusätzlich entsteht der Innenrand 2(3 + 2) = 10 cm. Soll jeder Rand versiegelt werden, sind insgesamt 40 cm nötig."},{"type":"M","value":"U_{\\mathrm{alle\\ Ränder}}=30+10=40"},{"type":"H","value":"4. Die Frage entscheidet"},{"type":"T","value":"Die Fläche nimmt ab, während die Länge aller Ränder zunimmt. „Umfang“ muss hier klar sagen, ob nur die äußere Begrenzung oder alle Ränder gemeint sind."}]},"source-0":{"title":"Eine L-Form ergänzen statt raten","blocks":[{"type":"H","value":"Eine L-Form ergänzen statt raten"},{"type":"T","value":"Die Figur entsteht aus einem Rechteck 6 cm × 4 cm, aus dem rechts oben ein Rechteck 2 cm × 1 cm herausgeschnitten wird. Der <b>Flächeninhalt</b> misst die bedeckte Ebene. Deshalb dürfen wir den Inhalt des ausgeschnittenen Rechtecks vom ganzen abziehen."},{"type":"V","value":"M03"},{"type":"M","value":"A=6\\cdot4-2\\cdot1=22\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Der <b>Umfang</b> misst dagegen die Randlänge. Wir laufen den Rand ab. Die fehlenden Teilseiten sind 4 − 1 = 3 cm und 6 − 2 = 4 cm. Auch die beiden Kanten der Einbuchtung gehören zum Rand."},{"type":"M","value":"U=6+3+2+1+4+4=20\\quad\\mathrm{(cm)}"},{"type":"T","value":"Flächen werden in Quadrateinheiten angegeben, Umfänge in Längeneinheiten. Bei dieser Eck-Aussparung bleibt der Umfang wegen der Lage des Ausschnitts gleich wie beim äußeren Rechteck: Zwei Randstücke werden durch gleich lange innen ersetzt. Der Flächeninhalt wird trotzdem kleiner."}],"prerequisites":["N02","M02"]},"source-1":{"title":"Eine Seitenlänge rückwärts berechnen","blocks":[{"type":"H","value":"Eine Seitenlänge rückwärts berechnen"},{"type":"T","value":"Ein anderes Rechteck hat Fläche 24 cm² und Breite 4 cm. Fläche ist Länge mal Breite. Wir teilen deshalb durch die bekannte Breite, um die Länge zu erhalten."},{"type":"M","value":"a=24:4=6\\quad\\mathrm{(cm)}\\qquad U=2(6+4)=20\\quad\\mathrm{(cm)}"}],"prerequisites":["N02","M02"]}},"taskExamples":{}},"M04":{"default":"transfer","variants":{"transfer":{"title":"Ein voller Quader kann mehr Oberfläche bekommen","prerequisites":["M03","M02"],"rationale":"Zerschneidet Körper ohne Volumenverlust und analysiert neue Schnittflächen; kein einfaches V/O-Ausrechnen mit Zahlenwechsel.","blocks":[{"type":"H","value":"1. Den Ausgangskörper berechnen"},{"type":"T","value":"Ein Quader misst 6 × 4 × 2 cm. Sein Volumen ist 48 cm³, seine Oberfläche 88 cm²."},{"type":"M","value":"V=6\\cdot4\\cdot2=48,\\qquad O=2(24+12+8)=88"},{"type":"H","value":"2. Mittig zerschneiden"},{"type":"T","value":"Schneide senkrecht zur 6-cm-Kante in zwei Quader 3 × 4 × 2 cm. Ohne Materialverlust bleibt das Gesamtvolumen gleich."},{"type":"M","value":"2\\cdot(3\\cdot4\\cdot2)=48"},{"type":"H","value":"3. Neue Flächen mitzählen"},{"type":"T","value":"An der Schnittstelle entstehen zwei zusätzliche Rechtecke von je 4 × 2 = 8 cm². Nach dem Trennen ist die Gesamtoberfläche daher 16 cm² größer."},{"type":"M","value":"O_{\\mathrm{getrennt}}=88+2\\cdot8=104"},{"type":"H","value":"4. Den Grund erklären"},{"type":"T","value":"Volumen misst das vorhandene Material im Raum. Oberfläche misst die nun freien Begrenzungsflächen. Zerteilen kann die Oberfläche verändern, ohne das Volumen zu verändern."}]},"source-0":{"title":"Füllen und Einpacken sind zwei verschiedene Fragen","blocks":[{"type":"H","value":"Füllen und Einpacken sind zwei verschiedene Fragen"},{"type":"T","value":"Ein Quader ist 4 cm lang, 3 cm breit und 2 cm hoch. Seine <b>Grundfläche</b> hat 4 · 3 = 12 cm². Zwei Schichten von je 1 cm Höhe ergeben das <b>Volumen</b>, also den Rauminhalt."},{"type":"M","value":"V=4\\cdot3\\cdot2=24\\quad\\mathrm{(cm^3)}"},{"type":"V","value":"M04"},{"type":"T","value":"Die <b>Oberfläche</b> enthält dagegen alle sechs äußeren Rechtecke. Gegenüberliegende Flächen sind gleich groß: zweimal 12 cm², zweimal 8 cm² und zweimal 6 cm². Deshalb steht in der Formel ein Faktor 2 vor der Summe."},{"type":"M","value":"O=2(4\\cdot3+4\\cdot2+3\\cdot2)=2(12+8+6)=52\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Bei einem oben offenen Behälter fehlt die Deckfläche 4 · 3 = 12 cm². Die Bodenfläche bleibt vorhanden. Wir ziehen daher nur einmal 12 cm² ab."},{"type":"M","value":"O_{\\mathrm{offen}}=52-12=40\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Die Innenmaße bestimmen das Fassungsvermögen; Materialdicke wird in diesem Modell vernachlässigt. Ein Ergebnis in cm² beantwortet keine Volumenfrage. Prüfe deshalb vor dem Rechnen, ob Füllmenge oder benötigte Fläche gesucht ist."}],"prerequisites":["M02","M03"]}},"taskExamples":{}},"M05":{"default":"transfer","variants":{"transfer":{"title":"Schieben verändert die Dreiecksfläche nicht","prerequisites":["G07","M03"],"rationale":"Scheren eines Dreiecks mit gleicher Höhe, inklusive Höhenfuß außerhalb, kontrastiert Form und Flächeninhalt.","blocks":[{"type":"H","value":"1. Grundseite und Höhe wählen"},{"type":"T","value":"AB ist 6 cm lang. Die Spitze C liegt auf einer Geraden parallel zu AB im senkrechten Abstand 4 cm."},{"type":"H","value":"2. Die Fläche unabhängig von der Spitze rechnen"},{"type":"T","value":"Jede Lage von C auf dieser Parallelen hat dieselbe Grundseite und dieselbe Höhe."},{"type":"M","value":"A=\\frac{6\\cdot4}{2}=12\\ \\mathrm{cm}^2"},{"type":"H","value":"3. Die Spitze über ein Ende hinausschieben"},{"type":"T","value":"Liegt C weit rechts von B, fällt die Höhe auf die Verlängerung von AB. Sie ist weiterhin 4 cm lang; die schräge Seite darf nicht als Höhe eingesetzt werden."},{"type":"H","value":"4. Form und Flächeninhalt unterscheiden"},{"type":"T","value":"Die Seitenlängen und Winkel ändern sich beim Verschieben, der Flächeninhalt nicht. Ein schmal aussehendes schiefes Dreieck kann dieselbe Fläche wie ein symmetrisches haben."}]},"source-0":{"title":"Die Höhe steht senkrecht auf der Grundseite","blocks":[{"type":"H","value":"Die Höhe steht senkrecht auf der Grundseite"},{"type":"V","value":"M05"},{"type":"T","value":"Beim <b>Parallelogramm</b> können wir ein Randdreieck abschneiden und auf der anderen Seite anfügen. So entsteht ein gleich großes Rechteck. Die schräge Seitenlänge wird nicht zur Höhe; entscheidend ist der senkrechte Abstand der parallelen Seiten."},{"type":"M","value":"A_P=g\\cdot h=6\\cdot3=18\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Zwei kongruente <b>Dreiecke</b> bilden ein Parallelogramm mit derselben Grundseite und Höhe. Ein Dreieck besitzt deshalb nur dessen halben Flächeninhalt."},{"type":"M","value":"A_D=\\frac{g\\cdot h}{2}=\\frac{6\\cdot3}{2}=9\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Beim <b>Trapez</b> sind a und c die parallelen Seiten. Zwei passende Kopien bilden ein Parallelogramm mit Grundseite a + c und derselben Höhe h. Deshalb teilen wir dessen Fläche durch 2."},{"type":"M","value":"A_T=\\frac{(a+c)h}{2}=\\frac{(6+2)\\cdot3}{2}=12\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Die Höhe gehört immer zur gewählten Grundseite bzw. zum parallelen Seitenpaar. In allen drei Bildern beträgt sie 3 cm; sie wird mit einem rechten Winkel markiert. Beim Trapez darfst du nicht zwei beliebige Seiten in a + c einsetzen."}],"prerequisites":["M03","G07"]}},"taskExamples":{}},"M06":{"default":"transfer","variants":{"transfer":{"title":"Mehr Höhe verdoppelt nicht automatisch die Oberfläche","prerequisites":["M05","F02"],"rationale":"Stellt V(h) undO(h) gegenüber und deutet konstanten Flächenanteil; verbindet Geometrie mit Proportionalität.","blocks":[{"type":"H","value":"1. Die Grundfigur festhalten"},{"type":"T","value":"Ein gerades Prisma hat Grundfläche G = 9 cm² und Grundumfang u = 14 cm. Nur seine Körperhöhe h soll verändert werden."},{"type":"H","value":"2. Das Volumen als Regel schreiben"},{"type":"T","value":"Jede weitere Höheneinheit fügt dieselbe Grundflächenschicht hinzu. Daher ist V proportional zu h."},{"type":"M","value":"V(h)=9h,\\qquad V(2)=18,\\quad V(4)=36"},{"type":"H","value":"3. Die Oberfläche als Regel schreiben"},{"type":"T","value":"Grund- und Deckfläche bleiben zusammen 18 cm². Nur der Mantel wächst mit h."},{"type":"M","value":"O(h)=18+14h,\\qquad O(2)=46,\\quad O(4)=74"},{"type":"H","value":"4. Den Unterschied begründen"},{"type":"T","value":"Verdoppelte Höhe verdoppelt das Volumen, aber nicht die Oberfläche: 74 ist nicht 92. Ein fester Anteil verhindert hier die Proportionalität."}]},"source-0":{"title":"Ein Dreieck als Grundfläche, viele gleiche Schichten","blocks":[{"type":"H","value":"Ein Dreieck als Grundfläche, viele gleiche Schichten"},{"type":"T","value":"Ein gerades Prisma hat ein rechtwinkliges Grunddreieck mit Seiten 3 cm, 4 cm, 5 cm. Die <b>Körperhöhe h</b> beträgt 10 cm. Die Grundfläche steht senkrecht zu den Seitenkanten; jede parallele Schicht hat denselben Inhalt G."},{"type":"M","value":"G=\\frac{3\\cdot4}{2}=6\\quad\\mathrm{(cm^2)}\\qquad V=Gh=6\\cdot10=60\\quad\\mathrm{(cm^3)}"},{"type":"V","value":"M06"},{"type":"T","value":"Der <b>Mantel</b> besteht aus drei Rechtecken mit Höhe 10 cm und Breiten 3, 4 und 5 cm. Aufgeklappt ergeben sie ein Rechteck mit Breite gleich dem <b>Grundumfang u</b>. Deshalb ist der Mantelinhalt u · h."},{"type":"M","value":"u=3+4+5=12\\quad\\mathrm{(cm)}\\qquad M=12\\cdot10=120\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Für die <b>Oberfläche</b> kommen zwei Dreiecke hinzu: Grund- und Deckfläche. Die Körperhöhe 10 cm ist nicht die Dreieckshöhe 4 cm; beide haben verschiedene Aufgaben."},{"type":"M","value":"O=2G+M=2\\cdot6+120=132\\quad\\mathrm{(cm^2)}"},{"type":"T","value":"Das Netz erklärt die Formel: zwei Grundflächen plus Mantel. Die Formel M = uh gilt so für gerade Prismen; die geometrischen Voraussetzungen gehören zur Rechnung."}],"prerequisites":["M04","M05","G09"]}},"taskExamples":{}},"M07":{"default":"transfer","variants":{"transfer":{"title":"Eine Kopie verändert den Maßstab, nicht das Gebäude","prerequisites":["D02","M03"],"rationale":"Vergleicht Originalplan und Verkleinerung mit wiederholter Realitätsprobe; trennt lineare und Flächenfaktoren.","blocks":[{"type":"H","value":"1. Den Originalplan lesen"},{"type":"T","value":"Eine Wand ist im Maßstab 1 : 80 genau 5 cm lang. Wirklich sind das 400 cm, also 4 m."},{"type":"M","value":"5\\cdot80=400\\ \\mathrm{cm}"},{"type":"H","value":"2. Den Plan auf 50 % kopieren"},{"type":"T","value":"Die gezeichnete Wand wird 2,5 cm lang. Das echte Gebäude bleibt unverändert 400 cm lang."},{"type":"H","value":"3. Den neuen Maßstab bestimmen"},{"type":"T","value":"Vergleiche die neuen 2,5 cm mit den wirklichen 400 cm. Ein Zentimeter der Kopie steht für 160 cm."},{"type":"M","value":"2{,}5:400=1:160"},{"type":"H","value":"4. Den Flächenfaktor getrennt prüfen"},{"type":"T","value":"Papierflächen werden in zwei Richtungen halbiert, also auf ein Viertel verkleinert. Die wirkliche Gebäudefläche ändert sich durch Kopieren überhaupt nicht."},{"type":"M","value":"\\left(\\frac12\\right)^2=\\frac14"}]},"source-0":{"title":"Plan und Wirklichkeit in derselben Einheit vergleichen","blocks":[{"type":"H","value":"Plan und Wirklichkeit in derselben Einheit vergleichen"},{"type":"T","value":"Der <b>Maßstab</b> 1 : 100 bedeutet: 1 cm im Plan entspricht 100 cm in Wirklichkeit. Ein Zimmer misst im Plan 4 cm × 3 cm. Jede wirkliche Länge ist hundertmal so groß; danach rechnen wir Zentimeter in Meter um."},{"type":"M","value":"4\\,\\mathrm{cm}\\cdot100=400\\,\\mathrm{cm}=4\\,\\mathrm m\\qquad3\\,\\mathrm{cm}\\cdot100=300\\,\\mathrm{cm}=3\\,\\mathrm m"},{"type":"V","value":"M07"},{"type":"T","value":"Rückwärts zeichnen wir eine 80 cm breite Tür als 80 : 100 = 0,8 cm. Division macht die Vergrößerung der Planlänge rückgängig. Vor dem Vergleichen brauchen beide Längen dieselbe Einheit; 4 cm zu 4 m ist deshalb 1 : 100 und nicht 1 : 1."}],"prerequisites":["B08","M01","F01"]},"source-1":{"title":"Fläche wächst in zwei Richtungen","blocks":[{"type":"H","value":"Fläche wächst in zwei Richtungen"},{"type":"M","value":"A_{\\mathrm{Plan}}=4\\cdot3=12\\quad\\mathrm{(cm^2)}"},{"type":"M","value":"A_{\\mathrm{wirklich}}=400\\cdot300=120\\,000\\,\\mathrm{cm}^2=12\\,\\mathrm m^2"},{"type":"T","value":"Der <b>Längenfaktor</b> ist 100, der <b>Flächenfaktor</b> ist 100² = 10 000. Beide Seiten eines Flächenstücks werden vergrößert, deshalb wirkt der Faktor zweimal. Den Flächeninhalt nur mit 100 zu multiplizieren wäre zu wenig."}],"prerequisites":["B08","M01","F01"]}},"taskExamples":{"M07_NEU_06":"source-0","M07_POOL_04":"source-0"}},"M08":{"default":"transfer","variants":{"transfer":{"title":"Ein Schätzbereich ist ehrlicher als eine scheinbar genaue Zahl","prerequisites":["D02","M03"],"rationale":"Verarbeitet Unsicherheit beider Längen zu Unter-/Obergrenze statt einer Einzelgrößenordnung.","blocks":[{"type":"H","value":"1. Unsichere Maße nennen"},{"type":"T","value":"Ein Raum wird auf 7 bis 8 m Länge und 5 bis 6 m Breite geschätzt. Die Bandbreiten beschreiben die Unsicherheit der Vergleichsgrößen."},{"type":"H","value":"2. Eine untere Grenze rechnen"},{"type":"T","value":"Bei beiden kleinsten Werten ergibt sich 35 m². Für positive Seiten wird das Produkt mit größeren Seiten ebenfalls größer."},{"type":"M","value":"A_{\\min}=7\\cdot5=35\\ \\mathrm{m}^2"},{"type":"H","value":"3. Eine obere Grenze rechnen"},{"type":"T","value":"Bei beiden größten Werten ergibt sich 48 m². Die tatsächliche Fläche liegt unter den genannten Annahmen zwischen beiden Grenzen."},{"type":"M","value":"A_{\\max}=8\\cdot6=48\\ \\mathrm{m}^2"},{"type":"H","value":"4. Die Aussage passend nutzen"},{"type":"T","value":"„Etwa 35 bis 48 m²“ macht die Unsicherheit sichtbar. Für einen verbindlichen Materialkauf wären genauere Messungen und gegebenenfalls Verschnitt sinnvoll; eine Zahl mit vielen Nachkommastellen ersetzt die fehlende Genauigkeit nicht."}]},"source-0":{"title":"Passt das Wasser in das Aquarium?","blocks":[{"type":"H","value":"Passt das Wasser in das Aquarium?"},{"type":"T","value":"Ein Aquarium hat ungefähr 60 cm Länge, 30 cm Breite und 40 cm Füllhöhe. Zum <b>Schätzen</b> nutzen wir ein Quader-Modell. Die Kanten sind bereits gerundete Maße; Materialdicke und Einrichtung werden zunächst vernachlässigt."},{"type":"M","value":"V\\approx60\\cdot30\\cdot40=72\\,000\\quad\\mathrm{(cm^3)}"},{"type":"M","value":"72\\,000\\,\\mathrm{cm}^3=72\\,\\mathrm l"},{"type":"T","value":"Die <b>Größenordnung</b> sind also einige Zehn Liter. 72 000 Liter wären für ein kleines Aquarium unplausibel: Die Zahl aus der Rechnung gehört zunächst zu Kubikzentimetern. Die Umrechnung ist Teil der Lösung, kein nachträgliches Etikett."},{"type":"V","value":"M08"},{"type":"T","value":"Ein 10-Liter-Eimer ist eine hilfreiche <b>Vergleichsgröße</b>: Etwa sieben volle Eimer passen zum Modell. Kies und Dekoration verdrängen Wasser, deshalb wird die tatsächliche Wassermenge geringer ausfallen."}],"prerequisites":["M01","M02"]},"source-1":{"title":"Schätzen heißt Annahmen sichtbar machen","blocks":[{"type":"H","value":"Schätzen heißt Annahmen sichtbar machen"},{"type":"T","value":"Für ein Klassenzimmer schätzen wir 8 m Länge und 6 m Breite, also etwa 48 m² Bodenfläche. „48 cm²“ würde kaum eine Handfläche bedecken und passt nicht. Eine gute Schätzung nennt Vergleichsgrößen, Rechenmodell und sinnvolle Einheit. Sie verspricht keine Genauigkeit, die die geschätzten Angaben nicht besitzen."}],"prerequisites":["M01","M02"]}},"taskExamples":{}},"S01":{"default":"transfer","variants":{"transfer":{"title":"Eine große Stichprobe kann systematisch einseitig sein","prerequisites":["S02","N01"],"rationale":"Vergleicht zwei Auswahlmechanismen und Nichtantworten statt nur eine weitere neutrale Frage zu formulieren.","blocks":[{"type":"H","value":"1. Die Zielgruppe bestimmen"},{"type":"T","value":"Eine Schule will die Zufriedenheit aller Lernenden mit dem Mittagessen erfassen, einschließlich derjenigen, die die Mensa nicht nutzen."},{"type":"H","value":"2. Die spontane Befragung prüfen"},{"type":"T","value":"500 Antworten aus der Mensaschlange enthalten fast nur aktuelle Nutzende. Viele Antworten machen die fehlenden Nichtnutzenden nicht automatisch sichtbar."},{"type":"H","value":"3. Eine passendere Auswahl planen"},{"type":"T","value":"Ziehe zufällig aus vollständigen Klassenlisten, verteilt nach Jahrgangsanteilen. Frage neutral nach Nutzung und Zufriedenheit; Nichtnutzende erhalten eine passende Antwortmöglichkeit."},{"type":"H","value":"4. Nichtantworten offenlegen"},{"type":"T","value":"Berichte Einladungszahl, gültige Antworten und Auswahlweg. Auch eine zufällige Einladung kann durch unterschiedliche Antwortbereitschaft verzerrt werden. Die Antwortzahl allein ist kein Gütesiegel."}]},"source-0":{"title":"Eine Frage so planen, dass die Antwort etwas bedeutet","blocks":[{"type":"H","value":"Eine Frage so planen, dass die Antwort etwas bedeutet"},{"type":"T","value":"Wir wollen wissen, wie die Schülerinnen und Schüler der Schule zur Schule kommen. Die <b>Zielgruppe</b> sind alle Lernenden dieser Schule. Eine neutrale Frage lautet: „Welches Verkehrsmittel hast du heute für den längsten Teil deines Schulwegs benutzt?“ Das legt Zeitraum und Zuordnung eindeutig fest."},{"type":"T","value":"„Fährst du auch umweltfreundlich mit dem Rad?“ ist nicht <b>neutral</b>: Die Formulierung bewertet eine Antwort. Außerdem lässt sie keine gleichwertigen anderen Möglichkeiten zu. Wir bieten Fahrrad, zu Fuß, Bus/Bahn, Auto und Sonstiges als getrennte Kategorien an."},{"type":"V","value":"S01"},{"type":"T","value":"Nicht alle können befragt werden. Wir ziehen eine <b>Stichprobe</b>, also eine Teilgruppe, zum Beispiel zufällig ausgewählte Lernende aus jeder Jahrgangsstufe. Nur am Fahrradständer zu fragen würde Radfahrende bevorzugen. Diese systematische Schieflage heißt <b>Verzerrung</b>."}],"prerequisites":[]},"source-1":{"title":"Was darf man aus den Daten schließen?","blocks":[{"type":"H","value":"Was darf man aus den Daten schließen?"},{"type":"T","value":"Eine große, einseitig ausgewählte Stichprobe bleibt einseitig. Wir dokumentieren daher Frage, Auswahl, Datum und Zahl der Antworten. Bei der Auswertung schreiben wir zunächst „in unserer Stichprobe“. Ein Regentag kann andere Ergebnisse liefern als ein sonniger Tag; für einen typischen Schulweg wären mehrere Tage oder eine andere klar formulierte Frage nötig."}],"prerequisites":[]}},"taskExamples":{}},"S02":{"default":"transfer","variants":{"transfer":{"title":"Zwei Zählweisen ergeben verschiedene Prozentbasen","prerequisites":["B08","P01"],"rationale":"Kontrastiert Personenanteile und Nennungsanteile bei Mehrfachantworten, statt nur Quote aus zwei Zahlen.","blocks":[{"type":"H","value":"1. Die Erhebung klären"},{"type":"T","value":"Zehn Kinder dürfen Fußball und Schwimmen wählen, auch beides oder keines. Sechs nennen Fußball und fünf Schwimmen; drei nennen beides."},{"type":"H","value":"2. Anteile an allen Kindern berechnen"},{"type":"T","value":"Fußball nennen 60 %, Schwimmen 50 %. Die Summe darf über 100 % liegen, weil die Gruppen überlappen."},{"type":"M","value":"\\frac6{10}=60\\%,\\qquad\\frac5{10}=50\\%"},{"type":"H","value":"3. Kinder und Nennungen unterscheiden"},{"type":"T","value":"Es gibt elf Nennungen, aber nur zehn Kinder. Acht verschiedene Kinder nennen mindestens eine der beiden Sportarten; die drei Doppelzählungen werden einmal abgezogen."},{"type":"M","value":"6+5-3=8"},{"type":"H","value":"4. Die Bezugsgröße nennen"},{"type":"T","value":"6/11 wäre der Fußballanteil an allen Nennungen; 6/10 ist der Fußballanteil an allen Kindern. Beide Rechnungen beantworten unterschiedliche Fragen und dürfen nicht verwechselt werden."}]},"source-0":{"title":"Zählen und Anteile vergleichen","blocks":[{"type":"H","value":"Zählen und Anteile vergleichen"},{"type":"T","value":"20 Kinder werden nach ihrem Schulweg befragt: 8 nennen das Rad, 6 den Bus und 6 zu Fuß. Die <b>absolute Häufigkeit h</b> zählt die Antworten in einer Kategorie. Die <b>relative Häufigkeit r</b> setzt diese Anzahl ins Verhältnis zur Gesamtzahl N."},{"type":"V","value":"S02"},{"type":"M","value":"r_{\\mathrm{Rad}}=\\frac hN=\\frac8{20}=0{,}4=40\\%"},{"type":"T","value":"Wir teilen durch 20, weil alle Antworten zusammen das Ganze bilden. Für Bus und zu Fuß erhalten wir jeweils 6/20 = 0,3 = 30 %. Jede Person wurde genau einer Kategorie zugeordnet und alle Antworten sind erfasst. Deshalb müssen die absoluten Häufigkeiten 20 und die relativen 1 ergeben."},{"type":"M","value":"8+6+6=20\\qquad0{,}4+0{,}3+0{,}3=1"}],"prerequisites":["B01","D03"]},"source-1":{"title":"Eine Anzahl rückwärts finden","blocks":[{"type":"H","value":"Eine Anzahl rückwärts finden"},{"type":"T","value":"In einer anderen Gruppe von 30 Kindern fahren 40 % Rad. Wir nehmen 0,4 der Gesamtzahl: 0,4 · 30 = 12 Kinder. Derselbe relative Anteil kann also zu einer anderen absoluten Anzahl gehören."},{"type":"M","value":"h=rN=0{,}4\\cdot30=12"},{"type":"T","value":"Wenn Mehrfachantworten erlaubt sind, ergeben die Anteile nicht unbedingt 100 %. Die Summenkontrolle gilt nur für vollständige, überschneidungsfreie Kategorien. Auch der Bezugswert muss beim Vergleichen von Gruppen immer bekannt sein."}],"prerequisites":["B01","D03"]}},"taskExamples":{"S02_NEU_08":"source-1"}},"S03":{"default":"transfer","variants":{"transfer":{"title":"Säulenhöhe und Bildfläche können Unterschiedliches zeigen","prerequisites":["M03","S02"],"rationale":"Prüft eine ikonische zweidimensionale Vergrößerung statt nur abgeschnittene Achsen.","blocks":[{"type":"H","value":"1. Die Daten lesen"},{"type":"T","value":"Eine Gruppe verkauft 20 Fahrräder, eine andere 40. Der zweite Wert ist doppelt so groß."},{"type":"M","value":"40:20=2"},{"type":"H","value":"2. Ein Bildsymbol vergrößern"},{"type":"T","value":"Wird das zweite Fahrradsymbol doppelt so hoch und doppelt so breit gezeichnet, nimmt es viermal so viel Bildfläche ein."},{"type":"M","value":"2\\cdot2=4"},{"type":"H","value":"3. Den optischen Eindruck beurteilen"},{"type":"T","value":"Die Darstellung kann wie eine Vervierfachung wirken, obwohl die Verkaufszahl nur verdoppelt ist. Eine auffällige Bildfläche ist keine neue Datenmenge."},{"type":"H","value":"4. Eine eindeutige Alternative wählen"},{"type":"T","value":"Verwende gleich breite Säulen ab 0 mit Höhen 20 und 40 oder ein und zwei gleich große Fahrradsymbole. Beschrifte Daten, Einheit und Zeitraum, damit der Vergleich nachvollziehbar bleibt."}]},"source-0":{"title":"Dieselben Daten als Säulen und Kreissektoren","blocks":[{"type":"H","value":"Dieselben Daten als Säulen und Kreissektoren"},{"type":"T","value":"Von 20 Kindern wählen 10 A, 6 B und 4 C. Im <b>Säulendiagramm</b> gibt die Höhe die absolute Häufigkeit an. Alle Säulen verwenden dieselbe Skala und beginnen bei 0, damit Höhenverhältnisse die Mengenverhältnisse abbilden."},{"type":"V","value":"S03"},{"type":"T","value":"Im <b>Kreisdiagramm</b> steht der Vollwinkel 360° für alle 20 Kinder. Der <b>Sektorwinkel</b> ist daher der Anteil mal 360°. Für B rechnen wir erst 6/20 = 0,3 und nehmen dann 30 % des Vollwinkels."},{"type":"M","value":"A:\\ 180^\\circ\\qquad B:\\ \\frac6{20}\\cdot360^\\circ=108^\\circ\\qquad C:\\ 72^\\circ"},{"type":"T","value":"Zur Probe ergeben die Winkel 360°. Rückwärts entspricht ein Winkel von 72° dem Anteil 72/360 = 1/5 = 20 %. Die Gesamtzahl 20 Kinder wird benötigt, um daraus die absolute Anzahl 4 zu berechnen."}],"prerequisites":["S02","G02"]},"source-1":{"title":"Eine Skala kann Unterschiede größer erscheinen lassen","blocks":[{"type":"H","value":"Eine Skala kann Unterschiede größer erscheinen lassen"},{"type":"T","value":"Würde die senkrechte Achse eines Säulendiagramms erst bei 3 beginnen, wären die sichtbaren Höhen 7, 3 und 1. Die erste Säule wirkte siebenmal so hoch wie die dritte, obwohl 10 nur das 2,5-Fache von 4 ist. Prüfe daher Achsenanfang, Einheiten, Gesamtzahl und Beschriftungen, bevor du eine Aussage übernimmst."}],"prerequisites":["S02","G02"]}},"taskExamples":{}},"S04":{"default":"transfer","variants":{"transfer":{"title":"Eine neue Zahl kann das Mittel unverändert lassen","prerequisites":["E01","T01"],"rationale":"Rückwärtsfrage zur Invarianz des Mittels und unterschiedliche Effekte auf Modalwert/Spannweite.","blocks":[{"type":"H","value":"1. Eine Ausgangsliste untersuchen"},{"type":"T","value":"Die Zahlen 2, 4 und 9 haben Summe 15 und Mittelwert 5. Keiner der Werte muss dem Mittel entsprechen."},{"type":"M","value":"\\bar x=\\frac{2+4+9}{3}=5"},{"type":"H","value":"2. Einen vierten Wert passend wählen"},{"type":"T","value":"Das Mittel soll 5 bleiben. Mit vier Werten braucht man nun Summe 20; die neue Zahl muss also 5 sein."},{"type":"M","value":"\\frac{15+x}{4}=5\\quad\\Rightarrow\\quad x=5"},{"type":"H","value":"3. Den Grund verallgemeinern"},{"type":"T","value":"Fügt man genau den bisherigen Mittelwert hinzu, bleibt das Mittel gleich. Man fügt eine Person mit exakt durchschnittlichem Wert hinzu."},{"type":"H","value":"4. Andere Kennwerte separat prüfen"},{"type":"T","value":"Die Liste 2,4,5,9 hat weiter Spannweite 7. Noch gibt es keinen eindeutigen häufigsten Wert. Eine zweite hinzugefügte 5 macht 5 zum eindeutigen Modalwert, obwohl das Mittel weiter 5 bleibt."}]},"source-0":{"title":"Drei Kennwerte beantworten drei Fragen","blocks":[{"type":"H","value":"Drei Kennwerte beantworten drei Fragen"},{"type":"T","value":"Die Daten lauten 2, 3, 3, 4, 8. Das <b>arithmetische Mittel</b> verteilt die Summe gleichmäßig auf die fünf Werte. Der <b>Modalwert</b> ist der am häufigsten vorkommende Wert. Die <b>Spannweite</b> misst den Abstand zwischen größtem und kleinstem Wert."},{"type":"M","value":"\\bar x=\\frac{2+3+3+4+8}{5}=\\frac{20}{5}=4"},{"type":"M","value":"\\mathrm{Modalwert}=3\\qquad\\mathrm{Spannweite}=8-2=6"},{"type":"V","value":"S04"},{"type":"T","value":"Die 8 zieht den Mittelwert nach oben. Ersetzen wir sie durch den auffällig hohen Wert 18, steigt das Mittel auf 6 und die Spannweite auf 16; der Modalwert bleibt 3. Solche <b>Ausreißer</b> beeinflussen die Kennwerte verschieden stark. Es kann auch mehrere gleich häufigste Modalwerte geben."}],"prerequisites":["N02","D02"]},"source-1":{"title":"Vom Mittelwert auf einen fehlenden Wert schließen","blocks":[{"type":"H","value":"Vom Mittelwert auf einen fehlenden Wert schließen"},{"type":"T","value":"Vier Zahlen haben das Mittel 5. Ihre Summe muss daher 4 · 5 = 20 sein. Sind drei Zahlen 2, 4 und 6 bekannt, bleibt für die vierte 20 − 12 = 8."},{"type":"M","value":"x=4\\cdot5-(2+4+6)=8"},{"type":"T","value":"Die Probe berechnet das Mittel aller vier Zahlen erneut. Nur den Mittelwert von den bekannten Zahlen abzuziehen würde die Anzahl der Datenwerte übersehen."}],"prerequisites":["N02","D02"]}},"taskExamples":{}},"S05":{"default":"transfer","variants":{"transfer":{"title":"Gleicher Mittelwert und gleiche Spannweite reichen nicht","prerequisites":["S04","S02"],"rationale":"Zeigt verborgen unterschiedliche Häufigkeitsverteilungen bei identischen Kennwerten und Gruppengröße.","blocks":[{"type":"H","value":"1. Zwei gleich große Gruppen ansehen"},{"type":"T","value":"A: 0,0,4,4,8,8. B: 0,4,4,4,4,8. Beide enthalten sechs Werte."},{"type":"H","value":"2. Mittel und Spannweite berechnen"},{"type":"T","value":"Beide Summen sind 24, beide Mittelwerte 4. Beide reichen von 0 bis 8 und haben Spannweite 8."},{"type":"M","value":"\\bar x_A=\\bar x_B=24:6=4,\\qquad R_A=R_B=8"},{"type":"H","value":"3. Die Verteilung direkt vergleichen"},{"type":"T","value":"In A liegt nur ein Drittel genau bei 4; in B liegen vier von sechs Werten dort. Gleiche Mittelwerte und Spannweiten verdecken hier die Häufung in der Mitte."},{"type":"M","value":"\\frac26\\ne\\frac46"},{"type":"H","value":"4. Das Urteil begrenzen"},{"type":"T","value":"Für die Aussage „Die Gruppen sind gleich verteilt“ reichen diese Kennwerte nicht. Eine Häufigkeitstabelle oder Punktdarstellung zeigt den Unterschied."}]},"source-0":{"title":"Gleicher Durchschnitt – ganz andere Gruppen","blocks":[{"type":"H","value":"Gleicher Durchschnitt – ganz andere Gruppen"},{"type":"T","value":"Gruppe A hat die Werte 4, 4, 4, 4, 4; Gruppe B die Werte 0, 2, 4, 6, 8. Beide Summen sind 20, beide Gruppen enthalten fünf Werte. Deshalb ist der Mittelwert bei beiden 4."},{"type":"V","value":"S05"},{"type":"M","value":"\\bar x_A=\\bar x_B=4\\qquad R_A=0;\\quad R_B=8"},{"type":"T","value":"Die <b>Verteilung</b> beschreibt, wie häufig welche Werte vorkommen. In A sind alle gleich, in B sind sie weit verteilt. Diese Verschiedenheit nennen wir unterschiedliche <b>Streuung</b>; hier macht sie die Spannweite R sichtbar. Der gleiche Mittelwert verschweigt sie."}],"prerequisites":["S03","S04"]},"source-1":{"title":"Eine Behauptung mit einem Gegenbeispiel prüfen","blocks":[{"type":"H","value":"Eine Behauptung mit einem Gegenbeispiel prüfen"},{"type":"T","value":"Die Behauptung „Gruppen mit gleichem Mittelwert haben dieselben Daten“ ist widerlegt: A und B sind ein <b>Gegenbeispiel</b>. Ein einziges passendes Gegenbeispiel genügt, um eine allgemeine Behauptung zu widerlegen."},{"type":"T","value":"Auch Mittelwert und Spannweite zusammen verraten nicht alles. Die Daten 0, 3, 4, 5, 8 haben ebenfalls Mittelwert 4 und Spannweite 8, sind aber anders verteilt als B. Jeder Kennwert fasst zusammen und verliert dabei Informationen. Für einen fairen Vergleich betrachten wir daher möglichst auch Einzelwerte oder eine Darstellung ihrer Häufigkeiten."}],"prerequisites":["S03","S04"]}},"taskExamples":{"S05_NEU_06":"source-0"}},"W01":{"default":"transfer","variants":{"transfer":{"title":"Ein Ereignis kann auf verschiedene Beschreibungen passen","prerequisites":["N03","B01"],"rationale":"Nutzt Schnitt und Vereinigung zweier Würfelereignisse zur Trennung von Ergebnis und Bedingung.","blocks":[{"type":"H","value":"1. Zwei Ereignisse festlegen"},{"type":"T","value":"Beim normalen Würfel bedeutet A „gerade“, B „größer als 3“. Beide sind Mengen möglicher Einzelergebnisse."},{"type":"M","value":"A=\\{2,4,6\\},\\qquad B=\\{4,5,6\\}"},{"type":"H","value":"2. „Und“ als gemeinsamen Teil lesen"},{"type":"T","value":"Für „gerade und größer als 3“ müssen beide Bedingungen zugleich erfüllt sein. Das gilt für 4 und 6."},{"type":"M","value":"A\\cap B=\\{4,6\\}"},{"type":"H","value":"3. „Oder“ ohne Doppelzählung lesen"},{"type":"T","value":"Für „gerade oder größer als 3“ genügt mindestens eine Bedingung. 4 und 6 werden trotzdem jeweils nur einmal in der Ergebnismenge notiert."},{"type":"M","value":"A\\cup B=\\{2,4,5,6\\}"},{"type":"H","value":"4. Einen konkreten Wurf zuordnen"},{"type":"T","value":"Die Augenzahl 4 ist ein einzelnes Ergebnis, das gleichzeitig in A und B liegt. Zwei passende Beschreibungen machen daraus nicht zwei verschiedene Würfelergebnisse."}]},"source-0":{"title":"Ein Wurf und eine Menge passender Ausgänge","blocks":[{"type":"H","value":"Ein Wurf und eine Menge passender Ausgänge"},{"type":"T","value":"Ein Würfelwurf ist ein <b>Zufallsversuch</b>: Mögliche Ausgänge sind bekannt, der einzelne Ausgang steht vorher nicht fest. Ein <b>Ergebnis</b> ist etwa die Augenzahl 4. Die <b>Ergebnismenge Ω</b> („Omega“) enthält alle möglichen Ergebnisse."},{"type":"M","value":"\\Omega=\\{1;2;3;4;5;6\\}"},{"type":"V","value":"W01"},{"type":"T","value":"Das <b>Ereignis E</b> „gerade Augenzahl“ enthält die passenden Ergebnisse 2, 4 und 6. Es tritt ein, wenn das tatsächlich gewürfelte Ergebnis zu dieser Menge gehört. Ein Ereignis ist also eine Menge von Ergebnissen, nicht nur ein Wort für einen einzelnen Wurf."},{"type":"M","value":"E=\\{2;4;6\\}\\subseteq\\Omega"},{"type":"T","value":"„Augenzahl kleiner als 7“ ist ein <b>sicheres Ereignis</b>: Es enthält ganz Ω. „Augenzahl 8“ ist <b>unmöglich</b>: Die passende Menge ist leer, geschrieben ∅. Auch ein Ereignis mit nur einem Ergebnis, etwa {4}, ist eine Menge."}],"prerequisites":["S02"]},"source-1":{"title":"Bei zwei Würfen zählt die Reihenfolge","blocks":[{"type":"H","value":"Bei zwei Würfen zählt die Reihenfolge"},{"type":"T","value":"Werfen wir zweimal eine Münze, können Ergebnisse als Paare notiert werden: KK, KZ, ZK, ZZ. KZ und ZK sind verschieden. Das Ereignis „genau einmal Kopf“ enthält beide. Die Art, wie Ergebnisse beschrieben werden, muss zum Versuch passen."},{"type":"M","value":"E_{\\mathrm{einmal\\ Kopf}}=\\{KZ;ZK\\}"}],"prerequisites":["S02"]}},"taskExamples":{}},"W02":{"default":"transfer","variants":{"transfer":{"title":"Zwei Farben können dieselbe Chance trotz verschiedener Kugelzahl haben","prerequisites":["B02","B08","F01"],"rationale":"Vergleicht Urnen verschiedener Gesamtgrößen und erklärt invariantes Verhältnis bei Skalierung.","blocks":[{"type":"H","value":"1. Zwei Beutel vergleichen"},{"type":"T","value":"A enthält 2 rote und 3 blaue, B enthält 6 rote und 9 blaue gleichartige Kugeln. B hat mehr rote Kugeln, aber auch mehr Kugeln insgesamt."},{"type":"H","value":"2. Die Chancen auf dieselbe Bezugsgröße bringen"},{"type":"T","value":"P(Rot) ist in A 2/5 und in B 6/15. Kürzen zeigt denselben Anteil."},{"type":"M","value":"\\frac6{15}=\\frac25"},{"type":"H","value":"3. Die Skalierung verstehen"},{"type":"T","value":"Alle Farbanzahlen wurden mit 3 multipliziert. Zähler und Nenner wachsen gemeinsam; die Wahrscheinlichkeit bleibt 40 %."},{"type":"H","value":"4. Eine andere Veränderung unterscheiden"},{"type":"T","value":"Legt man nur rote Kugeln dazu, wächst ihr Anteil. Eine größere absolute Anzahl allein sagt deshalb ohne Gesamtzahl noch nicht, welche Chance größer ist."}]},"source-0":{"title":"Zählen funktioniert nur bei gleichen Chancen","blocks":[{"type":"H","value":"Zählen funktioniert nur bei gleichen Chancen"},{"type":"T","value":"Bei einem idealen fairen Würfel sind alle sechs Augenzahlen gleich wahrscheinlich. Das ist ein <b>Laplace-Versuch</b>. Für E = „Augenzahl mindestens 5“ sind 5 und 6 günstig. „Günstig“ heißt nur: zum Ereignis passend, nicht persönlich erwünscht."},{"type":"M","value":"P(E)=\\frac{2}{6}=\\frac13"},{"type":"V","value":"W02"},{"type":"T","value":"Das <b>Gegenereignis</b> enthält alle Ergebnisse, bei denen E nicht eintritt: hier 1, 2, 3, 4. E und sein Gegenereignis schließen sich aus und decken zusammen alle Möglichkeiten ab. Daher ergänzen sich ihre Wahrscheinlichkeiten zu 1."},{"type":"M","value":"P(\\overline E)=1-P(E)=1-\\frac13=\\frac23"}],"prerequisites":["W01","B04"]},"source-1":{"title":"Die Kategorien sind nicht immer gleich wahrscheinlich","blocks":[{"type":"H","value":"Die Kategorien sind nicht immer gleich wahrscheinlich"},{"type":"T","value":"In einem Beutel liegen 3 gleichartige rote und 1 blaue Kugel. Die vier einzelnen Kugeln seien gleich wahrscheinlich. Die beiden Farben sind es nicht: Rot kann auf drei Arten entstehen, Blau nur auf eine. Deshalb ist P(Rot) = 3/4 und nicht 1/2."},{"type":"M","value":"P(\\mathrm{Rot})=\\frac34\\qquad P(\\mathrm{Blau})=\\frac14"},{"type":"T","value":"Prüfe vor „günstig durch möglich“, ob deine gezählten Einzelergebnisse gleiche Chancen haben. Zwei Farbnamen oder zwei Möglichkeiten allein reichen als Begründung für jeweils 50 % nicht aus."}],"prerequisites":["W01","B04"]}},"taskExamples":{}},"W03":{"default":"transfer","variants":{"transfer":{"title":"Eine Trefferquote kann mit mehr Versuchen zunächst schlechter passen","prerequisites":["B08","W02"],"rationale":"Konkreter nichtmonotoner Fortsetzungsvergleich mit demselben Anfangszustand; unterscheidet Einzelwirkung und langfristige Aussage.","blocks":[{"type":"H","value":"1. Die Ausgangsquote festhalten"},{"type":"T","value":"Nach zehn Würfen einer fairen Münze gab es genau fünf Köpfe. Die beobachtete Quote stimmt gerade mit der Modellchance 1/2 überein."},{"type":"M","value":"r=5/10=1/2"},{"type":"H","value":"2. Einen weiteren Kopf hinzufügen"},{"type":"T","value":"Nach Kopf beträgt die Quote 6/11, also etwa 54,5 %. Der Abstand von 50 % ist größer geworden, obwohl mehr Daten vorliegen."},{"type":"M","value":"r_{\\mathrm{neu}}=\\frac6{11}>\\frac12"},{"type":"H","value":"3. Auch die andere Fortsetzung prüfen"},{"type":"T","value":"Nach Zahl wäre die Quote 5/11, also etwa 45,5 %. Auch das entfernt sie von der zuvor exakten Hälfte."},{"type":"M","value":"\\frac5{11}<\\frac12"},{"type":"H","value":"4. Die langfristige Aussage richtig lesen"},{"type":"T","value":"Mehr Versuche garantieren nicht nach jedem einzelnen Schritt eine bessere Annäherung. Stabilisierung über lange Serien ist keine Pflicht zu einem sofortigen Ausgleich; der nächste unabhängige Wurf bleibt fair."}]},"source-0":{"title":"Ein Modell macht eine Aussage über Chancen","blocks":[{"type":"H","value":"Ein Modell macht eine Aussage über Chancen"},{"type":"T","value":"Eine ideale faire Münze hat im Modell die <b>Wahrscheinlichkeit</b> P(Kopf) = 1/2. In 20 tatsächlichen Würfen beobachten wir 13-mal Kopf. Die <b>relative Häufigkeit</b> beschreibt diese Daten, also Trefferzahl geteilt durch Versuchszahl."},{"type":"M","value":"r_{20}(K)=\\frac{13}{20}=0{,}65\\qquad P(K)=0{,}5"},{"type":"V","value":"W03"},{"type":"T","value":"0,65 und 0,5 widersprechen sich nicht automatisch: Ein Zufallsversuch schwankt. Das Modell fordert nicht exakt zehnmal Kopf in jeweils 20 Würfen. Bei vielen unabhängigen Wiederholungen liegt die relative Häufigkeit häufig näher an der Modellwahrscheinlichkeit; sie nähert sich aber nicht bei jedem einzelnen neuen Wurf stetig an."}],"prerequisites":["W01","S02"]},"source-1":{"title":"Der nächste Wurf gleicht nichts absichtlich aus","blocks":[{"type":"H","value":"Der nächste Wurf gleicht nichts absichtlich aus"},{"type":"T","value":"Nach 13-mal Kopf in 20 Würfen bleibt beim fairen unabhängigen nächsten Wurf P(Kopf) = 1/2. Die Münze hat kein Gedächtnis und muss nicht „aufholen“. Kopf im nächsten Wurf ergibt 14/21 ≈ 0,667; Zahl ergibt 13/21 ≈ 0,619."},{"type":"M","value":"\\frac{14}{21}\\approx0{,}667\\qquad\\frac{13}{21}\\approx0{,}619"},{"type":"T","value":"Die Häufigkeit kann sich also vom Wert 0,5 entfernen oder ihm nähern. Um ein Modell anhand von Daten zu beurteilen, betrachten wir viele Versuche und die Versuchsanordnung; eine kleine Abweichung allein beweist keine manipulierte Münze."}],"prerequisites":["W01","S02"]}},"taskExamples":{"W03_POOL_04":"source-1","W03_NEU_08":"source-1","W03_NEU_06":"source-0"}},"W04":{"default":"transfer","variants":{"transfer":{"title":"Dieselbe Farbe kann nach anderer Vorgeschichte andere Chancen haben","prerequisites":["W02","B08"],"rationale":"Vergleicht zwei unterschiedliche Knoten derselben Stufe ohne Zurücklegen und ihre bedingte Bedeutung.","blocks":[{"type":"H","value":"1. Die Anfangsfüllung festlegen"},{"type":"T","value":"In einer Urne liegen 2 rote und 2 blaue Kugeln. Es wird dreimal ohne Zurücklegen gezogen. Vor jedem Zug zählt die jeweils tatsächlich verbliebene Füllung."},{"type":"H","value":"2. Nach zweimal Rot zählen"},{"type":"T","value":"Nach RR bleiben 0 rote und 2 blaue Kugeln. Im dritten Zug ist Blau sicher und Rot unmöglich."},{"type":"M","value":"P(R\\mid RR)=0,\\qquad P(B\\mid RR)=1"},{"type":"H","value":"3. Nach Rot und Blau zählen"},{"type":"T","value":"Nach RB bleiben 1 rote und 1 blaue Kugel. Jetzt hat jede Farbe im dritten Zug Chance 1/2."},{"type":"M","value":"P(R\\mid RB)=\\frac12,\\qquad P(B\\mid RB)=\\frac12"},{"type":"H","value":"4. Die Knoten getrennt lesen"},{"type":"T","value":"Obwohl beide Situationen zur dritten Stufe gehören, unterscheiden sich die Chancen. Jeder Knoten bedeutet eine bestimmte Vorgeschichte; die Summe seiner vollständigen Fortsetzungen bleibt jeweils 1."}]},"source-0":{"title":"Zwei Züge – die Urne nach jedem Zug neu betrachten","blocks":[{"type":"H","value":"Zwei Züge – die Urne nach jedem Zug neu betrachten"},{"type":"T","value":"In einer Urne liegen 2 rote und 1 blaue gleichartige Kugel. Wir ziehen zweimal. Ein <b>Baumdiagramm</b> ordnet den Ablauf: Jede <b>Stufe</b> ist ein Zug, jeder <b>Zweig</b> ein möglicher Ausgang. Ein <b>Knoten</b> zeigt, nach welchen bisherigen Ergebnissen weitergezogen wird."},{"type":"V","value":"W04"},{"type":"T","value":"Im ersten Zug ist P(R) = 2/3 und P(B) = 1/3. <b>Mit Zurücklegen</b> liegen vor dem zweiten Zug wieder 2 rote und 1 blaue Kugel in der Urne. Deshalb stehen an beiden Knoten erneut die Wahrscheinlichkeiten 2/3 und 1/3."},{"type":"T","value":"<b>Ohne Zurücklegen</b> hängt der zweite Zug vom ersten ab. Nach Rot verbleiben 1 rote und 1 blaue Kugel: jeweils 1/2. Nach Blau verbleiben 2 rote Kugeln: Rot hat Wahrscheinlichkeit 1, Blau 0. Der Zweig mit 0 macht das unmögliche Ergebnis BB sichtbar."},{"type":"M","value":"\\frac23+\\frac13=1\\qquad\\frac12+\\frac12=1\\qquad1+0=1"},{"type":"T","value":"Die <b>Zweigsumme</b> muss an jedem Knoten 1 sein, weil von dort genau eine der vollständigen Möglichkeiten eintritt. Der Nenner im zweiten Zug ohne Zurücklegen ist 2, nicht 3: Es sind nur noch zwei Kugeln da."}],"prerequisites":["W01","B01"]}},"taskExamples":{"W04_H":"source-0"}},"W05":{"default":"transfer","variants":{"transfer":{"title":"Überlappende Ereignisse darf man nicht einfach addieren","prerequisites":["W01","W02","B04"],"rationale":"Grenze der Summenregel anhand überlappender Ereignisse; vollständige Pfade statt Signalwortheuristik.","blocks":[{"type":"H","value":"1. Zwei Ereignisse bei zwei Münzwürfen wählen"},{"type":"T","value":"Eine faire Münze wird zweimal unabhängig geworfen. A bedeutet „erster Wurf Kopf“, B bedeutet „zweiter Wurf Kopf“. Die vier geordneten Ergebnisse KK, KZ, ZK, ZZ haben je Wahrscheinlichkeit 1/4."},{"type":"H","value":"2. Einzelchancen bestimmen"},{"type":"T","value":"A umfasst KK und KZ, B umfasst KK und ZK. Daher hat jedes Ereignis Wahrscheinlichkeit 1/2."},{"type":"M","value":"P(A)=P(B)=\\frac12"},{"type":"H","value":"3. Die Überschneidung erkennen"},{"type":"T","value":"Für „A oder B“ passt KK nur einmal. Einfach 1/2 + 1/2 würde KK doppelt zählen. Die passenden vollständigen Pfade sind KK, KZ und ZK."},{"type":"M","value":"P(A\\cup B)=\\frac14+\\frac14+\\frac14=\\frac34"},{"type":"H","value":"4. Eine Kontrollrechnung nutzen"},{"type":"T","value":"Das Gegenereignis ist ZZ mit Chance 1/4. Also ergibt sich erneut 1 − 1/4 = 3/4. Beim Addieren müssen die verwendeten Alternativen sich ausschließen oder ihre Überschneidung muss berücksichtigt werden."}]},"source-0":{"title":"Eine günstige Reihenfolge ist noch nicht das ganze Ereignis","blocks":[{"type":"H","value":"Eine günstige Reihenfolge ist noch nicht das ganze Ereignis"},{"type":"T","value":"Wir werfen zweimal eine faire Münze. Ein vollständiger <b>Pfad</b> beschreibt eine Reihenfolge, etwa KZ. Die Wahrscheinlichkeit entlang eines Pfades entsteht durch Multiplikation der Zweigwahrscheinlichkeiten: die <b>Produktregel</b>."},{"type":"V","value":"W05"},{"type":"M","value":"P(KZ)=\\frac12\\cdot\\frac12=\\frac14"},{"type":"T","value":"„<b>Genau</b> einmal Kopf“ besteht aus zwei verschiedenen Pfaden, KZ und ZK. Sie können nicht gleichzeitig das Ergebnis desselben Versuches sein. Deshalb addieren wir ihre Wahrscheinlichkeiten mit der <b>Summenregel</b>."},{"type":"M","value":"P(\\mathrm{genau\\ einmal\\ K})=\\frac14+\\frac14=\\frac12"},{"type":"T","value":"„<b>Mindestens</b> einmal Kopf“ schließt auch KK ein. Wir addieren drei Pfade oder rechnen über das Gegenereignis „kein Kopf“, also ZZ. Das zweite Vorgehen ist kürzer, weil nur ein ungünstiger Pfad übrig bleibt."},{"type":"M","value":"P(\\mathrm{mindestens\\ einmal\\ K})=1-P(ZZ)=1-\\frac14=\\frac34"},{"type":"T","value":"Entlang eines Pfades wird multipliziert, zwischen verschiedenen günstigen vollständigen Pfaden addiert. Zähle keinen Pfad doppelt. Bei anderen Versuchen müssen die Wahrscheinlichkeiten am jeweiligen Knoten passen; bei Ziehen ohne Zurücklegen ändern sie sich oft."}],"prerequisites":["W04","B04","B06"]},"extra-three-stage":{"title":"Drei Versuche, genau zwei Treffer","prerequisites":["W04","B04","B06"],"rationale":"Dreistufige Pfadstruktur und genau-zwei-Ereignis statt der zweistufigen mindestens-einmal-Kopf-Aufgabe.","blocks":[{"type":"H","value":"Drei Versuche, genau zwei Treffer"},{"type":"T","value":"Ein Spiel hat bei jedem Versuch unabhängig Trefferchance 1/3. Es wird dreimal gespielt. Berechne die Chance für genau zwei Treffer."},{"type":"H","value":"1. Die passenden Reihenfolgen sammeln"},{"type":"T","value":"Mit T für Treffer und F für Fehlschlag sind TTF, TFT und FTT günstig. TTT gehört nicht dazu, denn drei Treffer sind nicht genau zwei."},{"type":"H","value":"2. Einen vollständigen Pfad berechnen"},{"type":"M","value":"P(TTF)=\\frac13\\cdot\\frac13\\cdot\\frac23=\\frac2{27}"},{"type":"T","value":"Die drei Faktoren gehören zu drei nacheinander eintretenden Bedingungen. Wegen gleicher unabhängiger Einzelchancen haben die anderen beiden günstigen Pfade denselben Wert."},{"type":"H","value":"3. Verschiedene vollständige Pfade addieren"},{"type":"M","value":"P(\\text{genau zwei Treffer})=\\frac2{27}+\\frac2{27}+\\frac2{27}=\\frac29"},{"type":"T","value":"Ein Spielverlauf kann nicht gleichzeitig TTF und TFT sein. Deshalb dürfen ihre Wahrscheinlichkeiten addiert werden. Innerhalb eines Pfades wird dagegen multipliziert."}]}},"taskExamples":{"W05_TEST_01":"extra-three-stage","W05_NEU_01":"extra-three-stage","W05_NEU_06":"extra-three-stage"}},"W06":{"default":"transfer","variants":{"transfer":{"title":"Gleich große Gruppen durch Verwerfen erzeugen","prerequisites":["W02","W03"],"rationale":"Zeigt warum Ablehnungssampling bedingt fair bleibt und verworfene Zufallszahlen keine Fehlschläge sind.","blocks":[{"type":"H","value":"1. Drei gleich wahrscheinliche Ergebnisse simulieren"},{"type":"T","value":"Ein Zufallsgenerator liefert bei jeder unabhängigen Ziehung jede Ziffer 0 bis 9 gleich wahrscheinlich. Gesucht sind drei gleich wahrscheinliche Ausgänge A, B, C. Zehn lässt sich nicht gleichmäßig in drei ganze Gruppen teilen."},{"type":"H","value":"2. Eine feste Verwerfungsregel setzen"},{"type":"T","value":"Ordne 0,1,2 zu A, 3,4,5 zu B und 6,7,8 zu C. Bei 9 wird neu gezogen, bis eine gültige Ziffer kommt."},{"type":"H","value":"3. Nur gültige Ergebnisse vergleichen"},{"type":"T","value":"Unter den neun gültigen Ziffern entfallen auf jeden Ausgang drei. Eine verworfene 9 ist kein eigener Ausgang und kein Fehlschlag des simulierten Versuchs."},{"type":"M","value":"P(A\\mid\\text{gültig})=\\frac39=\\frac13"},{"type":"H","value":"4. Versuche sauber protokollieren"},{"type":"T","value":"Ein simulierter Versuch endet erst mit einem gültigen Ausgang. Berichte die Zuordnung und gegebenenfalls auch die verworfenen Ziffern. Die Regel bleibt fest; nachträgliches Weglassen nur unerwünschter Ergebnisse wäre etwas anderes."}]},"source-0":{"title":"Eine Trefferchance von 30 Prozent nachbilden","blocks":[{"type":"H","value":"Eine Trefferchance von 30 Prozent nachbilden"},{"type":"T","value":"Eine <b>Simulation</b> ersetzt einen realen Zufallsvorgang durch ein passendes Zufallsmodell. Wir wollen eine Trefferchance von 30 % darstellen. Ein Zufallszahlengenerator liefert die ganzen Zahlen 0 bis 9 unabhängig und gleich wahrscheinlich. Wir ordnen 0, 1, 2 einem Treffer und 3 bis 9 einem Fehlschlag zu."},{"type":"V","value":"W06"},{"type":"M","value":"P(\\mathrm{Treffer})=\\frac3{10}=0{,}3"},{"type":"T","value":"Die Zuordnung trifft die gewünschte Chance, weil 3 von 10 gleich wahrscheinlichen Zahlen günstig sind. Ein einzelner Versuch ist genau eine gezogene Zahl. Wir führen 100 Versuche durch und protokollieren die Treffer; die Regel wird währenddessen nicht verändert."}],"prerequisites":["W03","W04"]},"source-1":{"title":"Die Simulation auswerten","blocks":[{"type":"H","value":"Die Simulation auswerten"},{"type":"T","value":"Angenommen, wir erhalten 27 Treffer. Die relative Häufigkeit ist 27/100 = 0,27. Das ist das beobachtete Ergebnis dieser Serie, nicht eine Änderung der festgelegten Modellwahrscheinlichkeit 0,3."},{"type":"M","value":"r_{100}(T)=\\frac{27}{100}=27\\%"},{"type":"T","value":"Eine neue Serie kann anders ausfallen. Mehr unabhängige Versuche machen den Zufall nicht weg, können aber eine stabilere Schätzung liefern. Außerdem hängt die Aussage vom Modell ab: Die Simulation prüft nicht, ob eine reale Person wirklich eine konstante Trefferchance von 30 % hat. Dazu wären reale Daten und passende Annahmen nötig."}],"prerequisites":["W03","W04"]}},"taskExamples":{"W06_POOL_01":"source-0"}}};
